| public      | audit_balance_consistency           | p_user_id uuid                                                                                                                                                                    | TABLE(user_id uuid, asset_symbol text, issue_type text, recorded_balance numeric, expected_balance numeric, discrepancy numeric)                                                                                                                                                                                                                                                                                                                                                                                | CREATE OR REPLACE FUNCTION public.audit_balance_consistency(p_user_id uuid DEFAULT NULL::uuid)<br> RETURNS TABLE(user_id uuid, asset_symbol text, issue_type text, recorded_balance numeric, expected_balance numeric, discrepancy numeric)<br> LANGUAGE plpgsql<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    WITH computed AS (<br>        SELECT<br>            t.user_id,<br>            t.asset_symbol,<br>            SUM(<br>                CASE<br>                    WHEN t.type IN (<br>                        'deposit', 'staking_reward', 'unstake_completed', 'unstake',<br>                        'instant_unstake', 'game_win', 'referral_bonus', 'cashback', 'refund',<br>                        'dividend_payment', 'lending_reward', 'balance_adjustment',<br>                        'loan_borrowed', 'loan_collateral_release'<br>                    ) THEN t.amount<br>                    WHEN t.type IN (<br>                        'withdrawal', 'staking', 'staking_lock', 'stake', 'game_bet',<br>                        'wakati_purchase', 'fee', 'platform_fee', 'burn', 'airtime_purchase',<br>                        'admin_reclaim',<br>                        'loan_collateral_lock', 'loan_repaid', 'loan_liquidated'<br>                    ) THEN -t.amount<br>                    WHEN t.type = 'swap_debit'   THEN -t.amount<br>                    WHEN t.type = 'swap_credit'  THEN  t.amount<br>                    WHEN t.type = 'p2p_transfer' THEN<br>                        CASE WHEN t.amount > 0 THEN t.amount ELSE -ABS(t.amount) END<br>                    ELSE 0<br>                END<br>            ) AS computed_available<br>        FROM public.transactions t<br>        WHERE t.status = 'completed'<br>          AND (p_user_id IS NULL OR t.user_id = p_user_id)<br>        GROUP BY t.user_id, t.asset_symbol<br>    )<br>    SELECT<br>        ub.user_id,<br>        ub.asset_symbol,<br>        'balance_mismatch'::text                            AS issue_type,<br>        ROUND(ub.available_balance, 8)                      AS recorded_balance,<br>        ROUND(COALESCE(c.computed_available, 0), 8)         AS expected_balance,<br>        ROUND(ub.available_balance - COALESCE(c.computed_available, 0), 8) AS discrepancy<br>    FROM public.user_balances ub<br>    LEFT JOIN computed c<br>           ON c.user_id = ub.user_id AND c.asset_symbol = ub.asset_symbol<br>    WHERE ABS(ub.available_balance - COALESCE(c.computed_available, 0)) > 0.00000001<br>      AND (p_user_id IS NULL OR ub.user_id = p_user_id)<br>    ORDER BY ABS(ub.available_balance - COALESCE(c.computed_available, 0)) DESC;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              |
| public      | audit_platform_asset_balance        | p_asset_symbol text                                                                                                                                                               | TABLE(asset text, calc_balance numeric, recorded_balance numeric, diff numeric, net_position numeric, is_balanced boolean)                                                                                                                                                                                                                                                                                                                                                                                      | CREATE OR REPLACE FUNCTION public.audit_platform_asset_balance(p_asset_symbol text)<br> RETURNS TABLE(asset text, calc_balance numeric, recorded_balance numeric, diff numeric, net_position numeric, is_balanced boolean)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    WITH user_sum AS (<br>        SELECT<br>            COALESCE(SUM(available_balance), 0) AS total_available,<br>            COALESCE(SUM(staking_balance), 0)   AS total_staking<br>        FROM user_balances<br>        WHERE asset_symbol = p_asset_symbol<br>    ),<br>    metrics AS (<br>        SELECT<br>            sam.total_user_balance,<br>            sam.net_position AS m_net_position<br>        FROM supported_assets_metrics sam<br>        WHERE sam.asset_symbol = p_asset_symbol<br>    )<br>    SELECT<br>        p_asset_symbol,<br>        (us.total_available + us.total_staking),<br>        m.total_user_balance,<br>        (us.total_available + us.total_staking) - m.total_user_balance,<br>        m.m_net_position,<br>        ABS((us.total_available + us.total_staking) - m.total_user_balance) < 0.00000001<br>    FROM user_sum us, metrics m;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       |
| public      | buy_wakati_with_asset               | p_user_id uuid, p_from_asset_symbol text, p_from_amount numeric, p_wakati_amount numeric, p_exchange_rate numeric, p_fee_percentage numeric                                       | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.buy_wakati_with_asset(p_user_id uuid, p_from_asset_symbol text, p_from_amount numeric, p_wakati_amount numeric, p_exchange_rate numeric, p_fee_percentage numeric DEFAULT 0.5)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_fee_amount             numeric;<br>  v_base_amount            numeric;<br>  v_total_debit            numeric;<br>  v_user_from_balance      numeric;<br>  v_treasury_wakati_before numeric;<br>  v_treasury_from_before   numeric;<br>  v_transaction_id         uuid;<br>BEGIN<br>  IF auth.uid() IS DISTINCT FROM p_user_id THEN<br>    RETURN jsonb_build_object('success', false, 'message', 'Non autorisé', 'error_code', 'FORBIDDEN');<br>  END IF;<br><br>  IF p_from_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'message', 'Montant asset invalide', 'error_code', 'INVALID_AMOUNT');<br>  END IF;<br>  IF p_wakati_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'message', 'Montant WAKATI invalide', 'error_code', 'INVALID_AMOUNT');<br>  END IF;<br>  IF p_from_asset_symbol = 'WAKATI' THEN<br>    RETURN jsonb_build_object('success', false, 'message', 'Impossible d''acheter WAKATI avec WAKATI', 'error_code', 'INVALID_ASSET');<br>  END IF;<br><br>  v_base_amount := p_from_amount;<br>  v_fee_amount  := ROUND(v_base_amount * (p_fee_percentage / 100), 8);<br>  v_total_debit := v_base_amount + v_fee_amount;<br><br>  SELECT available_balance INTO v_user_from_balance<br>  FROM user_balances WHERE user_id = p_user_id AND asset_symbol = p_from_asset_symbol FOR UPDATE;<br><br>  IF NOT FOUND OR v_user_from_balance < v_total_debit THEN<br>    RETURN jsonb_build_object('success', false, 'message', 'Solde insuffisant pour ' \|\| p_from_asset_symbol, 'error_code', 'INSUFFICIENT_BALANCE');<br>  END IF;<br><br>  SELECT balance INTO v_treasury_wakati_before FROM treasury_wallets WHERE asset_symbol = 'WAKATI' FOR UPDATE;<br>  IF NOT FOUND OR v_treasury_wakati_before < p_wakati_amount THEN<br>    RETURN jsonb_build_object('success', false, 'message', 'Liquidité WAKATI insuffisante', 'error_code', 'TREASURY_INSUFFICIENT_WAKATI');<br>  END IF;<br><br>  -- Debit utilisateur (actif source, base + frais)<br>  UPDATE user_balances SET available_balance = available_balance - v_total_debit, updated_at = now()<br>  WHERE user_id = p_user_id AND asset_symbol = p_from_asset_symbol;<br><br>  -- Credit utilisateur (WAKATI)<br>  INSERT INTO user_balances (user_id, asset_symbol, available_balance, updated_at)<br>  VALUES (p_user_id, 'WAKATI', p_wakati_amount, now())<br>  ON CONFLICT (user_id, asset_symbol) DO UPDATE<br>  SET available_balance = user_balances.available_balance + p_wakati_amount, updated_at = now();<br><br>  -- Tresorerie absorbe la part hors-frais de l'actif source<br>  SELECT balance INTO v_treasury_from_before FROM treasury_wallets WHERE asset_symbol = p_from_asset_symbol FOR UPDATE;<br>  IF FOUND THEN<br>    UPDATE treasury_wallets SET balance = balance + v_base_amount, updated_at = now() WHERE asset_symbol = p_from_asset_symbol;<br>  ELSE<br>    INSERT INTO treasury_wallets (asset_symbol, balance, total_collected, total_burned, total_withdrawn, updated_at)<br>    VALUES (p_from_asset_symbol, v_base_amount, v_base_amount, 0, 0, now());<br>    v_treasury_from_before := 0;<br>  END IF;<br><br>  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)<br>  VALUES (p_from_asset_symbol, 'wakati_sale', v_base_amount, v_treasury_from_before, v_treasury_from_before + v_base_amount,<br>          p_user_id, 'Achat WAKATI - actif recu (hors frais)');<br><br>  -- Tresorerie debite les WAKATI emis vers le user<br>  UPDATE treasury_wallets SET balance = balance - p_wakati_amount, total_withdrawn = total_withdrawn + p_wakati_amount, updated_at = now()<br>  WHERE asset_symbol = 'WAKATI';<br><br>  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)<br>  VALUES ('WAKATI', 'wakati_sale', p_wakati_amount, v_treasury_wakati_before, v_treasury_wakati_before - p_wakati_amount,<br>          p_user_id, 'Achat WAKATI - WAKATI emis');<br><br>  -- Frais reels (part separee, ajoutee a la tresorerie + platform_fees via la fonction commune)<br>  IF v_fee_amount > 0 THEN<br>    PERFORM collect_fee_to_platform(p_from_asset_symbol, v_fee_amount, 'wakati_purchase_fee', p_user_id, NULL);<br>  END IF;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (p_user_id, 'buy_wakati', 'WAKATI', p_wakati_amount, p_wakati_amount, 'completed', now(),<br>    jsonb_build_object('from_asset', p_from_asset_symbol, 'from_amount_total', v_total_debit,<br>                        'base_amount', v_base_amount, 'fee_amount', v_fee_amount,<br>                        'fee_percentage', p_fee_percentage, 'exchange_rate', p_exchange_rate))<br>  RETURNING id INTO v_transaction_id;<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'transaction_id', v_transaction_id, 'from_asset', p_from_asset_symbol,<br>    'from_amount_total', v_total_debit, 'base_amount', v_base_amount, 'fee_amount', v_fee_amount,<br>    'fee_percentage', p_fee_percentage, 'wakati_credited', p_wakati_amount, 'exchange_rate', p_exchange_rate<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'message', SQLERRM, 'error_code', 'INTERNAL_ERROR');<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   |
| public      | calculate_fee                       | p_asset_symbol text, p_amount numeric, p_fee_type text                                                                                                                            | TABLE(fee_amount numeric, fee_percentage numeric, net_amount numeric, fee_details jsonb)                                                                                                                                                                                                                                                                                                                                                                                                                        | CREATE OR REPLACE FUNCTION public.calculate_fee(p_asset_symbol text, p_amount numeric, p_fee_type text DEFAULT 'transfer'::text)<br> RETURNS TABLE(fee_amount numeric, fee_percentage numeric, net_amount numeric, fee_details jsonb)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>DECLARE<br>    v_fee_percentage NUMERIC := 0;<br>    v_fee_amount NUMERIC := 0;<br>    v_min_fee NUMERIC := 0.01;<br>BEGIN<br>    CASE p_fee_type<br>        WHEN 'transfer' THEN<br>            v_fee_percentage := 0.5;<br>            v_fee_amount := p_amount * (v_fee_percentage / 100);<br>            IF v_fee_amount < v_min_fee THEN v_fee_amount := v_min_fee; END IF;<br><br>        WHEN 'withdraw' THEN<br>            SELECT withdraw_fee INTO v_fee_amount<br>            FROM supported_assets<br>            WHERE symbol = p_asset_symbol;<br><br>            v_fee_amount := COALESCE(v_fee_amount, 0);<br><br>            IF p_amount > 0 THEN<br>                v_fee_percentage := (v_fee_amount / p_amount) * 100;<br>            ELSE<br>                v_fee_percentage := 0;<br>            END IF;<br><br>        WHEN 'swap' THEN<br>            v_fee_percentage := 0.5;<br>            v_fee_amount := p_amount * (v_fee_percentage / 100);<br>            IF v_fee_amount < v_min_fee THEN v_fee_amount := v_min_fee; END IF;<br><br>        ELSE<br>            v_fee_amount := 0;<br>            v_fee_percentage := 0;<br>    END CASE;<br><br>    fee_amount := v_fee_amount;<br>    fee_percentage := v_fee_percentage;<br>    net_amount := p_amount - v_fee_amount;<br><br>    fee_details := jsonb_build_object(<br>        'fee_type', p_fee_type,<br>        'asset_symbol', p_asset_symbol,<br>        'amount', p_amount,<br>        'min_fee_applied', (v_fee_amount = v_min_fee AND v_min_fee > 0 AND p_fee_type <> 'withdraw')<br>    );<br><br>    RETURN NEXT;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | calculate_net_amount                |                                                                                                                                                                                   | trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         | CREATE OR REPLACE FUNCTION public.calculate_net_amount()<br> RETURNS trigger<br> LANGUAGE plpgsql<br>AS $function$<br>BEGIN<br>    NEW.net_amount := NEW.amount - COALESCE(NEW.fee, 0);<br>    RETURN NEW;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | calculate_pool_apy                  | p_pool_id uuid, p_stake_amount numeric, p_reference_date timestamp with time zone                                                                                                 | TABLE(apy numeric, mode text, details jsonb)                                                                                                                                                                                                                                                                                                                                                                                                                                                                    | CREATE OR REPLACE FUNCTION public.calculate_pool_apy(p_pool_id uuid, p_stake_amount numeric DEFAULT 0, p_reference_date timestamp with time zone DEFAULT now())<br> RETURNS TABLE(apy numeric, mode text, details jsonb)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>DECLARE<br>    v_pool RECORD;<br>    v_result_apy NUMERIC := 0;<br>    v_details JSONB := '{}'::jsonb;<br>    v_total_staked NUMERIC;<br>    v_rewards_remaining NUMERIC;<br>    v_days_remaining INTEGER;<br>    v_daily_budget NUMERIC;<br>    v_projected_total_staked NUMERIC;<br>    v_utilization_rate NUMERIC;<br>BEGIN<br>    -- Récupérer les informations du pool<br>    SELECT * INTO v_pool <br>    FROM staking_pools <br>    WHERE id = p_pool_id AND is_active = true;<br>    <br>    IF v_pool IS NULL THEN<br>        RETURN QUERY SELECT 0::NUMERIC, 'error'::TEXT, '{"error": "Pool not found or inactive"}'::jsonb;<br>        RETURN;<br>    END IF;<br>    <br>    -- Calculer le total staké actuel<br>    SELECT COALESCE(SUM(amount), 0) INTO v_total_staked<br>    FROM user_stakes <br>    WHERE pool_id = p_pool_id AND status = 'active';<br>    <br>    -- Total projeté (actuel + nouveau stake)<br>    v_projected_total_staked := v_total_staked + p_stake_amount;<br>    <br>    CASE v_pool.apy_mode<br>        <br>        -- ── APY FIXE ──────────────────────────────────────────<br>        WHEN 'fixed' THEN<br>            v_result_apy := COALESCE(v_pool.base_apy, 0);<br>            v_details := jsonb_build_object(<br>                'mode', 'fixed',<br>                'base_apy', v_pool.base_apy,<br>                'effective_apy', ROUND(v_result_apy, 2)<br>            );<br>        <br>        -- ── APY DYNAMIQUE ─────────────────────────────────────<br>        WHEN 'dynamic' THEN<br>            -- Calculer le taux d'utilisation<br>            IF COALESCE(v_pool.total_capacity, 0) = 0 THEN<br>                v_utilization_rate := 0;<br>            ELSE<br>                v_utilization_rate := v_projected_total_staked / v_pool.total_capacity;<br>            END IF;<br>            <br>            -- APY = base_apy * (1 - utilisation) avec minimum 20% du base<br>            v_result_apy := v_pool.base_apy * GREATEST(1 - v_utilization_rate, 0.2);<br>            <br>            v_details := jsonb_build_object(<br>                'mode', 'dynamic',<br>                'base_apy', v_pool.base_apy,<br>                'effective_apy', ROUND(v_result_apy, 2),<br>                'utilization_rate', ROUND(v_utilization_rate * 100, 2),<br>                'total_staked', v_total_staked,<br>                'projected_staked', v_projected_total_staked,<br>                'total_capacity', v_pool.total_capacity<br>            );<br>        <br>        -- ── LAUNCHPOOL ────────────────────────────────────────<br>        WHEN 'launchpool' THEN<br>            -- Vérifier si le launchpool est valide<br>            IF v_pool.launchpool_end_date IS NULL <br>               OR v_pool.launchpool_end_date <= p_reference_date<br>               OR COALESCE(v_pool.launchpool_rewards_left, 0) <= 0 THEN<br>                <br>                v_result_apy := 0;<br>                v_details := jsonb_build_object(<br>                    'mode', 'launchpool',<br>                    'status', 'ended',<br>                    'message', 'Launchpool terminé ou épuisé',<br>                    'effective_apy', 0<br>                );<br>                <br>                RETURN QUERY SELECT v_result_apy, 'launchpool'::TEXT, v_details;<br>                RETURN;<br>            END IF;<br><br>            -- Calculer les jours restants<br>            v_days_remaining := GREATEST(<br>                EXTRACT(DAY FROM (v_pool.launchpool_end_date - p_reference_date))::INTEGER,<br>                1<br>            );<br>            <br>            v_rewards_remaining := COALESCE(v_pool.launchpool_rewards_left, 0);<br>            <br>            -- Si personne n'a stake<br>            IF v_projected_total_staked = 0 THEN<br>                v_result_apy := COALESCE(v_pool.base_apy, 10.0); -- 10% par défaut<br>                v_details := jsonb_build_object(<br>                    'mode', 'launchpool',<br>                    'status', 'no_stakers',<br>                    'base_apy', v_pool.base_apy,<br>                    'effective_apy', ROUND(v_result_apy, 2),<br>                    'message', 'Pas encore de stakers - APY de base affiché'<br>                );<br>            ELSE<br>                -- Budget quotidien<br>                v_daily_budget := v_rewards_remaining / v_days_remaining;<br>                <br>                -- FORMULE : APY = (daily_budget / total_staked) × 365 × 100<br>                v_result_apy := (v_daily_budget / v_projected_total_staked) * 365 * 100;<br>                <br>                v_details := jsonb_build_object(<br>                    'mode', 'launchpool',<br>                    'status', 'active',<br>                    'total_staked', v_total_staked,<br>                    'projected_staked', v_projected_total_staked,<br>                    'rewards_remaining', ROUND(v_rewards_remaining, 2),<br>                    'days_remaining', v_days_remaining,<br>                    'daily_budget', ROUND(v_daily_budget, 4),<br>                    'effective_apy', ROUND(v_result_apy, 2),<br>                    'formula', '(daily_budget / total_staked) × 365 × 100'<br>                );<br>            END IF;<br>        <br>        -- ── AUTRE MODE (fallback) ─────────────────────────────<br>        ELSE<br>            v_result_apy := COALESCE(v_pool.base_apy, 0);<br>            v_details := jsonb_build_object(<br>                'mode', COALESCE(v_pool.apy_mode, 'unknown'),<br>                'base_apy', v_pool.base_apy,<br>                'effective_apy', ROUND(v_result_apy, 2),<br>                'warning', 'Mode non reconnu, utilisation du base_apy'<br>            );<br>    <br>    END CASE;<br>    <br>    -- S'assurer que l'APY n'est pas négatif<br>    v_result_apy := GREATEST(ROUND(v_result_apy, 6), 0);<br>    <br>    -- Retourner le résultat<br>    RETURN QUERY SELECT v_result_apy, v_pool.apy_mode, v_details;<br>    <br>EXCEPTION WHEN OTHERS THEN<br>    RAISE NOTICE 'calculate_pool_apy error (pool %): %', p_pool_id, SQLERRM;<br>    RETURN QUERY SELECT <br>        COALESCE(v_pool.base_apy, 0)::NUMERIC, <br>        COALESCE(v_pool.apy_mode, 'error')::TEXT, <br>        jsonb_build_object('error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | check_balance                       | p_user_id uuid, p_asset text, p_amount numeric                                                                                                                                    | boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         | CREATE OR REPLACE FUNCTION public.check_balance(p_user_id uuid, p_asset text, p_amount numeric)<br> RETURNS boolean<br> LANGUAGE plpgsql<br>AS $function$<br>DECLARE<br>  v_balance numeric;<br>BEGIN<br>  SELECT available_balance INTO v_balance<br>  FROM user_balances <br>  WHERE user_id = p_user_id AND asset_symbol = p_asset;<br>  <br>  RETURN COALESCE(v_balance, 0) >= p_amount;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | check_transaction_limit             | p_user_id uuid, p_amount numeric, p_type text                                                                                                                                     | TABLE(allowed boolean, message text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.check_transaction_limit(p_user_id uuid, p_amount numeric, p_type text)<br> RETURNS TABLE(allowed boolean, message text)<br> LANGUAGE plpgsql<br>AS $function$<br>DECLARE<br>    v_limits RECORD;<br>BEGIN<br>    -- Récupérer ou créer les limites<br>    INSERT INTO user_transaction_limits (user_id)<br>    VALUES (p_user_id)<br>    ON CONFLICT (user_id) DO NOTHING;<br>    <br>    SELECT * INTO v_limits<br>    FROM user_transaction_limits<br>    WHERE user_id = p_user_id<br>    FOR UPDATE;<br>    <br>    -- Reset si nécessaire<br>    IF v_limits.last_daily_reset < CURRENT_DATE THEN<br>        UPDATE user_transaction_limits<br>        SET <br>            daily_withdraw_used = 0,<br>            daily_deposit_used = 0,<br>            last_daily_reset = CURRENT_DATE<br>        WHERE user_id = p_user_id;<br>        <br>        SELECT * INTO v_limits<br>        FROM user_transaction_limits<br>        WHERE user_id = p_user_id;<br>    END IF;<br>    <br>    -- Vérifier limites<br>    IF p_type = 'withdraw' THEN<br>        IF (v_limits.daily_withdraw_used + p_amount) > v_limits.daily_withdraw_limit THEN<br>            RETURN QUERY SELECT FALSE, 'Limite quotidienne de retrait dépassée';<br>            RETURN;<br>        END IF;<br>    ELSIF p_type = 'deposit' THEN<br>        IF (v_limits.daily_deposit_used + p_amount) > v_limits.daily_deposit_limit THEN<br>            RETURN QUERY SELECT FALSE, 'Limite quotidienne de dépôt dépassée';<br>            RETURN;<br>        END IF;<br>    END IF;<br>    <br>    RETURN QUERY SELECT TRUE, 'Limite OK';<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        |
| public      | check_user_address                  | p_user_id uuid, p_asset_symbol text                                                                                                                                               | TABLE(status text, id uuid, asset_symbol text, network text, address text, derivation_index integer, is_active boolean, cached_balance numeric, created_at timestamp with time zone, error_message text)                                                                                                                                                                                                                                                                                                        | CREATE OR REPLACE FUNCTION public.check_user_address(p_user_id uuid, p_asset_symbol text)<br> RETURNS TABLE(status text, id uuid, asset_symbol text, network text, address text, derivation_index integer, is_active boolean, cached_balance numeric, created_at timestamp with time zone, error_message text)<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>#variable_conflict use_column<br>declare<br>  v_symbol text := upper(trim(p_asset_symbol));<br>  v_pending record;<br>  v_status int;<br>  v_body jsonb;<br>begin<br>  if auth.uid() is distinct from p_user_id<br>     and coalesce(auth.role(), '') <> 'service_role' then<br>    raise exception 'Non autorisé';<br>  end if;<br><br>  return query<br>    select 'ready'::text, ua.id, ua.asset_symbol, ua.network, ua.address,<br>           ua.derivation_index, ua.is_active, ua.cached_balance, ua.created_at, null::text<br>    from public.user_addresses ua<br>    where ua.user_id = p_user_id and ua.asset_symbol = v_symbol<br>    limit 1;<br>  if found then return; end if;<br><br>  select * into v_pending from public.pending_address_requests par<br>  where par.user_id = p_user_id and par.asset_symbol = v_symbol;<br><br>  if not found then<br>    return query select 'failed'::text, null::uuid, v_symbol, null::text, null::text,<br>                        null::integer, null::boolean, null::numeric, null::timestamptz,<br>                        'Aucune génération en cours — relancez'::text;<br>    return;<br>  end if;<br><br>  select r.status_code, r.content::jsonb into v_status, v_body<br>  from net._http_response r where r.id = v_pending.request_id;<br><br>  if v_status is null then<br>    return query select 'pending'::text, null::uuid, v_symbol, null::text, null::text,<br>                        null::integer, null::boolean, null::numeric, null::timestamptz, null::text;<br>    return;<br>  end if;<br><br>  delete from public.pending_address_requests par<br>  where par.user_id = p_user_id and par.asset_symbol = v_symbol;<br><br>  if v_status <> 200 or coalesce((v_body->>'success')::boolean, false) = false then<br>    return query select 'failed'::text, null::uuid, v_symbol, null::text, null::text,<br>                        null::integer, null::boolean, null::numeric, null::timestamptz,<br>                        coalesce(v_body->>'error', 'Erreur inconnue (HTTP ' \|\| v_status \|\| ')');<br>    return;<br>  end if;<br><br>  insert into public.user_addresses (<br>    user_id, asset_symbol, address, derivation_index, network, is_active, cached_balance<br>  )<br>  values (<br>    p_user_id,<br>    upper(v_body->'data'->>'asset_symbol'),<br>    v_body->'data'->>'address',<br>    (v_body->'data'->>'derivation_index')::integer,<br>    v_body->'data'->>'network',<br>    true, 0<br>  )<br>  on conflict (user_id, asset_symbol) do update<br>    set address = excluded.address,<br>        derivation_index = excluded.derivation_index,<br>        network = excluded.network,<br>        is_active = true;<br><br>  return query<br>    select 'ready'::text, ua.id, ua.asset_symbol, ua.network, ua.address,<br>           ua.derivation_index, ua.is_active, ua.cached_balance, ua.created_at, null::text<br>    from public.user_addresses ua<br>    where ua.user_id = p_user_id and ua.asset_symbol = v_symbol<br>    limit 1;<br>end;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      |
| public      | collect_fee_to_platform             | p_asset_symbol text, p_amount numeric, p_fee_type text, p_source_user_id uuid, p_source_transaction_id uuid                                                                       | uuid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.collect_fee_to_platform(p_asset_symbol text, p_amount numeric, p_fee_type text, p_source_user_id uuid DEFAULT NULL::uuid, p_source_transaction_id uuid DEFAULT NULL::uuid)<br> RETURNS uuid<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>    v_fee_id uuid;<br>    v_asset_exists boolean;<br>    v_balance_after numeric;<br>    v_balance_before numeric;<br>BEGIN<br>    -- Validation des paramètres<br>    IF p_amount <= 0 THEN<br>        RAISE WARNING 'collect_fee_to_platform: Montant invalide (%)', p_amount;<br>        RETURN NULL;<br>    END IF;<br><br>    -- Vérifier que l'asset existe<br>    SELECT EXISTS (<br>        SELECT 1 FROM supported_assets WHERE symbol = p_asset_symbol AND is_active = true<br>    ) INTO v_asset_exists;<br><br>    IF NOT v_asset_exists THEN<br>        RAISE WARNING 'collect_fee_to_platform: Asset % non trouvé ou inactif', p_asset_symbol;<br>        RETURN NULL;<br>    END IF;<br><br>    -- ================================================<br>    -- 1. Insérer dans platform_fees<br>    -- ================================================<br>    INSERT INTO public.platform_fees (<br>        asset_symbol,<br>        amount,<br>        fee_type,<br>        source_user_id,<br>        source_transaction_id,<br>        collected_at<br>    ) VALUES (<br>        p_asset_symbol,<br>        p_amount,<br>        p_fee_type,<br>        p_source_user_id,<br>        p_source_transaction_id,<br>        NOW()<br>    ) RETURNING id INTO v_fee_id;<br><br>    -- ================================================<br>    -- 1.bis. Crediter le wallet de tresorerie (le vrai solde spendable)<br>    -- ================================================<br>    INSERT INTO public.treasury_wallets (asset_symbol, balance, total_collected)<br>    VALUES (p_asset_symbol, p_amount, p_amount)<br>    ON CONFLICT (asset_symbol) DO UPDATE SET<br>        balance = treasury_wallets.balance + p_amount,<br>        total_collected = treasury_wallets.total_collected + p_amount,<br>        updated_at = now()<br>    RETURNING balance, balance - p_amount INTO v_balance_after, v_balance_before;<br><br>    INSERT INTO public.treasury_ledger (<br>        asset_symbol, entry_type, amount, balance_before, balance_after,<br>        source_transaction_id, source_fee_id, reason<br>    ) VALUES (<br>        p_asset_symbol, 'fee_credit', p_amount, v_balance_before, v_balance_after,<br>        p_source_transaction_id, v_fee_id, p_fee_type<br>    );<br><br>    -- ================================================<br>    -- 2. Mettre à jour les métriques dans supported_assets_metrics<br>    -- ================================================<br>    <br>    -- Mise à jour des métriques existantes<br>    UPDATE public.supported_assets_metrics<br>    SET <br>        total_fees_collected = COALESCE(total_fees_collected, 0) + p_amount,<br>        last_updated = NOW()<br>    WHERE asset_symbol = p_asset_symbol;<br><br>    -- Mise à jour spécifique selon le type de frais<br>    CASE p_fee_type<br>        WHEN 'swap_fee' THEN<br>            UPDATE public.supported_assets_metrics<br>            SET total_swap_fees_collected = COALESCE(total_swap_fees_collected, 0) + p_amount<br>            WHERE asset_symbol = p_asset_symbol;<br>            <br>        WHEN 'p2p_fee' THEN<br>            UPDATE public.supported_assets_metrics<br>            SET total_p2p_fees_collected = COALESCE(total_p2p_fees_collected, 0) + p_amount<br>            WHERE asset_symbol = p_asset_symbol;<br>            <br>        WHEN 'withdraw_fee' THEN<br>            UPDATE public.supported_assets_metrics<br>            SET total_withdraw_fees_collected = COALESCE(total_withdraw_fees_collected, 0) + p_amount<br>            WHERE asset_symbol = p_asset_symbol;<br>            <br>        WHEN 'unstake_fee' THEN<br>            UPDATE public.supported_assets_metrics<br>            SET total_fees_collected = COALESCE(total_fees_collected, 0) + p_amount<br>            WHERE asset_symbol = p_asset_symbol;<br>            <br>        WHEN 'early_unstake_penalty' THEN<br>            UPDATE public.supported_assets_metrics<br>            SET total_fees_collected = COALESCE(total_fees_collected, 0) + p_amount<br>            WHERE asset_symbol = p_asset_symbol;<br>            <br>        ELSE<br>            -- Autres types de frais (génériques)<br>            UPDATE public.supported_assets_metrics<br>            SET total_fees_collected = COALESCE(total_fees_collected, 0) + p_amount<br>            WHERE asset_symbol = p_asset_symbol;<br>    END CASE;<br><br>    -- Si l'asset n'a pas encore de métriques, les créer<br>    INSERT INTO public.supported_assets_metrics (<br>        asset_symbol,<br>        total_fees_collected,<br>        total_swap_fees_collected,<br>        total_p2p_fees_collected,<br>        total_withdraw_fees_collected,<br>        total_deposited,<br>        total_withdrawn,<br>        total_staked,<br>        total_user_balance,<br>        net_position,<br>        should_be_in_custody,<br>        last_updated<br>    )<br>    SELECT <br>        p_asset_symbol,<br>        p_amount,<br>        CASE WHEN p_fee_type = 'swap_fee' THEN p_amount ELSE 0 END,<br>        CASE WHEN p_fee_type = 'p2p_fee' THEN p_amount ELSE 0 END,<br>        CASE WHEN p_fee_type = 'withdraw_fee' THEN p_amount ELSE 0 END,<br>        0, 0, 0, 0, 0, 0,<br>        NOW()<br>    WHERE NOT EXISTS (<br>        SELECT 1 FROM public.supported_assets_metrics <br>        WHERE asset_symbol = p_asset_symbol<br>    );<br><br>    -- Log pour le débogage<br>    RAISE NOTICE '✅ Frais collecté: % % (type: %, tx: %)', <br>        p_amount, p_asset_symbol, p_fee_type, p_source_transaction_id;<br><br>    RETURN v_fee_id;<br><br>EXCEPTION<br>    WHEN OTHERS THEN<br>        RAISE WARNING 'collect_fee_to_platform: Erreur - %', SQLERRM;<br>        RETURN NULL;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     |
| public      | complete_user_profile               | p_user_id uuid, p_username text, p_referral_code text                                                                                                                             | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.complete_user_profile(p_user_id uuid, p_username text, p_referral_code text DEFAULT NULL::text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_referrer           RECORD;<br>  v_referral_applied    boolean := false;<br>  v_referrer_username   text;<br>  v_bonus_referred      numeric := 300;<br>  v_bonus_referrer      numeric := 200;<br>  v_bonus_asset         text    := 'WAKATI';<br>  v_clean_username      text;<br>BEGIN<br>  IF auth.uid() IS DISTINCT FROM p_user_id THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN', 'message', 'Action non autorisée');<br>  END IF;<br><br>  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'USER_NOT_FOUND', 'message', 'Utilisateur introuvable');<br>  END IF;<br><br>  IF EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id AND profile_completed = true) THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'ALREADY_COMPLETED', 'message', 'Profil déjà complété');<br>  END IF;<br><br>  v_clean_username := LOWER(TRIM(p_username));<br>  v_clean_username := REGEXP_REPLACE(v_clean_username, '[^a-zA-Z0-9_]', '', 'g');<br><br>  IF LENGTH(v_clean_username) > 20 THEN<br>    v_clean_username := SUBSTRING(v_clean_username FROM 1 FOR 20);<br>  END IF;<br><br>  IF LENGTH(v_clean_username) < 3 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'USERNAME_TOO_SHORT', 'message', 'Le username doit faire au moins 3 caractères');<br>  END IF;<br><br>  IF EXISTS (SELECT 1 FROM public.users WHERE username = v_clean_username AND id != p_user_id) THEN<br>    v_clean_username := SUBSTRING(v_clean_username FROM 1 FOR 18) \|\| SUBSTRING(MD5(RANDOM()::text) FROM 1 FOR 2);<br>    IF EXISTS (SELECT 1 FROM public.users WHERE username = v_clean_username AND id != p_user_id) THEN<br>      RETURN jsonb_build_object('success', false, 'error', 'USERNAME_TAKEN', 'message', 'Ce username est déjà pris, essaie un autre');<br>    END IF;<br>  END IF;<br><br>  IF p_referral_code IS NOT NULL AND TRIM(p_referral_code) != '' THEN<br><br>    IF EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id AND referred_by IS NOT NULL) THEN<br>      RETURN jsonb_build_object('success', false, 'error', 'ALREADY_REFERRED', 'message', 'Tu as déjà utilisé un code referral');<br>    END IF;<br><br>    SELECT id, username INTO v_referrer<br>    FROM public.users<br>    WHERE referral_code = UPPER(TRIM(p_referral_code))<br>      AND id != p_user_id;<br><br>    IF NOT FOUND THEN<br>      RETURN jsonb_build_object('success', false, 'error', 'INVALID_CODE', 'message', 'Code referral invalide ou inexistant');<br>    END IF;<br><br>    v_referral_applied  := true;<br>    v_referrer_username := v_referrer.username;<br><br>    UPDATE public.users SET referred_by = v_referrer.id, updated_at = NOW() WHERE id = p_user_id;<br><br>    -- Bonus filleul (300 WAKATI), finance par la tresorerie<br>    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance)<br>    VALUES (p_user_id, v_bonus_asset, v_bonus_referred)<br>    ON CONFLICT (user_id, asset_symbol) DO UPDATE<br>      SET available_balance = user_balances.available_balance + v_bonus_referred, updated_at = NOW();<br><br>    INSERT INTO public.transactions (user_id, type, asset_symbol, amount, status, metadata)<br>    VALUES (p_user_id, 'referral_bonus', v_bonus_asset, v_bonus_referred, 'completed',<br>      jsonb_build_object('referrer_id', v_referrer.id, 'referrer_username', v_referrer_username, 'recipient_type', 'referred'));<br><br>    PERFORM fn_treasury_debit_for_payout(v_bonus_asset, v_bonus_referred, p_user_id, 'Bonus parrainage - filleul');<br><br>    -- Bonus parrain (200 WAKATI), finance par la tresorerie<br>    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance)<br>    VALUES (v_referrer.id, v_bonus_asset, v_bonus_referrer)<br>    ON CONFLICT (user_id, asset_symbol) DO UPDATE<br>      SET available_balance = user_balances.available_balance + v_bonus_referrer, updated_at = NOW();<br><br>    INSERT INTO public.transactions (user_id, type, asset_symbol, amount, status, metadata)<br>    VALUES (v_referrer.id, 'referral_bonus', v_bonus_asset, v_bonus_referrer, 'completed',<br>      jsonb_build_object('referred_user_id', p_user_id, 'referred_username', v_clean_username, 'recipient_type', 'referrer'));<br><br>    PERFORM fn_treasury_debit_for_payout(v_bonus_asset, v_bonus_referrer, v_referrer.id, 'Bonus parrainage - parrain');<br><br>    INSERT INTO public.notifications (user_id, type, title, message, data) VALUES (<br>      v_referrer.id, 'referral_success', 'Nouveau filleul !',<br>      format('%s a rejoint Wakati avec ton code. +%s %s crédités !', v_clean_username, v_bonus_referrer, v_bonus_asset),<br>      jsonb_build_object('referred_user_id', p_user_id, 'referred_username', v_clean_username, 'bonus_amount', v_bonus_referrer)<br>    );<br><br>    INSERT INTO public.notifications (user_id, type, title, message, data) VALUES (<br>      p_user_id, 'referral_bonus', 'Code referral appliqué !',<br>      format('+%s %s crédités grâce au code de %s', v_bonus_referred, v_bonus_asset, v_referrer_username),<br>      jsonb_build_object('referrer_id', v_referrer.id, 'referrer_username', v_referrer_username, 'bonus_amount', v_bonus_referred)<br>    );<br><br>  END IF;<br><br>  UPDATE public.users<br>  SET username = v_clean_username, profile_completed = true, updated_at = NOW()<br>  WHERE id = p_user_id;<br><br>  RETURN jsonb_build_object(<br>    'success',           true,<br>    'username',          v_clean_username,<br>    'profile_completed', true,<br>    'referral_applied',  v_referral_applied,<br>    'referrer_username', v_referrer_username,<br>    'bonus_amount',      CASE WHEN v_referral_applied THEN v_bonus_referred ELSE 0 END,<br>    'bonus_asset',       v_bonus_asset,<br>    'message',           CASE<br>                           WHEN v_referral_applied<br>                           THEN format('Bienvenue ! +%s %s crédités.', v_bonus_referred, v_bonus_asset)<br>                           ELSE 'Profil complété avec succès.'<br>                         END<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', 'INTERNAL_ERROR', 'message', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | confirm_campay_deposit              | p_external_reference text, p_campay_tx_id text, p_amount numeric, p_fee numeric                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.confirm_campay_deposit(p_external_reference text, p_campay_tx_id text, p_amount numeric, p_fee numeric DEFAULT 0)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_tx_id uuid;<br>  v_user_id uuid;<br>  v_net_amount numeric;<br>BEGIN<br>  SELECT id, user_id, (amount - COALESCE(fee, 0))<br>  INTO v_tx_id, v_user_id, v_net_amount<br>  FROM transactions<br>  WHERE metadata->>'external_reference' = p_external_reference<br>    AND type = 'deposit'<br>    AND status IN ('pending', 'processing')<br>  LIMIT 1;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Transaction introuvable ou déjà traitée');<br>  END IF;<br><br>  UPDATE transactions<br>  SET status = 'completed', tx_hash = p_campay_tx_id, completed_at = now(),<br>      metadata = metadata \|\| jsonb_build_object('campay_tx_id', p_campay_tx_id, 'callback_received_at', now())<br>  WHERE id = v_tx_id;<br><br>  PERFORM increment_balance(v_user_id, 'FCFA', v_net_amount);<br><br>  IF p_fee > 0 THEN<br>    PERFORM collect_fee_to_platform('FCFA', p_fee, 'deposit_fee', v_user_id, v_tx_id);<br>  END IF;<br><br>  UPDATE user_transaction_limits<br>  SET daily_deposit_used = daily_deposit_used + p_amount, updated_at = now()<br>  WHERE user_id = v_user_id;<br><br>  INSERT INTO notifications (user_id, type, title, message, data)<br>  VALUES (v_user_id, 'deposit_confirmed', 'Dépôt confirmé ✅',<br>    format('Votre dépôt de %s FCFA a été crédité sur votre compte.', v_net_amount),<br>    jsonb_build_object('transaction_id', v_tx_id, 'amount', v_net_amount, 'tran_id', p_campay_tx_id));<br><br>  PERFORM fn_award_engagement_points(v_user_id, 'deposit');<br><br>  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id, 'user_id', v_user_id);<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    |
| public      | confirm_mobile_money_deposit        | p_external_reference text, p_provider_tx_id text, p_amount numeric, p_fee numeric                                                                                                 | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.confirm_mobile_money_deposit(p_external_reference text, p_provider_tx_id text, p_amount numeric, p_fee numeric DEFAULT 0)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_tx_id uuid;<br>  v_user_id uuid;<br>  v_asset_symbol text;<br>  v_net_amount numeric;<br>BEGIN<br>  -- FOR UPDATE : verrouille la ligne de transaction jusqu'a la fin de la<br>  -- transaction Postgres. Si deux webhooks du provider arrivent en meme temps<br>  -- (retry sur timeout, tres courant), le second attend ici puis relit le<br>  -- statut deja passe a 'completed' par le premier -> NOT FOUND -> pas de<br>  -- double credit. Sans ce verrou, les deux peuvent lire 'pending' simultanement.<br>  SELECT id, user_id, asset_symbol, (amount - COALESCE(fee, 0))<br>  INTO v_tx_id, v_user_id, v_asset_symbol, v_net_amount<br>  FROM transactions<br>  WHERE metadata->>'external_reference' = p_external_reference<br>    AND type = 'deposit'<br>    AND status IN ('pending', 'processing')<br>  LIMIT 1<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Transaction introuvable ou déjà traitée');<br>  END IF;<br><br>  UPDATE transactions<br>  SET status = 'completed', tx_hash = p_provider_tx_id, completed_at = now(),<br>      metadata = metadata \|\| jsonb_build_object('provider_tx_id', p_provider_tx_id, 'callback_received_at', now())<br>  WHERE id = v_tx_id;<br><br>  PERFORM increment_balance(v_user_id, v_asset_symbol, v_net_amount);<br><br>  IF p_fee > 0 THEN<br>    PERFORM collect_fee_to_platform(v_asset_symbol, p_fee, 'deposit_fee', v_user_id, v_tx_id);<br>  END IF;<br><br>  UPDATE user_transaction_limits<br>  SET daily_deposit_used = daily_deposit_used + p_amount, updated_at = now()<br>  WHERE user_id = v_user_id;<br><br>  INSERT INTO notifications (user_id, type, title, message, data)<br>  VALUES (v_user_id, 'deposit_confirmed', 'Dépôt confirmé ✅',<br>    format('Votre dépôt de %s %s a été crédité sur votre compte.', v_net_amount, v_asset_symbol),<br>    jsonb_build_object('transaction_id', v_tx_id, 'amount', v_net_amount, 'tran_id', p_provider_tx_id));<br><br>  PERFORM fn_award_engagement_points(v_user_id, 'deposit');<br><br>  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id, 'user_id', v_user_id);<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | confirm_mobile_money_withdrawal     | p_external_reference text, p_provider_tx_id text                                                                                                                                  | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.confirm_mobile_money_withdrawal(p_external_reference text, p_provider_tx_id text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_tx_id uuid;<br>  v_user_id uuid;<br>  v_net_amount numeric;<br>  v_asset text;<br>BEGIN<br>  SELECT id, user_id, net_amount, asset_symbol INTO v_tx_id, v_user_id, v_net_amount, v_asset<br>  FROM transactions<br>  WHERE metadata->>'external_reference' = p_external_reference<br>    AND type = 'withdrawal' AND status IN ('pending', 'processing')<br>  LIMIT 1<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Transaction introuvable ou deja traitee');<br>  END IF;<br><br>  UPDATE transactions<br>  SET status = 'completed', completed_at = now(),<br>      metadata = metadata \|\| jsonb_build_object('provider_tx_id', p_provider_tx_id)<br>  WHERE id = v_tx_id;<br><br>  INSERT INTO notifications (user_id, type, title, message, data)<br>  VALUES (<br>    v_user_id, 'withdrawal_completed', 'Retrait effectué ✅',<br>    format('Votre retrait de %s %s a été envoyé avec succès.', v_net_amount, v_asset),<br>    jsonb_build_object('amount', v_net_amount)<br>  );<br><br>  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id);<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | decrement_balance                   | p_user_id uuid, p_asset_symbol text, p_amount numeric                                                                                                                             | numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         | CREATE OR REPLACE FUNCTION public.decrement_balance(p_user_id uuid, p_asset_symbol text, p_amount numeric)<br> RETURNS numeric<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  new_balance numeric;<br>BEGIN<br>  -- Réservé aux rôles internes uniquement<br>  IF current_role NOT IN ('service_role', 'postgres', 'supabase_admin') THEN<br>    RAISE EXCEPTION 'decrement_balance: accès non autorisé (rôle: %)', current_role<br>      USING ERRCODE = 'insufficient_privilege';<br>  END IF;<br><br>  -- Validation du montant<br>  IF p_amount <= 0 THEN<br>    RAISE EXCEPTION 'decrement_balance: le montant doit être positif (reçu: %)', p_amount<br>      USING ERRCODE = 'check_violation';<br>  END IF;<br><br>  UPDATE user_balances<br>  SET available_balance = available_balance - p_amount,<br>      updated_at = now()<br>  WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol<br>  RETURNING available_balance INTO new_balance;<br><br>  IF new_balance IS NULL THEN<br>    RAISE EXCEPTION 'decrement_balance: aucun solde trouvé pour user_id=% asset=%', p_user_id, p_asset_symbol<br>      USING ERRCODE = 'no_data_found';<br>  END IF;<br><br>  -- Vérification solde négatif (filet de sécurité)<br>  IF new_balance < 0 THEN<br>    RAISE EXCEPTION 'decrement_balance: solde insuffisant pour user_id=% asset=% (nouveau solde: %)', <br>      p_user_id, p_asset_symbol, new_balance<br>      USING ERRCODE = 'check_violation';<br>  END IF;<br><br>  RETURN new_balance;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              |
| public      | distribute_staking_rewards          |                                                                                                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.distribute_staking_rewards()<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_apr        numeric;<br>  v_daily_rate numeric;<br>  v_count      int := 0;<br>  v_total_dist numeric := 0;<br>BEGIN<br>  SELECT apr INTO v_apr FROM staking_config WHERE id = 1;<br>  IF v_apr IS NULL OR v_apr <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'APR non configuré');<br>  END IF;<br><br>  v_daily_rate := v_apr / 100.0 / 365.0;<br><br>  SELECT COALESCE(SUM(amount * v_daily_rate), 0) INTO v_total_dist<br>  FROM user_stakes<br>  WHERE status = 'active'<br>    AND pool_id = 'f6c208e1-f277-4720-b303-45c1b607bf1f';<br><br>  UPDATE user_stakes SET<br>    pending_rewards         = pending_rewards + (amount * v_daily_rate),<br>    last_reward_calculation = now(),<br>    updated_at              = now()<br>  WHERE status  = 'active'<br>    AND pool_id = 'f6c208e1-f277-4720-b303-45c1b607bf1f';<br><br>  GET DIAGNOSTICS v_count = ROW_COUNT;<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'stakers_updated', v_count,<br>    'apr_used', v_apr,<br>    'total_distributed_today', ROUND(v_total_dist, 8)<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| public      | estimate_swap                       | p_from_asset text, p_to_asset text, p_amount numeric, p_fee_rate numeric                                                                                                          | TABLE(from_asset text, to_asset text, amount_in numeric, amount_out numeric, gross_out numeric, rate numeric, fee_amount numeric, fee_rate_pct numeric, price_impact text, is_valid boolean, error_message text)                                                                                                                                                                                                                                                                                                | CREATE OR REPLACE FUNCTION public.estimate_swap(p_from_asset text, p_to_asset text, p_amount numeric, p_fee_rate numeric DEFAULT NULL::numeric)<br> RETURNS TABLE(from_asset text, to_asset text, amount_in numeric, amount_out numeric, gross_out numeric, rate numeric, fee_amount numeric, fee_rate_pct numeric, price_impact text, is_valid boolean, error_message text)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>DECLARE<br>    v_price_from numeric;<br>    v_price_to   numeric;<br>    v_rate       numeric;<br>    v_gross_out  numeric;<br>    v_fee        numeric;<br>    v_net_out    numeric;<br>    v_actual_fee_rate numeric;<br>    v_from_asset_record record;<br>    v_to_asset_record record;<br>BEGIN<br>    -- Récupérer les informations des assets source et destination<br>    SELECT * INTO v_from_asset_record <br>    FROM public.supported_assets <br>    WHERE symbol = p_from_asset AND is_active = true;<br>    <br>    SELECT * INTO v_to_asset_record <br>    FROM public.supported_assets <br>    WHERE symbol = p_to_asset AND is_active = true;<br>    <br>    -- Vérifier que les assets existent et sont actifs<br>    IF v_from_asset_record IS NULL THEN<br>        RETURN QUERY SELECT<br>            p_from_asset, p_to_asset, p_amount,<br>            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,<br>            'Asset source non trouvé ou inactif'::text,<br>            false, 'Asset source invalide'::text;<br>        RETURN;<br>    END IF;<br>    <br>    IF v_to_asset_record IS NULL THEN<br>        RETURN QUERY SELECT<br>            p_from_asset, p_to_asset, p_amount,<br>            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,<br>            'Asset destination non trouvé ou inactif'::text,<br>            false, 'Asset destination invalide'::text;<br>        RETURN;<br>    END IF;<br>    <br>    -- Vérifier que les assets peuvent être swappés<br>    IF NOT v_from_asset_record.can_be_swapped THEN<br>        RETURN QUERY SELECT<br>            p_from_asset, p_to_asset, p_amount,<br>            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,<br>            'Swap non autorisé pour l''asset source'::text,<br>            false, 'Swap non autorisé'::text;<br>        RETURN;<br>    END IF;<br>    <br>    IF NOT v_to_asset_record.can_be_swapped THEN<br>        RETURN QUERY SELECT<br>            p_from_asset, p_to_asset, p_amount,<br>            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,<br>            'Swap non autorisé pour l''asset destination'::text,<br>            false, 'Swap non autorisé'::text;<br>        RETURN;<br>    END IF;<br>    <br>    -- Récupérer les prix depuis asset_prices<br>    SELECT price_usd INTO v_price_from <br>    FROM public.asset_prices <br>    WHERE asset_symbol = p_from_asset;<br>    <br>    SELECT price_usd INTO v_price_to <br>    FROM public.asset_prices <br>    WHERE asset_symbol = p_to_asset;<br><br>    -- Vérifier que les prix sont disponibles<br>    IF v_price_from IS NULL OR v_price_from = 0 THEN<br>        RETURN QUERY SELECT<br>            p_from_asset, p_to_asset, p_amount,<br>            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,<br>            'Prix non disponible pour ' \|\| p_from_asset,<br>            false, 'Prix non disponible'::text;<br>        RETURN;<br>    END IF;<br>    <br>    IF v_price_to IS NULL OR v_price_to = 0 THEN<br>        RETURN QUERY SELECT<br>            p_from_asset, p_to_asset, p_amount,<br>            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,<br>            'Prix non disponible pour ' \|\| p_to_asset,<br>            false, 'Prix non disponible'::text;<br>        RETURN;<br>    END IF;<br>    <br>    -- ✅ Déterminer le taux de frais à utiliser<br>    -- Priorité: paramètre fourni → swap_fee_percentage de l'asset source → 0.5% par défaut<br>    v_actual_fee_rate := COALESCE(<br>        p_fee_rate, <br>        v_from_asset_record.swap_fee_percentage, <br>        0.5  -- 0.5% par défaut si rien n'est configuré<br>    );<br>    <br>    -- Calculer le taux de change et les montants<br>    v_rate      := v_price_from / v_price_to;<br>    v_gross_out := p_amount * v_rate;<br>    v_fee       := v_gross_out * (v_actual_fee_rate / 100);  -- Conversion pourcentage → décimal<br>    v_net_out   := v_gross_out - v_fee;<br><br>    -- Retourner le résultat<br>    RETURN QUERY SELECT<br>        p_from_asset,<br>        p_to_asset,<br>        p_amount,<br>        ROUND(v_net_out, 8),<br>        ROUND(v_gross_out, 8),<br>        ROUND(v_rate, 6),<br>        ROUND(v_fee, 8),<br>        ROUND(v_actual_fee_rate, 2),  -- Retourne le pourcentage<br>        'Faible'::text,<br>        true,<br>        NULL::text;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    |
| public      | execute_swap_realtime               | p_user_id uuid, p_from_asset text, p_to_asset text, p_from_amount numeric, p_slippage_tolerance numeric                                                                           | TABLE(success boolean, message text, transaction_id uuid, from_amount numeric, to_amount numeric, exchange_rate numeric, fee_amount numeric, net_to_amount numeric, realtime_price_used boolean)                                                                                                                                                                                                                                                                                                                | CREATE OR REPLACE FUNCTION public.execute_swap_realtime(p_user_id uuid, p_from_asset text, p_to_asset text, p_from_amount numeric, p_slippage_tolerance numeric DEFAULT 1.0)<br> RETURNS TABLE(success boolean, message text, transaction_id uuid, from_amount numeric, to_amount numeric, exchange_rate numeric, fee_amount numeric, net_to_amount numeric, realtime_price_used boolean)<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>    v_estimate record;<br>    v_user_balance numeric;<br>    v_transaction_id uuid;<br>    v_swap_tx_id uuid;<br>    v_from_asset_record record;<br>    v_to_asset_record record;<br>    v_fee_rate numeric;<br>    v_treasury_to_balance numeric;<br>BEGIN<br>    IF p_from_asset = p_to_asset THEN<br>        RETURN QUERY SELECT<br>            FALSE, 'Impossible de swapper le même asset',<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    IF p_from_amount <= 0 THEN<br>        RETURN QUERY SELECT<br>            FALSE, 'Le montant doit être supérieur à 0',<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    SELECT * INTO v_from_asset_record<br>    FROM public.supported_assets<br>    WHERE symbol = p_from_asset AND is_active = true AND can_be_swapped = true;<br><br>    SELECT * INTO v_to_asset_record<br>    FROM public.supported_assets<br>    WHERE symbol = p_to_asset AND is_active = true AND can_be_swapped = true;<br><br>    IF v_from_asset_record IS NULL THEN<br>        RETURN QUERY SELECT<br>            FALSE, format('Swap non autorisé pour l''asset source: %s', p_from_asset),<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    IF v_to_asset_record IS NULL THEN<br>        RETURN QUERY SELECT<br>            FALSE, format('Swap non autorisé pour l''asset destination: %s', p_to_asset),<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    v_fee_rate := COALESCE(v_from_asset_record.swap_fee_percentage, 0.5);<br><br>    SELECT * INTO v_estimate<br>    FROM public.estimate_swap(p_from_asset, p_to_asset, p_from_amount, v_fee_rate);<br><br>    IF v_estimate.amount_out IS NULL OR v_estimate.amount_out <= 0 THEN<br>        RETURN QUERY SELECT<br>            FALSE, 'Impossible d''estimer le swap',<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    SELECT available_balance INTO v_user_balance<br>    FROM public.user_balances<br>    WHERE user_id = p_user_id AND asset_symbol = p_from_asset;<br><br>    IF v_user_balance IS NULL OR v_user_balance < p_from_amount THEN<br>        RETURN QUERY SELECT<br>            FALSE,<br>            format('Solde insuffisant en %s. Disponible: %s, Requis: %s',<br>                   p_from_asset, COALESCE(v_user_balance, 0), p_from_amount),<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    -- ✅ CONSERVATION : la trésorerie doit réellement détenir l'actif de<br>    -- destination avant qu'on promette quoi que ce soit à l'utilisateur.<br>    SELECT balance INTO v_treasury_to_balance<br>    FROM public.treasury_wallets WHERE asset_symbol = p_to_asset FOR UPDATE;<br><br>    IF v_treasury_to_balance IS NULL OR v_treasury_to_balance < v_estimate.amount_out THEN<br>        RETURN QUERY SELECT<br>            FALSE,<br>            format('Réserve de liquidité insuffisante en %s pour ce swap. Réessayez avec un montant plus petit ou plus tard.', p_to_asset),<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    INSERT INTO public.transactions (<br>        user_id, type, asset_symbol, network, amount, status, metadata<br>    ) VALUES (<br>        p_user_id, 'swap_debit', p_from_asset, v_from_asset_record.network, p_from_amount, 'completed',<br>        jsonb_build_object(<br>            'swap_type', 'asset_swap', 'to_asset', p_to_asset, 'exchange_rate', v_estimate.rate,<br>            'fee_percentage', v_fee_rate, 'slippage_tolerance', p_slippage_tolerance<br>        )<br>    ) RETURNING id INTO v_swap_tx_id;<br><br>    UPDATE public.user_balances<br>    SET available_balance = available_balance - p_from_amount, updated_at = NOW()<br>    WHERE user_id = p_user_id AND asset_symbol = p_from_asset;<br><br>    -- ✅ La trésorerie REÇOIT ce que l'utilisateur donne (jambe source).<br>    INSERT INTO public.treasury_wallets (asset_symbol, balance, total_collected, total_burned, total_withdrawn, updated_at)<br>    VALUES (p_from_asset, p_from_amount, p_from_amount, 0, 0, NOW())<br>    ON CONFLICT (asset_symbol) DO UPDATE<br>    SET balance = treasury_wallets.balance + p_from_amount,<br>        total_collected = treasury_wallets.total_collected + p_from_amount,<br>        updated_at = NOW();<br><br>    -- ✅ La trésorerie DONNE ce qu'elle doit à l'utilisateur (jambe destination).<br>    UPDATE public.treasury_wallets<br>    SET balance = balance - v_estimate.amount_out, updated_at = NOW()<br>    WHERE asset_symbol = p_to_asset;<br><br>    INSERT INTO public.transactions (<br>        user_id, type, asset_symbol, network, amount, fee, net_amount, status, reference_id, metadata<br>    ) VALUES (<br>        p_user_id, 'swap_credit', p_to_asset, v_to_asset_record.network, v_estimate.amount_out,<br>        v_estimate.fee_amount, v_estimate.amount_out, 'completed', v_swap_tx_id,<br>        jsonb_build_object('swap_type', 'asset_swap', 'from_asset', p_from_asset, 'from_amount', p_from_amount, 'exchange_rate', v_estimate.rate)<br>    ) RETURNING id INTO v_transaction_id;<br><br>    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance)<br>    VALUES (p_user_id, p_to_asset, v_estimate.amount_out)<br>    ON CONFLICT (user_id, asset_symbol)<br>    DO UPDATE SET available_balance = user_balances.available_balance + v_estimate.amount_out, updated_at = NOW();<br><br>    -- ✅ Trace de revenu réel pour les calculs de capacité de crédit et de<br>    -- prix WAKATI (audit uniquement : l'argent a déjà bougé ci-dessus via<br>    -- les 2 jambes, ceci ne fait que l'enregistrer comme revenu).<br>    IF v_estimate.fee_amount > 0 THEN<br>      INSERT INTO public.platform_fees (asset_symbol, amount, fee_type, source_user_id, source_transaction_id, collected_at)<br>      VALUES (p_to_asset, v_estimate.fee_amount, 'swap_fee', p_user_id, v_transaction_id, NOW());<br>    END IF;<br><br>    UPDATE public.supported_assets_metrics<br>    SET total_swap_volume = COALESCE(total_swap_volume, 0) + p_from_amount,<br>        total_swap_fees_collected = COALESCE(total_swap_fees_collected, 0) + v_estimate.fee_amount,<br>        total_fees_collected = COALESCE(total_fees_collected, 0) + v_estimate.fee_amount,<br>        last_updated = NOW()<br>    WHERE asset_symbol = p_from_asset;<br><br>    IF NOT FOUND THEN<br>        INSERT INTO public.supported_assets_metrics (<br>            asset_symbol, total_swap_volume, total_swap_fees_collected, total_fees_collected,<br>            total_deposited, total_withdrawn, total_staked, total_user_balance, net_position, should_be_in_custody, last_updated<br>        ) VALUES (p_from_asset, p_from_amount, v_estimate.fee_amount, v_estimate.fee_amount, 0, 0, 0, 0, 0, 0, NOW());<br>    END IF;<br><br>    UPDATE public.supported_assets_metrics<br>    SET total_swap_volume = COALESCE(total_swap_volume, 0) + v_estimate.amount_out, last_updated = NOW()<br>    WHERE asset_symbol = p_to_asset;<br><br>    IF NOT FOUND THEN<br>        INSERT INTO public.supported_assets_metrics (<br>            asset_symbol, total_swap_volume, total_deposited, total_withdrawn, total_staked, total_user_balance, net_position, should_be_in_custody, last_updated<br>        ) VALUES (p_to_asset, v_estimate.amount_out, 0, 0, 0, 0, 0, 0, NOW());<br>    END IF;<br><br>    PERFORM fn_award_engagement_points(p_user_id, 'swap');<br><br>    RETURN QUERY SELECT<br>        TRUE,<br>        format('Swap réussi! %s %s → %s %s (frais: %s %s)',<br>               p_from_amount, p_from_asset, v_estimate.amount_out, p_to_asset, v_estimate.fee_amount, p_to_asset),<br>        v_transaction_id, p_from_amount, v_estimate.amount_out, v_estimate.rate, v_estimate.fee_amount, v_estimate.amount_out, true;<br><br>EXCEPTION<br>    WHEN OTHERS THEN<br>        RETURN QUERY SELECT FALSE, 'Erreur lors du swap: ' \|\| SQLERRM, NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | execute_swap_realtime               | p_user_id uuid, p_from_asset text, p_to_asset text, p_from_amount numeric, p_slippage_tolerance numeric, p_min_amount_out numeric                                                 | TABLE(success boolean, message text, transaction_id uuid, from_amount numeric, to_amount numeric, exchange_rate numeric, fee_amount numeric, net_to_amount numeric, realtime_price_used boolean)                                                                                                                                                                                                                                                                                                                | CREATE OR REPLACE FUNCTION public.execute_swap_realtime(p_user_id uuid, p_from_asset text, p_to_asset text, p_from_amount numeric, p_slippage_tolerance numeric DEFAULT 1.0, p_min_amount_out numeric DEFAULT NULL::numeric)<br> RETURNS TABLE(success boolean, message text, transaction_id uuid, from_amount numeric, to_amount numeric, exchange_rate numeric, fee_amount numeric, net_to_amount numeric, realtime_price_used boolean)<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>    v_estimate record;<br>    v_user_balance numeric;<br>    v_transaction_id uuid;<br>    v_swap_tx_id uuid;<br>    v_from_asset_record record;<br>    v_to_asset_record record;<br>    v_fee_rate numeric;<br>    v_treasury_to_balance numeric;<br>BEGIN<br>    IF p_from_asset = p_to_asset THEN<br>        RETURN QUERY SELECT<br>            FALSE, 'Impossible de swapper le même asset',<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    IF p_from_amount <= 0 THEN<br>        RETURN QUERY SELECT<br>            FALSE, 'Le montant doit être supérieur à 0',<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    SELECT * INTO v_from_asset_record<br>    FROM public.supported_assets<br>    WHERE symbol = p_from_asset AND is_active = true AND can_be_swapped = true;<br><br>    SELECT * INTO v_to_asset_record<br>    FROM public.supported_assets<br>    WHERE symbol = p_to_asset AND is_active = true AND can_be_swapped = true;<br><br>    IF v_from_asset_record IS NULL THEN<br>        RETURN QUERY SELECT<br>            FALSE, format('Swap non autorisé pour l''asset source: %s', p_from_asset),<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    IF v_to_asset_record IS NULL THEN<br>        RETURN QUERY SELECT<br>            FALSE, format('Swap non autorisé pour l''asset destination: %s', p_to_asset),<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    v_fee_rate := COALESCE(v_from_asset_record.swap_fee_percentage, 0.5);<br><br>    SELECT * INTO v_estimate<br>    FROM public.estimate_swap(p_from_asset, p_to_asset, p_from_amount, v_fee_rate);<br><br>    IF v_estimate.amount_out IS NULL OR v_estimate.amount_out <= 0 THEN<br>        RETURN QUERY SELECT<br>            FALSE, 'Impossible d''estimer le swap',<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    -- ✅ PROTECTION ANTI-SLIPPAGE : si l'appelant a fourni le montant minimum<br>    -- accepté (calculé au moment du devis affiché), on refuse le swap si le<br>    -- taux a bougé en dessous de ce seuil entre le devis et l'exécution.<br>    IF p_min_amount_out IS NOT NULL AND v_estimate.amount_out < p_min_amount_out THEN<br>        RETURN QUERY SELECT<br>            FALSE,<br>            format('Le taux a changé : %s %s reçus au lieu du minimum accepté de %s %s. Merci de reconfirmer.',<br>                   v_estimate.amount_out, p_to_asset, p_min_amount_out, p_to_asset),<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    SELECT available_balance INTO v_user_balance<br>    FROM public.user_balances<br>    WHERE user_id = p_user_id AND asset_symbol = p_from_asset;<br><br>    IF v_user_balance IS NULL OR v_user_balance < p_from_amount THEN<br>        RETURN QUERY SELECT<br>            FALSE,<br>            format('Solde insuffisant en %s. Disponible: %s, Requis: %s',<br>                   p_from_asset, COALESCE(v_user_balance, 0), p_from_amount),<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    SELECT balance INTO v_treasury_to_balance<br>    FROM public.treasury_wallets WHERE asset_symbol = p_to_asset FOR UPDATE;<br><br>    IF v_treasury_to_balance IS NULL OR v_treasury_to_balance < v_estimate.amount_out THEN<br>        RETURN QUERY SELECT<br>            FALSE,<br>            format('Réserve de liquidité insuffisante en %s pour ce swap. Réessayez avec un montant plus petit ou plus tard.', p_to_asset),<br>            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>        RETURN;<br>    END IF;<br><br>    INSERT INTO public.transactions (<br>        user_id, type, asset_symbol, network, amount, status, metadata<br>    ) VALUES (<br>        p_user_id, 'swap_debit', p_from_asset, v_from_asset_record.network, p_from_amount, 'completed',<br>        jsonb_build_object(<br>            'swap_type', 'asset_swap', 'to_asset', p_to_asset, 'exchange_rate', v_estimate.rate,<br>            'fee_percentage', v_fee_rate, 'slippage_tolerance', p_slippage_tolerance,<br>            'min_amount_out', p_min_amount_out<br>        )<br>    ) RETURNING id INTO v_swap_tx_id;<br><br>    UPDATE public.user_balances<br>    SET available_balance = available_balance - p_from_amount, updated_at = NOW()<br>    WHERE user_id = p_user_id AND asset_symbol = p_from_asset;<br><br>    INSERT INTO public.treasury_wallets (asset_symbol, balance, total_collected, total_burned, total_withdrawn, updated_at)<br>    VALUES (p_from_asset, p_from_amount, p_from_amount, 0, 0, NOW())<br>    ON CONFLICT (asset_symbol) DO UPDATE<br>    SET balance = treasury_wallets.balance + p_from_amount,<br>        total_collected = treasury_wallets.total_collected + p_from_amount,<br>        updated_at = NOW();<br><br>    UPDATE public.treasury_wallets<br>    SET balance = balance - v_estimate.amount_out, updated_at = NOW()<br>    WHERE asset_symbol = p_to_asset;<br><br>    INSERT INTO public.transactions (<br>        user_id, type, asset_symbol, network, amount, fee, net_amount, status, reference_id, metadata<br>    ) VALUES (<br>        p_user_id, 'swap_credit', p_to_asset, v_to_asset_record.network, v_estimate.amount_out,<br>        v_estimate.fee_amount, v_estimate.amount_out, 'completed', v_swap_tx_id,<br>        jsonb_build_object('swap_type', 'asset_swap', 'from_asset', p_from_asset, 'from_amount', p_from_amount, 'exchange_rate', v_estimate.rate)<br>    ) RETURNING id INTO v_transaction_id;<br><br>    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance)<br>    VALUES (p_user_id, p_to_asset, v_estimate.amount_out)<br>    ON CONFLICT (user_id, asset_symbol)<br>    DO UPDATE SET available_balance = user_balances.available_balance + v_estimate.amount_out, updated_at = NOW();<br><br>    IF v_estimate.fee_amount > 0 THEN<br>      INSERT INTO public.platform_fees (asset_symbol, amount, fee_type, source_user_id, source_transaction_id, collected_at)<br>      VALUES (p_to_asset, v_estimate.fee_amount, 'swap_fee', p_user_id, v_transaction_id, NOW());<br>    END IF;<br><br>    UPDATE public.supported_assets_metrics<br>    SET total_swap_volume = COALESCE(total_swap_volume, 0) + p_from_amount,<br>        total_swap_fees_collected = COALESCE(total_swap_fees_collected, 0) + v_estimate.fee_amount,<br>        total_fees_collected = COALESCE(total_fees_collected, 0) + v_estimate.fee_amount,<br>        last_updated = NOW()<br>    WHERE asset_symbol = p_from_asset;<br><br>    IF NOT FOUND THEN<br>        INSERT INTO public.supported_assets_metrics (<br>            asset_symbol, total_swap_volume, total_swap_fees_collected, total_fees_collected,<br>            total_deposited, total_withdrawn, total_staked, total_user_balance, net_position, should_be_in_custody, last_updated<br>        ) VALUES (p_from_asset, p_from_amount, v_estimate.fee_amount, v_estimate.fee_amount, 0, 0, 0, 0, 0, 0, NOW());<br>    END IF;<br><br>    UPDATE public.supported_assets_metrics<br>    SET total_swap_volume = COALESCE(total_swap_volume, 0) + v_estimate.amount_out, last_updated = NOW()<br>    WHERE asset_symbol = p_to_asset;<br><br>    IF NOT FOUND THEN<br>        INSERT INTO public.supported_assets_metrics (<br>            asset_symbol, total_swap_volume, total_deposited, total_withdrawn, total_staked, total_user_balance, net_position, should_be_in_custody, last_updated<br>        ) VALUES (p_to_asset, v_estimate.amount_out, 0, 0, 0, 0, 0, 0, NOW());<br>    END IF;<br><br>    PERFORM fn_award_engagement_points(p_user_id, 'swap');<br><br>    RETURN QUERY SELECT<br>        TRUE,<br>        format('Swap réussi! %s %s → %s %s (frais: %s %s)',<br>               p_from_amount, p_from_asset, v_estimate.amount_out, p_to_asset, v_estimate.fee_amount, p_to_asset),<br>        v_transaction_id, p_from_amount, v_estimate.amount_out, v_estimate.rate, v_estimate.fee_amount, v_estimate.amount_out, true;<br><br>EXCEPTION<br>    WHEN OTHERS THEN<br>        RETURN QUERY SELECT FALSE, 'Erreur lors du swap: ' \|\| SQLERRM, NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | execute_wheel_spin                  | p_user_id uuid, p_spin_type text, p_segment_id integer, p_spin_hash text, p_client_seed text, p_server_seed text, p_nonce integer                                                 | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.execute_wheel_spin(p_user_id uuid, p_spin_type text, p_segment_id integer, p_spin_hash text, p_client_seed text, p_server_seed text, p_nonce integer)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_config       RECORD;<br>  v_stats        RECORD;<br>  v_segment      RECORD;<br>  v_now          TIMESTAMPTZ := NOW();<br>  v_today        DATE        := CURRENT_DATE;<br>  v_spin_cost    NUMERIC     := 0;<br>  v_spin_asset   TEXT;<br>  v_jackpot_cut  NUMERIC     := 0;<br>  v_house_cut    NUMERIC     := 0;<br>  v_new_streak   INT;<br>  v_streak_bonus INT         := 0;<br>  v_daily        INTEGER;<br>  -- ✅ Suivi de la perte nette pour le signal de crédit (score_credit_capacity)<br>  v_payout_asset     TEXT;<br>  v_payout_amount    NUMERIC := 0;<br>  v_spin_price_usd   NUMERIC;<br>  v_payout_price_usd NUMERIC;<br>  v_net_loss_usd     NUMERIC;<br>  v_net_loss_native  NUMERIC;<br>BEGIN<br>  SELECT * INTO v_config  FROM public.wheel_config     WHERE id = 1              FOR UPDATE;<br>  SELECT * INTO v_stats   FROM public.user_wheel_stats WHERE user_id = p_user_id FOR UPDATE;<br>  SELECT * INTO v_segment FROM public.wheel_segments   WHERE id = p_segment_id AND is_active = true;<br><br>  v_spin_asset := v_config.paid_spin_cost_asset;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Segment invalide', 'error_code', 'INVALID_SEGMENT');<br>  END IF;<br>  IF NOT v_config.is_active THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Roue désactivée', 'error_code', 'WHEEL_DISABLED');<br>  END IF;<br><br>  IF p_spin_type = 'free' THEN<br><br>    IF v_stats.free_spins_reset_at <= v_now THEN<br>      v_daily := CASE WHEN public.fn_user_can_get_free_spins(p_user_id)<br>                       THEN v_config.free_spins_daily ELSE 0 END;<br>      UPDATE public.user_wheel_stats<br>      SET free_spins_remaining = v_daily,<br>          free_spins_reset_at  = date_trunc('day', v_now) + INTERVAL '1 day'<br>      WHERE user_id = p_user_id;<br>      v_stats.free_spins_remaining := v_daily;<br>    END IF;<br><br>    IF v_stats.free_spins_remaining <= 0 THEN<br>      RETURN jsonb_build_object('success', false, 'error', 'Aucun spin gratuit disponible', 'error_code', 'NO_FREE_SPINS');<br>    END IF;<br><br>    UPDATE public.user_wheel_stats<br>    SET free_spins_remaining  = free_spins_remaining - 1,<br>        total_free_spins_used = total_free_spins_used + 1<br>    WHERE user_id = p_user_id;<br><br>  ELSIF p_spin_type = 'paid' THEN<br>    v_spin_cost   := v_config.paid_spin_cost_amount;<br>    v_jackpot_cut := ROUND(v_spin_cost * v_config.jackpot_contribution_pct / 100, 8);<br>    v_house_cut   := v_spin_cost - v_jackpot_cut;<br><br>    IF NOT EXISTS (<br>      SELECT 1 FROM public.user_balances<br>      WHERE user_id = p_user_id AND asset_symbol = v_spin_asset<br>        AND available_balance >= v_spin_cost<br>    ) THEN<br>      RETURN jsonb_build_object('success', false, 'error', 'Solde ' \|\| v_spin_asset \|\| ' insuffisant', 'error_code', 'INSUFFICIENT_BALANCE');<br>    END IF;<br><br>    UPDATE public.user_balances<br>    SET available_balance = available_balance - v_spin_cost,<br>        updated_at        = v_now<br>    WHERE user_id = p_user_id AND asset_symbol = v_spin_asset;<br><br>    UPDATE public.wheel_config<br>    SET jackpot_current_amount = jackpot_current_amount + v_jackpot_cut,<br>        updated_at             = v_now<br>    WHERE id = 1;<br><br>    -- Comptabilité de trésorerie réelle : INCHANGÉE. Le coût brut du spin<br>    -- (moins la part jackpot) est bien physiquement encaissé, peu importe<br>    -- ce qui se passe ensuite avec la récompense.<br>    IF v_house_cut > 0 THEN<br>      PERFORM collect_fee_to_platform(v_spin_asset, v_house_cut, 'game_house_edge', p_user_id, NULL);<br>    END IF;<br><br>    INSERT INTO public.transactions (<br>      user_id, type, asset_symbol, amount, status, metadata, created_at<br>    ) VALUES (<br>      p_user_id, 'game_bet', v_spin_asset, v_spin_cost, 'completed',<br>      jsonb_build_object('spin_hash', p_spin_hash, 'spin_type', 'paid', 'game_type', 'wheel'),<br>      v_now<br>    );<br><br>    UPDATE public.user_wheel_stats<br>    SET total_paid_spins_used = total_paid_spins_used + 1,<br>        total_wakati_spent    = total_wakati_spent + v_spin_cost<br>    WHERE user_id = p_user_id;<br><br>    PERFORM fn_award_engagement_points(p_user_id, 'wheel_paid');<br><br>  ELSE<br>    RETURN jsonb_build_object('success', false, 'error', 'Type de spin invalide', 'error_code', 'INVALID_SPIN_TYPE');<br>  END IF;<br><br>  IF    v_stats.last_spin_date IS NULL                               THEN v_new_streak := 1;<br>  ELSIF v_stats.last_spin_date = v_today                             THEN v_new_streak := v_stats.current_streak;<br>  ELSIF v_stats.last_spin_date = v_today - INTERVAL '1 day'          THEN v_new_streak := v_stats.current_streak + 1;<br>  ELSE                                                                     v_new_streak := 1;<br>  END IF;<br><br>  IF v_new_streak > v_stats.current_streak<br>    AND v_config.streak_bonus_interval > 0<br>    AND v_new_streak % v_config.streak_bonus_interval = 0 THEN<br>    v_streak_bonus := v_config.streak_bonus_free_spins;<br>  END IF;<br><br>  IF v_segment.is_jackpot THEN<br>    DECLARE v_jackpot_amount NUMERIC;<br>    BEGIN<br>      SELECT jackpot_current_amount INTO v_jackpot_amount FROM public.wheel_config WHERE id = 1;<br>      IF v_jackpot_amount > 0 THEN<br>        INSERT INTO public.user_balances (user_id, asset_symbol, available_balance, updated_at)<br>        VALUES (p_user_id, v_config.jackpot_asset_symbol, v_jackpot_amount, v_now)<br>        ON CONFLICT (user_id, asset_symbol) DO UPDATE<br>        SET available_balance = user_balances.available_balance + v_jackpot_amount, updated_at = v_now;<br><br>        UPDATE public.wheel_config SET jackpot_current_amount = 0, updated_at = v_now WHERE id = 1;<br><br>        INSERT INTO public.transactions (<br>          user_id, type, asset_symbol, amount, status, metadata, created_at<br>        ) VALUES (<br>          p_user_id, 'game_win', v_config.jackpot_asset_symbol, v_jackpot_amount, 'completed',<br>          jsonb_build_object('spin_hash', p_spin_hash, 'game_type', 'wheel', 'reward_type', 'jackpot'),<br>          v_now<br>        );<br><br>        -- ✅ Payout suivi pour le calcul de perte nette (crédit)<br>        v_payout_asset  := v_config.jackpot_asset_symbol;<br>        v_payout_amount := v_jackpot_amount;<br>      END IF;<br>    END;<br><br>  ELSIF v_segment.reward_type = 'free_spins' THEN<br>    UPDATE public.user_wheel_stats<br>    SET free_spins_remaining = free_spins_remaining + COALESCE(v_segment.free_spins_reward, 0)<br>    WHERE user_id = p_user_id;<br>    -- Pas de valeur monétaire : ne compte pas comme un gain qui réduit la perte nette.<br><br>  ELSIF COALESCE(v_segment.reward_amount, 0) > 0 THEN<br>    DECLARE<br>      v_reward_amount NUMERIC;<br>      v_reward_asset  TEXT;<br>    BEGIN<br>      v_reward_asset  := COALESCE(v_segment.asset_symbol, v_spin_asset);<br>      v_reward_amount := CASE v_segment.reward_type<br>        WHEN 'fixed_amount'   THEN v_segment.reward_amount<br>        WHEN 'multiplier'     THEN v_spin_cost * v_segment.multiplier_value<br>        WHEN 'bet_multiplier' THEN v_spin_cost * v_segment.reward_amount<br>        ELSE 0<br>      END;<br><br>      IF v_reward_amount > 0 THEN<br>        INSERT INTO public.user_balances (user_id, asset_symbol, available_balance, updated_at)<br>        VALUES (p_user_id, v_reward_asset, v_reward_amount, v_now)<br>        ON CONFLICT (user_id, asset_symbol) DO UPDATE<br>        SET available_balance = user_balances.available_balance + v_reward_amount, updated_at = v_now;<br><br>        PERFORM fn_treasury_debit_for_payout(<br>          v_reward_asset, v_reward_amount, p_user_id, 'Recompense roue segment ' \|\| p_segment_id::text<br>        );<br><br>        INSERT INTO public.transactions (<br>          user_id, type, asset_symbol, amount, status, metadata, created_at<br>        ) VALUES (<br>          p_user_id, 'game_win', v_reward_asset, v_reward_amount, 'completed',<br>          jsonb_build_object('spin_hash', p_spin_hash, 'segment_id', p_segment_id,<br>                              'game_type', 'wheel', 'reward_type', v_segment.reward_type),<br>          v_now<br>        );<br><br>        -- ✅ Payout suivi pour le calcul de perte nette (crédit)<br>        v_payout_asset  := v_reward_asset;<br>        v_payout_amount := v_reward_amount;<br>      END IF;<br>    END;<br>  END IF;<br><br>  -- ══════════════════════════════════════════════════════════════════════<br>  -- ✅ SIGNAL DE CRÉDIT : perte nette réelle du spin payant (spin_cost -<br>  -- récompense payée sur CE spin), jamais négative. N'affecte QUE le calcul<br>  -- de capacité d'emprunt (fn_score_credit_capacity), pas la trésorerie.<br>  -- ══════════════════════════════════════════════════════════════════════<br>  IF p_spin_type = 'paid' AND v_spin_cost > 0 THEN<br>    SELECT price_usd INTO v_spin_price_usd FROM public.asset_prices WHERE asset_symbol = v_spin_asset;<br>    v_spin_price_usd := COALESCE(v_spin_price_usd, 0);<br><br>    IF v_payout_amount > 0 AND v_payout_asset IS NOT NULL THEN<br>      SELECT price_usd INTO v_payout_price_usd FROM public.asset_prices WHERE asset_symbol = v_payout_asset;<br>      v_payout_price_usd := COALESCE(v_payout_price_usd, 0);<br>    ELSE<br>      v_payout_price_usd := 0;<br>    END IF;<br><br>    IF v_spin_price_usd > 0 THEN<br>      v_net_loss_usd := GREATEST(v_spin_cost * v_spin_price_usd - v_payout_amount * v_payout_price_usd, 0);<br><br>      IF v_net_loss_usd > 0 THEN<br>        v_net_loss_native := v_net_loss_usd / v_spin_price_usd;<br><br>        INSERT INTO public.platform_fees (asset_symbol, amount, fee_type, source_user_id, collected_at)<br>        VALUES (v_spin_asset, v_net_loss_native, 'game_net_loss', p_user_id, v_now);<br>      END IF;<br>    END IF;<br>  END IF;<br><br>  UPDATE public.user_wheel_stats<br>  SET current_streak       = v_new_streak,<br>      longest_streak       = GREATEST(longest_streak, v_new_streak),<br>      last_spin_date       = v_today,<br>      total_spins          = total_spins + 1,<br>      free_spins_remaining = free_spins_remaining + v_streak_bonus,<br>      updated_at           = v_now<br>  WHERE user_id = p_user_id;<br><br>  INSERT INTO public.wheel_spins (<br>    user_id, segment_id, bet_amount, bet_asset,<br>    reward_amount, reward_asset, final_reward_amount,<br>    client_seed, server_seed, nonce, spin_hash, spin_result<br>  ) VALUES (<br>    p_user_id, p_segment_id,<br>    CASE WHEN p_spin_type = 'paid' THEN v_spin_cost ELSE 0 END,<br>    CASE WHEN p_spin_type = 'paid' THEN v_spin_asset ELSE NULL END,<br>    COALESCE(v_segment.reward_amount, 0), v_segment.asset_symbol, COALESCE(v_segment.reward_amount, 0),<br>    p_client_seed, p_server_seed, p_nonce, p_spin_hash,<br>    jsonb_build_object('spin_type', p_spin_type, 'segment', row_to_json(v_segment))<br>  );<br><br>  RETURN jsonb_build_object(<br>    'success',           true,<br>    'segment_id',        v_segment.id,<br>    'segment_label',     v_segment.label,<br>    'reward_type',       v_segment.reward_type,<br>    'reward_amount',     COALESCE(v_segment.reward_amount, 0),<br>    'reward_asset',      v_segment.asset_symbol,<br>    'is_jackpot',        COALESCE(v_segment.is_jackpot, false),<br>    'free_spins_reward', COALESCE(v_segment.free_spins_reward, 0),<br>    'streak',            v_new_streak,<br>    'streak_bonus',      v_streak_bonus,<br>    'spin_type',         p_spin_type,<br>    'spin_cost',         v_spin_cost,<br>    'spin_cost_asset',   v_spin_asset,<br>    'jackpot_amount',    (SELECT jackpot_current_amount FROM public.wheel_config WHERE id = 1)<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object(<br>    'success', false,<br>    'error', SQLERRM,<br>    'error_code', 'INTERNAL_ERROR'<br>  );<br>END;<br>$function$<br> |
| public      | fn_accrue_loan_interest             |                                                                                                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_accrue_loan_interest()<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_count int;<br>BEGIN<br>  WITH updated AS (<br>    UPDATE loans<br>    SET accrued_interest = accrued_interest +<br>          principal_amount * (apr_rate_snapshot / 100) *<br>          (EXTRACT(EPOCH FROM (now() - last_interest_accrual_at)) / (365 * 86400)),<br>        last_interest_accrual_at = now()<br>    WHERE status = 'active'<br>    RETURNING id<br>  )<br>  SELECT count(*) INTO v_count FROM updated;<br><br>  RETURN jsonb_build_object('success', true, 'loans_updated', v_count);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         |
| public      | fn_add_collateral                   | p_loan_id uuid, p_additional_amount numeric                                                                                                                                       | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_add_collateral(p_loan_id uuid, p_additional_amount numeric)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id       uuid := auth.uid();<br>  v_loan          loans%ROWTYPE;<br>  v_user_balance  numeric;<br>  v_price_collateral numeric;<br>  v_price_borrow      numeric;<br>  v_new_ltv           numeric;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  IF p_additional_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_loan FROM loans WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');<br>  END IF;<br><br>  SELECT available_balance INTO v_user_balance<br>  FROM user_balances WHERE user_id = v_user_id AND asset_symbol = v_loan.collateral_asset FOR UPDATE;<br><br>  IF NOT FOUND OR v_user_balance < p_additional_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant pour ajouter ce collateral');<br>  END IF;<br><br>  UPDATE user_balances SET available_balance = available_balance - p_additional_amount, updated_at = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_loan.collateral_asset;<br><br>  UPDATE loans SET collateral_amount = collateral_amount + p_additional_amount<br>  WHERE id = p_loan_id;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'loan_collateral_lock', v_loan.collateral_asset, p_additional_amount, p_additional_amount, 'completed', now(),<br>          jsonb_build_object('loan_id', p_loan_id, 'reason', 'top_up'));<br><br>  SELECT price_usd INTO v_price_collateral FROM asset_prices WHERE asset_symbol = v_loan.collateral_asset;<br>  SELECT price_usd INTO v_price_borrow     FROM asset_prices WHERE asset_symbol = v_loan.borrow_asset;<br><br>  v_new_ltv := ((v_loan.principal_amount + v_loan.accrued_interest) * v_price_borrow)<br>             / ((v_loan.collateral_amount + p_additional_amount) * v_price_collateral) * 100;<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'loan_id', p_loan_id,<br>    'collateral_total', v_loan.collateral_amount + p_additional_amount,<br>    'new_ltv_pct', ROUND(v_new_ltv, 2)<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         |
| public      | fn_admin_reclaim_user_balance       | p_user_id uuid, p_asset_symbol text, p_reason text, p_admin_id uuid                                                                                                               | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_admin_reclaim_user_balance(p_user_id uuid, p_asset_symbol text, p_reason text, p_admin_id uuid DEFAULT NULL::uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_available      numeric;<br>  v_staking        numeric;<br>  v_total          numeric;<br>  v_balance_before numeric;<br>  v_balance_after  numeric;<br>  v_stake          RECORD;<br>BEGIN<br>  SELECT available_balance, staking_balance INTO v_available, v_staking<br>  FROM public.user_balances<br>  WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Aucun solde pour cet utilisateur/asset');<br>  END IF;<br><br>  v_total := v_available + v_staking;<br>  IF v_total <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde deja nul');<br>  END IF;<br><br>  FOR v_stake IN<br>    SELECT id, pool_id, amount FROM public.user_stakes<br>    WHERE user_id = p_user_id AND status = 'active'<br>      AND pool_id IN (SELECT id FROM public.staking_pools WHERE asset_symbol = p_asset_symbol)<br>    FOR UPDATE<br>  LOOP<br>    UPDATE public.user_stakes<br>    SET amount = 0, status = 'unstaked', pending_rewards = 0, updated_at = now()<br>    WHERE id = v_stake.id;<br><br>    UPDATE public.staking_pools<br>    SET total_staked = GREATEST(0, total_staked - v_stake.amount), updated_at = now()<br>    WHERE id = v_stake.pool_id;<br>  END LOOP;<br><br>  UPDATE public.user_balances<br>  SET available_balance = 0,<br>      staking_balance   = 0,<br>      updated_at        = now()<br>  WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol;<br><br>  INSERT INTO public.treasury_wallets (asset_symbol, balance, total_collected)<br>  VALUES (p_asset_symbol, v_total, v_total)<br>  ON CONFLICT (asset_symbol) DO UPDATE SET<br>    balance = treasury_wallets.balance + v_total,<br>    total_collected = treasury_wallets.total_collected + v_total,<br>    updated_at = now()<br>  RETURNING balance, balance - v_total INTO v_balance_after, v_balance_before;<br><br>  INSERT INTO public.treasury_ledger (<br>    asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason<br>  ) VALUES (<br>    p_asset_symbol, 'admin_reclaim', v_total, v_balance_before, v_balance_after, p_admin_id, p_reason<br>  );<br><br>  INSERT INTO public.transactions (<br>    user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata<br>  ) VALUES (<br>    p_user_id, 'admin_reclaim', p_asset_symbol, v_total, v_total, 'completed', now(),<br>    jsonb_build_object('reason', p_reason, 'available_reclaimed', v_available, 'staking_reclaimed', v_staking)<br>  );<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'user_id', p_user_id,<br>    'asset_symbol', p_asset_symbol,<br>    'available_reclaimed', v_available,<br>    'staking_reclaimed', v_staking,<br>    'total_reclaimed', v_total,<br>    'treasury_balance_after', v_balance_after<br>  );<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              |
| public      | fn_admin_score_credit_status        | p_user_id uuid                                                                                                                                                                    | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_admin_score_credit_status(p_user_id uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_capacity jsonb;<br>  v_state    user_score_credit_state%ROWTYPE;<br>  v_active_loan score_loans%ROWTYPE;<br>BEGIN<br>  v_capacity := fn_score_credit_capacity(p_user_id);<br>  SELECT * INTO v_state FROM user_score_credit_state WHERE user_id = p_user_id;<br>  SELECT * INTO v_active_loan FROM score_loans WHERE user_id = p_user_id AND status = 'active';<br><br>  RETURN jsonb_build_object(<br>    'capacity', v_capacity,<br>    'conversion_rate_pct', COALESCE(v_state.conversion_rate_pct, 90),<br>    'default_count', COALESCE(v_state.default_count, 0),<br>    'last_default_at', v_state.last_default_at,<br>    'has_completed_first_loan', COALESCE(v_state.has_completed_first_loan, false),<br>    'active_loan', CASE WHEN v_active_loan.id IS NOT NULL THEN row_to_json(v_active_loan) ELSE NULL END<br>  );<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          |
| public      | fn_admin_set_wheel_currency         | p_asset text, p_spin_cost numeric, p_reset_jackpot boolean                                                                                                                        | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_admin_set_wheel_currency(p_asset text, p_spin_cost numeric, p_reset_jackpot boolean DEFAULT true)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_old RECORD;<br>BEGIN<br>  IF p_spin_cost <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Cout du spin invalide');<br>  END IF;<br><br>  IF NOT EXISTS (SELECT 1 FROM supported_assets WHERE symbol = p_asset AND is_active = true) THEN<br>    RETURN jsonb_build_object('success', false, 'error', p_asset \|\| ' n''est pas un actif actif/valide');<br>  END IF;<br><br>  SELECT paid_spin_cost_amount, paid_spin_cost_asset, jackpot_current_amount INTO v_old<br>  FROM wheel_config WHERE id = 1;<br><br>  UPDATE wheel_config<br>  SET paid_spin_cost_amount = p_spin_cost,<br>      paid_spin_cost_asset  = p_asset,<br>      jackpot_asset_symbol  = p_asset,<br>      jackpot_current_amount = CASE WHEN p_reset_jackpot THEN 0 ELSE jackpot_current_amount END,<br>      updated_at = now()<br>  WHERE id = 1;<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'previous_asset', v_old.paid_spin_cost_asset,<br>    'previous_cost', v_old.paid_spin_cost_amount,<br>    'previous_jackpot_wiped', CASE WHEN p_reset_jackpot THEN v_old.jackpot_current_amount ELSE 0 END,<br>    'new_asset', p_asset,<br>    'new_cost', p_spin_cost<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                |
| public      | fn_award_engagement_points          | p_user_id uuid, p_action_type text                                                                                                                                                | void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.fn_award_engagement_points(p_user_id uuid, p_action_type text)<br> RETURNS void<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_cfg score_action_config%ROWTYPE;<br>  v_points numeric;<br>BEGIN<br>  SELECT * INTO v_cfg FROM score_action_config WHERE action_type = p_action_type AND is_active = true;<br>  IF NOT FOUND THEN<br>    RETURN;<br>  END IF;<br><br>  v_points := v_cfg.points_min + floor(random() * (v_cfg.points_max - v_cfg.points_min + 1));<br><br>  INSERT INTO user_engagement_points (user_id, total_points, updated_at)<br>  VALUES (p_user_id, v_points, now())<br>  ON CONFLICT (user_id) DO UPDATE<br>  SET total_points = user_engagement_points.total_points + v_points, updated_at = now();<br>EXCEPTION WHEN OTHERS THEN<br>  -- Ne jamais casser l'action qui a declenche l'attribution de points<br>  NULL;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | fn_burn_tokens                      | p_asset_symbol text, p_amount numeric, p_reason text, p_admin_id uuid, p_tx_hash text                                                                                             | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_burn_tokens(p_asset_symbol text, p_amount numeric, p_reason text DEFAULT NULL::text, p_admin_id uuid DEFAULT NULL::uuid, p_tx_hash text DEFAULT NULL::text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_balance_before numeric;<br>  v_balance_after  numeric;<br>  v_burn_id        uuid;<br>BEGIN<br>  IF p_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT balance INTO v_balance_before<br>  FROM public.treasury_wallets<br>  WHERE asset_symbol = p_asset_symbol<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Aucune tresorerie pour cet asset');<br>  END IF;<br><br>  IF v_balance_before < p_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde tresorerie insuffisant pour ce burn',<br>                               'balance_disponible', v_balance_before);<br>  END IF;<br><br>  UPDATE public.treasury_wallets<br>  SET balance = balance - p_amount,<br>      total_burned = total_burned + p_amount,<br>      updated_at = now()<br>  WHERE asset_symbol = p_asset_symbol<br>  RETURNING balance INTO v_balance_after;<br><br>  INSERT INTO public.treasury_ledger (<br>    asset_symbol, entry_type, amount, balance_before, balance_after,<br>    performed_by, reason<br>  ) VALUES (<br>    p_asset_symbol, 'burn', p_amount, v_balance_before, v_balance_after,<br>    p_admin_id, p_reason<br>  );<br><br>  INSERT INTO public.token_burns (<br>    asset_symbol, amount, reason, burned_by, tx_hash, status, source<br>  ) VALUES (<br>    p_asset_symbol, p_amount, p_reason, p_admin_id, p_tx_hash, 'completed', 'treasury'<br>  ) RETURNING id INTO v_burn_id;<br><br>  UPDATE public.supported_assets_metrics<br>  SET total_burned = total_burned + p_amount, last_updated = now()<br>  WHERE asset_symbol = p_asset_symbol;<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'burn_id', v_burn_id,<br>    'asset_symbol', p_asset_symbol,<br>    'amount_burned', p_amount,<br>    'treasury_balance_after', v_balance_after<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | fn_check_and_liquidate_loans        |                                                                                                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_check_and_liquidate_loans()<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_loan RECORD;<br>  v_liquidated_count int := 0;<br>BEGIN<br>  FOR v_loan IN SELECT id FROM loans WHERE status = 'active' LOOP<br>    IF (fn_liquidate_loan(v_loan.id)->>'success')::boolean THEN<br>      v_liquidated_count := v_liquidated_count + 1;<br>    END IF;<br>  END LOOP;<br><br>  RETURN jsonb_build_object('success', true, 'loans_liquidated', v_liquidated_count);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          |
| public      | fn_check_score_loan_defaults        |                                                                                                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_check_score_loan_defaults()<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_config score_credit_config%ROWTYPE;<br>  v_loan   RECORD;<br>  v_interest numeric;<br>  v_count  int := 0;<br>BEGIN<br>  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;<br><br>  FOR v_loan IN SELECT * FROM score_loans WHERE status = 'active' AND grace_until < now() FOR UPDATE LOOP<br>    v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100<br>                  * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);<br><br>    UPDATE score_loans<br>    SET status = 'defaulted', accrued_interest = v_interest, closed_at = now()<br>    WHERE id = v_loan.id;<br><br>    INSERT INTO user_score_credit_state (user_id, conversion_rate_pct, default_count, last_default_at, updated_at)<br>    VALUES (v_loan.user_id, v_config.conversion_rate_base_pct, 1, now(), now())<br>    ON CONFLICT (user_id) DO UPDATE<br>    SET conversion_rate_pct = v_config.conversion_rate_base_pct,<br>        default_count = user_score_credit_state.default_count + 1,<br>        last_default_at = now(),<br>        updated_at = now();<br><br>    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>    VALUES (v_loan.user_id, 'score_loan_defaulted', v_loan.asset_symbol, v_loan.principal_amount + v_interest,<br>            v_loan.principal_amount + v_interest, 'completed', now(), jsonb_build_object('loan_id', v_loan.id));<br><br>    INSERT INTO notifications (user_id, type, title, message, data)<br>    VALUES (v_loan.user_id, 'score_loan_defaulted', 'Pret en retard',<br>            'Ton pret n''a pas ete rembourse a temps. Tes prochains credits serviront en priorite a le solder.',<br>            jsonb_build_object('loan_id', v_loan.id));<br><br>    v_count := v_count + 1;<br>  END LOOP;<br><br>  RETURN jsonb_build_object('processed', v_count);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | fn_compute_wakati_daily_price       |                                                                                                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_compute_wakati_daily_price()<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_state          public.wakati_reserve_state%ROWTYPE;<br>  v_period_start   timestamptz := date_trunc('day', now()) - interval '1 day';<br>  v_period_end     timestamptz := date_trunc('day', now());<br>  v_revenue_usd    numeric;<br>  v_payouts_usd    numeric;<br>  v_net_profit_usd numeric;<br>  v_contribution   numeric;<br>  v_reserve_new    numeric;<br>  v_circulating    numeric;<br>  v_price_old      numeric;<br>  v_raw_price      numeric;<br>  v_min_allowed    numeric;<br>  v_max_allowed    numeric;<br>  v_capped_price   numeric;<br>  v_final_price    numeric;<br>  v_was_capped     boolean := false;<br>BEGIN<br>  SELECT * INTO v_state FROM public.wakati_reserve_state WHERE id = 1 FOR UPDATE;<br>  IF NOT FOUND OR NOT v_state.is_active THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Systeme de prix WAKATI inactif ou non configure');<br>  END IF;<br><br>  SELECT COALESCE(SUM(pf.amount * ap.price_usd), 0) INTO v_revenue_usd<br>  FROM public.platform_fees pf<br>  JOIN public.asset_prices ap ON ap.asset_symbol = pf.asset_symbol<br>  WHERE pf.is_test = false<br>    AND pf.fee_type != 'game_net_loss'<br>    AND pf.collected_at >= v_period_start<br>    AND pf.collected_at < v_period_end;<br><br>  SELECT COALESCE(SUM(t.amount * ap.price_usd), 0) INTO v_payouts_usd<br>  FROM public.transactions t<br>  JOIN public.asset_prices ap ON ap.asset_symbol = t.asset_symbol<br>  WHERE t.type IN ('game_win', 'referral_bonus', 'staking_reward')<br>    AND t.status = 'completed'<br>    AND t.created_at >= v_period_start<br>    AND t.created_at < v_period_end;<br><br>  v_net_profit_usd := v_revenue_usd - v_payouts_usd;<br><br>  -- ✅ Un mauvais jour retire désormais vraiment de la réserve (même taux<br>  -- que la contribution positive), au lieu de simplement ne rien ajouter.<br>  -- La réserve elle-même ne descend jamais sous 0.<br>  v_contribution := v_net_profit_usd * v_state.profit_share_pct / 100;<br>  v_reserve_new  := GREATEST(v_state.reserve_usd + v_contribution, 0);<br><br>  -- Offre en circulation = détenue par les utilisateurs (exclut la trésorerie<br>  -- non distribuée). Si le staking dilue (mint sans contrepartie), ce nombre<br>  -- grossit et fait mécaniquement baisser raw_price ci-dessous.<br>  SELECT COALESCE(SUM(available_balance), 0) INTO v_circulating<br>  FROM public.user_balances WHERE asset_symbol = 'WAKATI';<br><br>  SELECT price_usd INTO v_price_old FROM public.asset_prices WHERE asset_symbol = 'WAKATI';<br><br>  IF v_circulating <= 0 THEN<br>    v_raw_price := v_price_old;<br>  ELSE<br>    v_raw_price := v_reserve_new / v_circulating;<br>  END IF;<br><br>  -- Plafond de variation quotidienne, dans les DEUX sens désormais utile.<br>  v_min_allowed  := v_price_old * (1 - v_state.max_daily_change_pct / 100);<br>  v_max_allowed  := v_price_old * (1 + v_state.max_daily_change_pct / 100);<br>  v_capped_price := LEAST(GREATEST(v_raw_price, v_min_allowed), v_max_allowed);<br>  v_was_capped   := (v_capped_price != v_raw_price);<br><br>  -- Mur ultime : jamais en dessous du plancher, quoi qu'il arrive.<br>  v_final_price := GREATEST(v_capped_price, v_state.price_floor_usd);<br><br>  UPDATE public.asset_prices SET price_usd = v_final_price, updated_at = now() WHERE asset_symbol = 'WAKATI';<br><br>  UPDATE public.wakati_reserve_state<br>  SET reserve_usd = v_reserve_new, last_computed_at = now(), updated_at = now()<br>  WHERE id = 1;<br><br>  INSERT INTO public.wakati_price_history (<br>    computed_for_date, net_profit_usd, reserve_contribution_usd, reserve_usd_after,<br>    circulating_supply, price_before_usd, raw_price_usd, final_price_usd, was_capped<br>  ) VALUES (<br>    v_period_start::date, v_net_profit_usd, v_contribution, v_reserve_new,<br>    v_circulating, v_price_old, v_raw_price, v_final_price, v_was_capped<br>  );<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'period', v_period_start::date,<br>    'net_profit_usd', v_net_profit_usd,<br>    'reserve_contribution_usd', v_contribution,<br>    'reserve_usd', v_reserve_new,<br>    'circulating_supply', v_circulating,<br>    'price_old', v_price_old,<br>    'price_new', v_final_price,<br>    'was_capped', v_was_capped<br>  );<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| public      | fn_confirm_withdrawal_fee           | p_transaction_id uuid                                                                                                                                                             | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_confirm_withdrawal_fee(p_transaction_id uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_tx transactions%ROWTYPE;<br>  v_fee_id uuid;<br>BEGIN<br>  SELECT * INTO v_tx FROM transactions<br>  WHERE id = p_transaction_id AND type = 'withdrawal'<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Transaction introuvable');<br>  END IF;<br><br>  IF v_tx.fee IS NULL OR v_tx.fee <= 0 THEN<br>    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'Aucun frais a collecter');<br>  END IF;<br><br>  -- Idempotence : si un frais a deja ete collecte pour cette transaction, on sort.<br>  IF EXISTS (<br>    SELECT 1 FROM platform_fees<br>    WHERE source_transaction_id = p_transaction_id AND fee_type = 'withdraw_fee'<br>  ) THEN<br>    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'Frais deja collecte');<br>  END IF;<br><br>  v_fee_id := collect_fee_to_platform(v_tx.asset_symbol, v_tx.fee, 'withdraw_fee', v_tx.user_id, p_transaction_id);<br><br>  RETURN jsonb_build_object('success', v_fee_id IS NOT NULL, 'fee_id', v_fee_id, 'fee_collected', v_tx.fee);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       |
| public      | fn_extend_score_loan                | p_loan_id uuid, p_preview boolean                                                                                                                                                 | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_extend_score_loan(p_loan_id uuid, p_preview boolean DEFAULT false)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id      uuid := auth.uid();<br>  v_loan         score_loans%ROWTYPE;<br>  v_config       score_credit_config%ROWTYPE;<br>  v_interest     numeric;<br>  v_new_principal numeric;<br>  v_fee          numeric;<br>  v_balance      numeric;<br>  v_new_apr      numeric;<br>  v_new_due_at   timestamptz;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  SELECT * INTO v_loan FROM score_loans<br>  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active'<br>  FOR UPDATE;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');<br>  END IF;<br><br>  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;<br><br>  IF now() > v_loan.grace_until THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Delai de grace depasse, extension indisponible');<br>  END IF;<br><br>  IF v_loan.extensions_used >= v_config.max_extensions_per_loan THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Nombre maximum de prolongations atteint pour ce pret');<br>  END IF;<br><br>  v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100<br>                * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);<br>  v_new_principal := v_loan.principal_amount + v_interest;<br>  v_fee := ROUND(v_new_principal * v_config.extension_fee_pct / 100, 8);<br>  v_new_apr := v_loan.apr_rate_snapshot + v_config.extension_apr_surcharge_pct;<br>  v_new_due_at := now() + (v_config.extension_days \|\| ' days')::interval;<br><br>  IF p_preview THEN<br>    RETURN jsonb_build_object(<br>      'success', true, 'preview', true, 'fee_charged', v_fee, 'fee_asset', v_loan.asset_symbol,<br>      'new_principal_owed', v_new_principal, 'current_apr_rate_pct', v_loan.apr_rate_snapshot,<br>      'new_apr_rate_pct', v_new_apr, 'new_due_at', v_new_due_at,<br>      'extensions_used', v_loan.extensions_used, 'extensions_remaining', v_config.max_extensions_per_loan - v_loan.extensions_used<br>    );<br>  END IF;<br><br>  SELECT available_balance INTO v_balance FROM user_balances<br>  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol FOR UPDATE;<br>  IF NOT FOUND OR v_balance < v_fee THEN<br>    RETURN jsonb_build_object(<br>      'success', false, 'error', 'Solde insuffisant pour payer le frais de prolongation',<br>      'fee_required', v_fee, 'asset_symbol', v_loan.asset_symbol<br>    );<br>  END IF;<br><br>  UPDATE user_balances SET available_balance = available_balance - v_fee, updated_at = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol;<br><br>  PERFORM collect_fee_to_platform(v_loan.asset_symbol, v_fee, 'score_loan_extension_fee', v_user_id, NULL);<br><br>  UPDATE score_loans SET<br>    principal_amount = v_new_principal,<br>    accrued_interest = 0,<br>    apr_rate_snapshot = v_new_apr,<br>    opened_at = now(),<br>    due_at = v_new_due_at,<br>    grace_until = v_new_due_at + (v_config.grace_period_hours \|\| ' hours')::interval,<br>    extensions_used = extensions_used + 1<br>  WHERE id = p_loan_id;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'score_loan_extended', v_loan.asset_symbol, v_fee, v_fee, 'completed', now(),<br>          jsonb_build_object('loan_id', p_loan_id, 'new_principal', v_new_principal, 'new_apr_rate_pct', v_new_apr, 'new_due_at', v_new_due_at));<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'preview', false, 'fee_charged', v_fee, 'fee_asset', v_loan.asset_symbol,<br>    'new_principal_owed', v_new_principal, 'new_apr_rate_pct', v_new_apr, 'new_due_at', v_new_due_at,<br>    'extensions_used', v_loan.extensions_used + 1, 'extensions_remaining', v_config.max_extensions_per_loan - (v_loan.extensions_used + 1)<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | fn_get_prediction_state             |                                                                                                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_get_prediction_state()<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id   uuid := auth.uid();<br>  v_active    jsonb;<br>  v_stats     jsonb;<br>  v_config    jsonb;<br>  v_balance   numeric;<br>  v_bets_today int;<br>  v_history   jsonb;<br>BEGIN<br>  -- Config<br>  SELECT jsonb_build_object(<br>    'asset_symbol',    asset_symbol,<br>    'asset_name',      asset_name,<br>    'bet_amount',      bet_amount,<br>    'bet_mode',        bet_mode,<br>    'bet_min',         bet_min,<br>    'bet_max',         bet_max,<br>    'win_multiplier',  win_multiplier,<br>    'duration_seconds',duration_seconds,<br>    'max_bets_per_day',max_bets_per_day,<br>    'cooldown_seconds',cooldown_seconds,<br>    'currency_symbol', currency_symbol,<br>    'is_active',       is_active<br>  ) INTO v_config FROM prediction_config WHERE id = 1;<br><br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('config', v_config);<br>  END IF;<br><br>  -- Solde disponible<br>  SELECT available_balance INTO v_balance<br>  FROM user_balances WHERE user_id = v_user_id AND asset_symbol = (SELECT currency_symbol FROM prediction_config WHERE id = 1);<br><br>  -- Paris du jour<br>  SELECT COUNT(*) INTO v_bets_today<br>  FROM prediction_bets<br>  WHERE user_id = v_user_id AND bet_at >= CURRENT_DATE AND status != 'cancelled';<br><br>  -- Pari actif en cours<br>  SELECT to_jsonb(pb.*) INTO v_active<br>  FROM prediction_bets pb<br>  WHERE user_id = v_user_id AND status = 'pending'<br>  ORDER BY bet_at DESC LIMIT 1;<br><br>  -- Stats utilisateur<br>  SELECT to_jsonb(s.*) INTO v_stats<br>  FROM prediction_user_stats s<br>  WHERE user_id = v_user_id;<br><br>  -- Historique 10 derniers paris<br>  SELECT jsonb_agg(<br>    jsonb_build_object(<br>      'id',                  id,<br>      'direction',           direction,<br>      'bet_amount',          bet_amount,<br>      'status',              status,<br>      'price_at_bet',        price_at_bet,<br>      'price_at_resolution', price_at_resolution,<br>      'profit_amount',       profit_amount,<br>      'bet_at',              bet_at,<br>      'resolved_at',         resolved_at<br>    ) ORDER BY bet_at DESC<br>  ) INTO v_history<br>  FROM (<br>    SELECT * FROM prediction_bets<br>    WHERE user_id = v_user_id AND status != 'pending'<br>    ORDER BY bet_at DESC LIMIT 10<br>  ) sub;<br><br>  RETURN jsonb_build_object(<br>    'config',       v_config,<br>    'balance',      COALESCE(v_balance, 0),<br>    'bets_today',   v_bets_today,<br>    'active_bet',   v_active,<br>    'stats',        COALESCE(v_stats, '{}'::jsonb),<br>    'history',      COALESCE(v_history, '[]'::jsonb)<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | fn_liquidate_loan                   | p_loan_id uuid                                                                                                                                                                    | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_liquidate_loan(p_loan_id uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_loan               loans%ROWTYPE;<br>  v_penalty_pct        numeric;<br>  v_price_collateral   numeric;<br>  v_price_borrow       numeric;<br>  v_debt               numeric;<br>  v_debt_usd           numeric;<br>  v_collateral_usd     numeric;<br>  v_ltv                numeric;<br>  v_collateral_needed  numeric;<br>  v_surplus            numeric;<br>  v_penalty            numeric;<br>  v_to_treasury        numeric;<br>  v_to_user            numeric;<br>  v_treasury_before    numeric;<br>BEGIN<br>  SELECT * INTO v_loan FROM loans WHERE id = p_loan_id AND status = 'active' FOR UPDATE;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');<br>  END IF;<br><br>  SELECT liquidation_penalty_pct INTO v_penalty_pct FROM lending_collateral_config WHERE asset_symbol = v_loan.collateral_asset;<br>  v_penalty_pct := COALESCE(v_penalty_pct, 0);<br><br>  SELECT price_usd INTO v_price_collateral FROM asset_prices WHERE asset_symbol = v_loan.collateral_asset;<br>  SELECT price_usd INTO v_price_borrow     FROM asset_prices WHERE asset_symbol = v_loan.borrow_asset;<br><br>  IF v_price_collateral IS NULL OR v_price_borrow IS NULL OR v_price_collateral <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible, liquidation impossible');<br>  END IF;<br><br>  v_debt           := v_loan.principal_amount + v_loan.accrued_interest;<br>  v_debt_usd       := v_debt * v_price_borrow;<br>  v_collateral_usd := v_loan.collateral_amount * v_price_collateral;<br>  v_ltv            := (v_debt_usd / v_collateral_usd) * 100;<br><br>  IF v_ltv < v_loan.liquidation_ltv_snapshot THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'LTV encore sain, pas de liquidation necessaire', 'ltv_actuel', ROUND(v_ltv,2));<br>  END IF;<br><br>  v_collateral_needed := LEAST(v_loan.collateral_amount, v_debt_usd / v_price_collateral);<br>  v_surplus           := v_loan.collateral_amount - v_collateral_needed;<br>  v_penalty           := ROUND(v_surplus * v_penalty_pct / 100, 8);<br>  v_to_user            := v_surplus - v_penalty;<br>  v_to_treasury         := v_collateral_needed + v_penalty;<br><br>  SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.collateral_asset FOR UPDATE;<br><br>  INSERT INTO treasury_wallets (asset_symbol, balance, total_collected)<br>  VALUES (v_loan.collateral_asset, v_to_treasury, v_to_treasury)<br>  ON CONFLICT (asset_symbol) DO UPDATE<br>  SET balance = treasury_wallets.balance + v_to_treasury, total_collected = treasury_wallets.total_collected + v_to_treasury, updated_at = now();<br><br>  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, reason)<br>  VALUES (v_loan.collateral_asset, 'liquidation', v_to_treasury, COALESCE(v_treasury_before,0), COALESCE(v_treasury_before,0) + v_to_treasury,<br>          'Liquidation pret ' \|\| p_loan_id::text \|\| ' - LTV ' \|\| ROUND(v_ltv,2)::text \|\| '% (dont penalite ' \|\| v_penalty::text \|\| ')');<br><br>  IF v_to_user > 0 THEN<br>    UPDATE user_balances SET available_balance = available_balance + v_to_user, updated_at = now()<br>    WHERE user_id = v_loan.user_id AND asset_symbol = v_loan.collateral_asset;<br><br>    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>    VALUES (v_loan.user_id, 'loan_collateral_release', v_loan.collateral_asset, v_to_user, v_to_user, 'completed', now(),<br>            jsonb_build_object('loan_id', p_loan_id, 'reason', 'liquidation_surplus', 'penalty_deducted', v_penalty));<br>  END IF;<br><br>  INSERT INTO loan_liquidations (<br>    loan_id, collateral_to_treasury, collateral_to_user, debt_settled,<br>    collateral_price_usd, borrow_price_usd, ltv_at_liquidation<br>  ) VALUES (<br>    p_loan_id, v_to_treasury, v_to_user, v_debt, v_price_collateral, v_price_borrow, v_ltv<br>  );<br><br>  UPDATE loans SET status = 'liquidated', closed_at = now() WHERE id = p_loan_id;<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'loan_id', p_loan_id, 'ltv_at_liquidation', ROUND(v_ltv,2),<br>    'collateral_to_treasury', v_to_treasury, 'penalty_amount', v_penalty,<br>    'collateral_returned_to_user', v_to_user<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  |
| public      | fn_open_loan                        | p_collateral_asset text, p_collateral_amount numeric, p_borrow_asset text, p_borrow_amount numeric                                                                                | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_open_loan(p_collateral_asset text, p_collateral_amount numeric, p_borrow_asset text, p_borrow_amount numeric)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id            uuid := auth.uid();<br>  v_coll_cfg           lending_collateral_config%ROWTYPE;<br>  v_borrow_cfg         lending_borrow_config%ROWTYPE;<br>  v_existing_loan       loans%ROWTYPE;<br>  v_price_collateral   numeric;<br>  v_price_borrow       numeric;<br>  v_ltv_pct            numeric;<br>  v_combined_collateral numeric;<br>  v_combined_debt       numeric;<br>  v_collateral_needed  numeric;<br>  v_collateral_balance numeric;<br>  v_treasury_balance   numeric;<br>  v_current_exposure   numeric;<br>  v_loan_id            uuid;<br>  v_merged              boolean := false;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  IF p_collateral_asset = p_borrow_asset THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Le collateral et l''emprunt doivent etre des actifs differents');<br>  END IF;<br><br>  IF p_collateral_amount <= 0 OR p_borrow_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montants invalides');<br>  END IF;<br><br>  SELECT * INTO v_coll_cfg FROM lending_collateral_config WHERE asset_symbol = p_collateral_asset AND is_active = true;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', p_collateral_asset \|\| ' n''est pas utilisable comme collateral');<br>  END IF;<br><br>  SELECT * INTO v_borrow_cfg FROM lending_borrow_config WHERE asset_symbol = p_borrow_asset AND is_active = true;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', p_borrow_asset \|\| ' n''est pas empruntable');<br>  END IF;<br><br>  IF p_borrow_amount < v_borrow_cfg.min_borrow_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant en dessous du minimum autorise', 'minimum', v_borrow_cfg.min_borrow_amount);<br>  END IF;<br><br>  IF v_borrow_cfg.max_borrow_amount IS NOT NULL AND p_borrow_amount > v_borrow_cfg.max_borrow_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant au dessus du maximum autorise', 'maximum', v_borrow_cfg.max_borrow_amount);<br>  END IF;<br><br>  IF v_borrow_cfg.max_total_borrowed IS NOT NULL THEN<br>    SELECT COALESCE(SUM(principal_amount), 0) INTO v_current_exposure<br>    FROM loans WHERE borrow_asset = p_borrow_asset AND status = 'active';<br><br>    IF v_current_exposure + p_borrow_amount > v_borrow_cfg.max_total_borrowed THEN<br>      RETURN jsonb_build_object('success', false, 'error', 'Plafond d''exposition atteint pour ' \|\| p_borrow_asset,<br>                                 'exposition_actuelle', v_current_exposure, 'plafond', v_borrow_cfg.max_total_borrowed);<br>    END IF;<br>  END IF;<br><br>  SELECT price_usd INTO v_price_collateral FROM asset_prices WHERE asset_symbol = p_collateral_asset;<br>  SELECT price_usd INTO v_price_borrow     FROM asset_prices WHERE asset_symbol = p_borrow_asset;<br><br>  IF v_price_collateral IS NULL OR v_price_borrow IS NULL OR v_price_collateral <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible pour cet actif');<br>  END IF;<br><br>  -- Chercher un pret actif existant avec exactement le meme couple collateral/emprunt<br>  SELECT * INTO v_existing_loan FROM loans<br>  WHERE user_id = v_user_id AND collateral_asset = p_collateral_asset<br>    AND borrow_asset = p_borrow_asset AND status = 'active'<br>  FOR UPDATE;<br><br>  IF FOUND THEN<br>    v_merged := true;<br>    v_combined_collateral := v_existing_loan.collateral_amount + p_collateral_amount;<br>    v_combined_debt := v_existing_loan.principal_amount + v_existing_loan.accrued_interest + p_borrow_amount;<br>    v_ltv_pct := (v_combined_debt * v_price_borrow) / (v_combined_collateral * v_price_collateral) * 100;<br>  ELSE<br>    v_ltv_pct := (p_borrow_amount * v_price_borrow) / (p_collateral_amount * v_price_collateral) * 100;<br>  END IF;<br><br>  IF v_ltv_pct > v_coll_cfg.max_ltv_pct THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'LTV trop eleve pour ce collateral',<br>                               'ltv_demande', ROUND(v_ltv_pct,2), 'ltv_max', v_coll_cfg.max_ltv_pct);<br>  END IF;<br><br>  v_collateral_needed := p_collateral_amount + v_coll_cfg.fixed_fee_amount;<br><br>  SELECT available_balance INTO v_collateral_balance<br>  FROM user_balances WHERE user_id = v_user_id AND asset_symbol = p_collateral_asset FOR UPDATE;<br><br>  IF NOT FOUND OR v_collateral_balance < v_collateral_needed THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde collateral insuffisant (collateral + frais requis)');<br>  END IF;<br><br>  SELECT balance INTO v_treasury_balance FROM treasury_wallets WHERE asset_symbol = p_borrow_asset FOR UPDATE;<br>  IF NOT FOUND OR v_treasury_balance < p_borrow_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Liquidite insuffisante en tresorerie pour cet actif',<br>                               'demande', p_borrow_amount, 'disponible', COALESCE(v_treasury_balance,0));<br>  END IF;<br><br>  UPDATE user_balances SET available_balance = available_balance - v_collateral_needed, updated_at = now()<br>  WHERE user_id = v_user_id AND asset_symbol = p_collateral_asset;<br><br>  INSERT INTO user_balances (user_id, asset_symbol, available_balance, updated_at)<br>  VALUES (v_user_id, p_borrow_asset, p_borrow_amount, now())<br>  ON CONFLICT (user_id, asset_symbol) DO UPDATE<br>  SET available_balance = user_balances.available_balance + p_borrow_amount, updated_at = now();<br><br>  UPDATE treasury_wallets<br>  SET balance = balance - p_borrow_amount, total_withdrawn = total_withdrawn + p_borrow_amount, updated_at = now()<br>  WHERE asset_symbol = p_borrow_asset;<br><br>  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)<br>  VALUES (p_borrow_asset, 'loan_disbursement', p_borrow_amount, v_treasury_balance, v_treasury_balance - p_borrow_amount,<br>          v_user_id, CASE WHEN v_merged THEN 'Ajout a un pret existant' ELSE 'Ouverture pret' END);<br><br>  IF v_coll_cfg.fixed_fee_amount > 0 THEN<br>    PERFORM collect_fee_to_platform(p_collateral_asset, v_coll_cfg.fixed_fee_amount, 'loan_origination_fee', v_user_id, NULL);<br>  END IF;<br><br>  IF v_merged THEN<br>    -- Fusionner avec le pret actif existant plutot que d'en creer un second<br>    UPDATE loans SET<br>      collateral_amount  = collateral_amount + p_collateral_amount,<br>      principal_amount   = principal_amount + p_borrow_amount,<br>      fixed_fee_charged  = fixed_fee_charged + v_coll_cfg.fixed_fee_amount<br>    WHERE id = v_existing_loan.id;<br><br>    v_loan_id := v_existing_loan.id;<br>  ELSE<br>    INSERT INTO loans (<br>      user_id, collateral_asset, collateral_amount, borrow_asset, principal_amount,<br>      apr_rate_snapshot, liquidation_ltv_snapshot, fixed_fee_charged, fixed_fee_asset<br>    ) VALUES (<br>      v_user_id, p_collateral_asset, p_collateral_amount, p_borrow_asset, p_borrow_amount,<br>      v_borrow_cfg.apr_rate_pct, v_coll_cfg.liquidation_ltv_pct, v_coll_cfg.fixed_fee_amount, p_collateral_asset<br>    ) RETURNING id INTO v_loan_id;<br>  END IF;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'loan_collateral_lock', p_collateral_asset, p_collateral_amount, p_collateral_amount, 'completed', now(),<br>          jsonb_build_object('loan_id', v_loan_id, 'merged', v_merged));<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'loan_borrowed', p_borrow_asset, p_borrow_amount, p_borrow_amount, 'completed', now(),<br>          jsonb_build_object('loan_id', v_loan_id, 'merged', v_merged));<br><br>  IF v_coll_cfg.fixed_fee_amount > 0 THEN<br>    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>    VALUES (v_user_id, 'fee', p_collateral_asset, v_coll_cfg.fixed_fee_amount, v_coll_cfg.fixed_fee_amount, 'completed', now(),<br>            jsonb_build_object('loan_id', v_loan_id, 'fee_type', 'loan_origination_fee'));<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'loan_id', v_loan_id, 'merged', v_merged, 'ltv_pct', ROUND(v_ltv_pct,2),<br>    'collateral_locked', p_collateral_amount, 'borrowed', p_borrow_amount,<br>    'fixed_fee_charged', v_coll_cfg.fixed_fee_amount, 'fixed_fee_asset', p_collateral_asset,<br>    'apr_rate_pct', v_borrow_cfg.apr_rate_pct<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   |
| public      | fn_open_score_loan                  | p_user_id uuid, p_asset_symbol text, p_amount numeric                                                                                                                             | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_open_score_loan(p_user_id uuid, p_asset_symbol text, p_amount numeric)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_config       score_credit_config%ROWTYPE;<br>  v_asset_cfg    score_loan_asset_config%ROWTYPE;<br>  v_state        user_score_credit_state%ROWTYPE;<br>  v_capacity     jsonb;<br>  v_price        numeric;<br>  v_amount_usd   numeric;<br>  v_fee          numeric;<br>  v_net          numeric;<br>  v_treasury_before numeric;<br>  v_loan_id      uuid;<br>  v_due_at       timestamptz;<br>BEGIN<br>  IF auth.uid() IS DISTINCT FROM p_user_id THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');<br>  END IF;<br><br>  IF p_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;<br><br>  SELECT * INTO v_asset_cfg FROM score_loan_asset_config WHERE asset_symbol = p_asset_symbol AND is_active = true;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', p_asset_symbol \|\| ' non disponible pour ce type de pret');<br>  END IF;<br><br>  IF p_amount < v_asset_cfg.min_borrow_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant en dessous du minimum', 'minimum', v_asset_cfg.min_borrow_amount);<br>  END IF;<br><br>  -- Un seul pret actif PAR ACTIF (avant : un seul pret actif tout actif confondu).<br>  -- Pour ajouter au meme actif, utiliser fn_topup_score_loan.<br>  IF EXISTS (SELECT 1 FROM score_loans WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol AND status = 'active') THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Un pret ' \|\| p_asset_symbol \|\| ' est deja en cours, utilise "Ajouter" pour l''augmenter');<br>  END IF;<br><br>  v_capacity := fn_score_credit_capacity(p_user_id);<br>  IF NOT (v_capacity->>'eligible')::boolean THEN<br>    RETURN jsonb_build_object('success', false, 'error', v_capacity->>'reason');<br>  END IF;<br><br>  SELECT price_usd INTO v_price FROM asset_prices WHERE asset_symbol = p_asset_symbol;<br>  IF v_price IS NULL OR v_price <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible pour cet actif');<br>  END IF;<br><br>  v_amount_usd := p_amount * v_price;<br>  IF v_amount_usd > (v_capacity->>'available_usd')::numeric THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant superieur a ta capacite actuelle');<br>  END IF;<br><br>  SELECT * INTO v_state FROM user_score_credit_state WHERE user_id = p_user_id FOR UPDATE;<br>  IF NOT FOUND THEN<br>    INSERT INTO user_score_credit_state (user_id, conversion_rate_pct)<br>    VALUES (p_user_id, v_config.conversion_rate_base_pct)<br>    RETURNING * INTO v_state;<br>  END IF;<br><br>  v_fee := ROUND(v_asset_cfg.fixed_fee_amount * (1 + v_state.default_count * (v_config.default_fee_multiplier - 1)), 8);<br>  v_net := p_amount - v_fee;<br><br>  IF v_net <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant trop faible pour couvrir le frais d''ouverture');<br>  END IF;<br><br>  SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = p_asset_symbol FOR UPDATE;<br>  IF NOT FOUND OR v_treasury_before < p_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Liquidite insuffisante en tresorerie pour cet actif');<br>  END IF;<br><br>  UPDATE treasury_wallets SET balance = balance - p_amount, total_withdrawn = total_withdrawn + p_amount, updated_at = now()<br>  WHERE asset_symbol = p_asset_symbol;<br><br>  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)<br>  VALUES (p_asset_symbol, 'loan_disbursement', p_amount, v_treasury_before, v_treasury_before - p_amount,<br>          p_user_id, 'Ouverture pret-score');<br><br>  INSERT INTO user_balances (user_id, asset_symbol, available_balance, updated_at)<br>  VALUES (p_user_id, p_asset_symbol, v_net, now())<br>  ON CONFLICT (user_id, asset_symbol) DO UPDATE<br>  SET available_balance = user_balances.available_balance + v_net, updated_at = now();<br><br>  PERFORM collect_fee_to_platform(p_asset_symbol, v_fee, 'score_loan_origination_fee', p_user_id, NULL);<br><br>  v_due_at := now() + (v_config.loan_duration_days \|\| ' days')::interval;<br><br>  INSERT INTO score_loans (user_id, asset_symbol, principal_amount, apr_rate_snapshot, fixed_fee_charged, status, opened_at, due_at, grace_until)<br>  VALUES (p_user_id, p_asset_symbol, p_amount, v_asset_cfg.apr_rate_pct, v_fee, 'active', now(), v_due_at,<br>          v_due_at + (v_config.grace_period_hours \|\| ' hours')::interval)<br>  RETURNING id INTO v_loan_id;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (p_user_id, 'score_loan_borrowed', p_asset_symbol, v_net, v_net, 'completed', now(), jsonb_build_object('loan_id', v_loan_id));<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (p_user_id, 'score_loan_fee', p_asset_symbol, v_fee, v_fee, 'completed', now(), jsonb_build_object('loan_id', v_loan_id));<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'loan_id', v_loan_id, 'amount_received', v_net, 'fee_charged', v_fee,<br>    'total_owed', p_amount, 'apr_rate_pct', v_asset_cfg.apr_rate_pct, 'due_at', v_due_at<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| public      | fn_place_bet                        | p_direction text, p_amount numeric, p_price_at_bet numeric                                                                                                                        | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_place_bet(p_direction text, p_amount numeric, p_price_at_bet numeric)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id     uuid := auth.uid();<br>  v_cfg         prediction_config%ROWTYPE;<br>  v_balance     numeric;<br>  v_bet_amount  numeric;<br>  v_resolves_at timestamptz;<br>  v_bet_id      uuid;<br>  v_bets_today  int;<br>  v_last_bet_at timestamptz;<br>BEGIN<br>  -- Auth<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  -- Validation direction<br>  IF p_direction NOT IN ('UP','DOWN') THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Direction invalide (UP ou DOWN)');<br>  END IF;<br><br>  -- Charger la config<br>  SELECT * INTO v_cfg FROM prediction_config WHERE id = 1;<br><br>  IF NOT v_cfg.is_active THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Le jeu est temporairement désactivé');<br>  END IF;<br><br>  -- Montant de la mise selon le mode<br>  IF v_cfg.bet_mode = 'fixed' THEN<br>    v_bet_amount := v_cfg.bet_amount;<br>  ELSE<br>    v_bet_amount := p_amount;<br>    IF v_bet_amount < v_cfg.bet_min OR v_bet_amount > v_cfg.bet_max THEN<br>      RETURN jsonb_build_object('success', false, 'error',<br>        'Montant invalide (min ' \|\| v_cfg.bet_min \|\| ' / max ' \|\| v_cfg.bet_max \|\| ')');<br>    END IF;<br>  END IF;<br><br>  -- Limite de paris par jour<br>  SELECT COUNT(*) INTO v_bets_today<br>  FROM prediction_bets<br>  WHERE user_id = v_user_id<br>    AND bet_at >= CURRENT_DATE<br>    AND status != 'cancelled';<br><br>  IF v_bets_today >= v_cfg.max_bets_per_day THEN<br>    RETURN jsonb_build_object('success', false, 'error',<br>      'Limite de ' \|\| v_cfg.max_bets_per_day \|\| ' paris par jour atteinte');<br>  END IF;<br><br>  -- Cooldown entre deux paris<br>  SELECT last_bet_at INTO v_last_bet_at<br>  FROM prediction_user_stats<br>  WHERE user_id = v_user_id;<br><br>  IF v_last_bet_at IS NOT NULL AND<br>     EXTRACT(EPOCH FROM (now() - v_last_bet_at)) < v_cfg.cooldown_seconds THEN<br>    RETURN jsonb_build_object('success', false, 'error',<br>      'Attendez encore ' \|\|<br>      (v_cfg.cooldown_seconds - FLOOR(EXTRACT(EPOCH FROM (now() - v_last_bet_at))))::int \|\|<br>      ' secondes avant de rejouer');<br>  END IF;<br><br>  -- Vérifier le solde disponible (FOR UPDATE pour éviter double-dépense)<br>  SELECT available_balance INTO v_balance<br>  FROM user_balances<br>  WHERE user_id = v_user_id AND asset_symbol = v_cfg.currency_symbol<br>  FOR UPDATE;<br><br>  IF v_balance IS NULL OR v_balance < v_bet_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant');<br>  END IF;<br><br>  -- Calculer la date de résolution<br>  v_resolves_at := now() + (v_cfg.duration_seconds \|\| ' seconds')::interval;<br><br>  -- Débiter le solde<br>  UPDATE user_balances<br>  SET available_balance = available_balance - v_bet_amount,<br>      updated_at        = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_cfg.currency_symbol;<br><br>  -- Créer le pari<br>  INSERT INTO prediction_bets (<br>    user_id, direction, bet_amount, currency_symbol,<br>    price_at_bet, resolves_at,<br>    win_multiplier, duration_seconds, asset_symbol<br>  ) VALUES (<br>    v_user_id, p_direction, v_bet_amount, v_cfg.currency_symbol,<br>    p_price_at_bet, v_resolves_at,<br>    v_cfg.win_multiplier, v_cfg.duration_seconds, v_cfg.asset_symbol<br>  )<br>  RETURNING id INTO v_bet_id;<br><br>  -- Enregistrer la transaction de mise<br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'game_bet', v_cfg.currency_symbol, v_bet_amount, v_bet_amount, 'completed', now(),<br>          jsonb_build_object('game', 'prediction', 'bet_id', v_bet_id, 'direction', p_direction));<br><br>  -- Initialiser ou mettre à jour les stats user<br>  INSERT INTO prediction_user_stats (user_id, total_bets, total_wagered, last_bet_at)<br>  VALUES (v_user_id, 1, v_bet_amount, now())<br>  ON CONFLICT (user_id) DO UPDATE SET<br>    total_bets   = prediction_user_stats.total_bets + 1,<br>    total_wagered = prediction_user_stats.total_wagered + v_bet_amount,<br>    last_bet_at  = now(),<br>    updated_at   = now();<br><br>  RETURN jsonb_build_object(<br>    'success',       true,<br>    'bet_id',        v_bet_id,<br>    'direction',     p_direction,<br>    'bet_amount',    v_bet_amount,<br>    'price_at_bet',  p_price_at_bet,<br>    'resolves_at',   v_resolves_at,<br>    'win_multiplier', v_cfg.win_multiplier,<br>    'potential_win', ROUND(v_bet_amount * v_cfg.win_multiplier, 4)<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | fn_remove_collateral                | p_loan_id uuid, p_amount numeric                                                                                                                                                  | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_remove_collateral(p_loan_id uuid, p_amount numeric)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id           uuid := auth.uid();<br>  v_loan               loans%ROWTYPE;<br>  v_coll_cfg           lending_collateral_config%ROWTYPE;<br>  v_price_collateral   numeric;<br>  v_price_borrow       numeric;<br>  v_new_collateral     numeric;<br>  v_new_ltv            numeric;<br>  v_debt               numeric;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  IF p_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_loan FROM loans<br>  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active'<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');<br>  END IF;<br><br>  v_new_collateral := v_loan.collateral_amount - p_amount;<br><br>  IF v_new_collateral <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error',<br>      'Impossible de retirer tout le collateral ainsi - rembourse le pret pour le liberer entierement');<br>  END IF;<br><br>  SELECT * INTO v_coll_cfg FROM lending_collateral_config WHERE asset_symbol = v_loan.collateral_asset;<br><br>  SELECT price_usd INTO v_price_collateral FROM asset_prices WHERE asset_symbol = v_loan.collateral_asset;<br>  SELECT price_usd INTO v_price_borrow     FROM asset_prices WHERE asset_symbol = v_loan.borrow_asset;<br><br>  IF v_price_collateral IS NULL OR v_price_borrow IS NULL OR v_price_collateral <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible, retrait impossible');<br>  END IF;<br><br>  v_debt    := v_loan.principal_amount + v_loan.accrued_interest;<br>  v_new_ltv := (v_debt * v_price_borrow) / (v_new_collateral * v_price_collateral) * 100;<br><br>  -- Le LTV apres retrait ne doit pas depasser le seuil MAX d'ouverture<br>  -- (meme logique de securite qu'a l'ouverture d'un nouveau pret)<br>  IF v_new_ltv > v_coll_cfg.max_ltv_pct THEN<br>    RETURN jsonb_build_object('success', false, 'error',<br>      'Retrait refuse : le LTV resultant serait trop eleve',<br>      'ltv_apres_retrait', ROUND(v_new_ltv,2), 'ltv_max', v_coll_cfg.max_ltv_pct);<br>  END IF;<br><br>  UPDATE loans SET collateral_amount = v_new_collateral WHERE id = p_loan_id;<br><br>  UPDATE user_balances<br>  SET available_balance = available_balance + p_amount, updated_at = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_loan.collateral_asset;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'loan_collateral_release', v_loan.collateral_asset, p_amount, p_amount, 'completed', now(),<br>          jsonb_build_object('loan_id', p_loan_id, 'reason', 'partial_withdrawal'));<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'loan_id', p_loan_id,<br>    'collateral_removed', p_amount,<br>    'collateral_remaining', v_new_collateral,<br>    'new_ltv_pct', ROUND(v_new_ltv, 2)<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       |
| public      | fn_repay_loan                       | p_loan_id uuid, p_repay_amount numeric                                                                                                                                            | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_repay_loan(p_loan_id uuid, p_repay_amount numeric)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id         uuid := auth.uid();<br>  v_loan            loans%ROWTYPE;<br>  v_owed            numeric;<br>  v_repay           numeric;<br>  v_interest_paid   numeric;<br>  v_principal_paid  numeric;<br>  v_user_balance    numeric;<br>  v_treasury_before numeric;<br>  v_fully_repaid    boolean;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  IF p_repay_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_loan FROM loans<br>  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');<br>  END IF;<br><br>  v_owed := v_loan.principal_amount + v_loan.accrued_interest;<br>  v_repay := LEAST(p_repay_amount, v_owed);<br>  v_interest_paid := LEAST(v_repay, v_loan.accrued_interest);<br>  v_principal_paid := v_repay - v_interest_paid;<br><br>  SELECT available_balance INTO v_user_balance<br>  FROM user_balances WHERE user_id = v_user_id AND asset_symbol = v_loan.borrow_asset FOR UPDATE;<br><br>  IF NOT FOUND OR v_user_balance < v_repay THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant pour rembourser');<br>  END IF;<br><br>  UPDATE user_balances SET available_balance = available_balance - v_repay, updated_at = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_loan.borrow_asset;<br><br>  -- Tolerance relative (0.01% du du, avec un plancher) au lieu d'un epsilon fixe :<br>  -- evite qu'un peu d'interet accru entre l'affichage cote client et l'execution<br>  -- laisse le pret bloque en "active" a cause d'une poussiere residuelle.<br>  v_fully_repaid := (v_owed - v_repay) <= GREATEST(v_owed * 0.0001, 0.00000001);<br><br>  UPDATE loans SET<br>    principal_amount = CASE WHEN v_fully_repaid THEN 0 ELSE principal_amount - v_principal_paid END,<br>    accrued_interest  = CASE WHEN v_fully_repaid THEN 0 ELSE accrued_interest - v_interest_paid END,<br>    status           = CASE WHEN v_fully_repaid THEN 'repaid' ELSE 'active' END,<br>    closed_at        = CASE WHEN v_fully_repaid THEN now() ELSE NULL END<br>  WHERE id = p_loan_id;<br><br>  IF v_principal_paid > 0 THEN<br>    SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.borrow_asset FOR UPDATE;<br>    UPDATE treasury_wallets SET balance = balance + v_principal_paid, updated_at = now()<br>    WHERE asset_symbol = v_loan.borrow_asset;<br>    INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)<br>    VALUES (v_loan.borrow_asset, 'loan_repayment', v_principal_paid, v_treasury_before, v_treasury_before + v_principal_paid,<br>            v_user_id, 'Remboursement principal pret ' \|\| p_loan_id::text);<br>  END IF;<br><br>  IF v_interest_paid > 0 THEN<br>    PERFORM collect_fee_to_platform(v_loan.borrow_asset, v_interest_paid, 'loan_interest', v_user_id, NULL);<br>  END IF;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'loan_repaid', v_loan.borrow_asset, v_repay, v_repay, 'completed', now(),<br>          jsonb_build_object('loan_id', p_loan_id, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid));<br><br>  IF v_fully_repaid THEN<br>    INSERT INTO user_balances (user_id, asset_symbol, available_balance, updated_at)<br>    VALUES (v_user_id, v_loan.collateral_asset, v_loan.collateral_amount, now())<br>    ON CONFLICT (user_id, asset_symbol) DO UPDATE<br>    SET available_balance = user_balances.available_balance + v_loan.collateral_amount, updated_at = now();<br><br>    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>    VALUES (v_user_id, 'loan_collateral_release', v_loan.collateral_asset, v_loan.collateral_amount, v_loan.collateral_amount, 'completed', now(),<br>            jsonb_build_object('loan_id', p_loan_id));<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'loan_id', p_loan_id, 'repaid', v_repay,<br>    'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid,<br>    'fully_repaid', v_fully_repaid,<br>    'collateral_released', CASE WHEN v_fully_repaid THEN v_loan.collateral_amount ELSE 0 END<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        