                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | fn_repay_score_loan                 | p_loan_id uuid, p_repay_amount numeric                                                                                                                                            | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_repay_score_loan(p_loan_id uuid, p_repay_amount numeric)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id        uuid := auth.uid();<br>  v_loan           score_loans%ROWTYPE;<br>  v_config         score_credit_config%ROWTYPE;<br>  v_interest       numeric;<br>  v_owed           numeric;<br>  v_repay          numeric;<br>  v_interest_paid  numeric;<br>  v_principal_paid numeric;<br>  v_balance        numeric;<br>  v_fully_repaid   boolean;<br>  v_treasury_before numeric;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br>  IF p_repay_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_loan FROM score_loans<br>  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');<br>  END IF;<br><br>  v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100<br>                * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);<br>  v_owed := v_loan.principal_amount + v_interest;<br>  v_repay := LEAST(p_repay_amount, v_owed);<br>  v_interest_paid := LEAST(v_repay, v_interest);<br>  v_principal_paid := v_repay - v_interest_paid;<br><br>  SELECT available_balance INTO v_balance FROM user_balances<br>  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol FOR UPDATE;<br>  IF NOT FOUND OR v_balance < v_repay THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant pour rembourser');<br>  END IF;<br><br>  UPDATE user_balances SET available_balance = available_balance - v_repay, updated_at = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol;<br><br>  v_fully_repaid := (v_owed - v_repay) <= GREATEST(v_owed * 0.0001, 0.00000001);<br><br>  UPDATE score_loans SET<br>    principal_amount = CASE WHEN v_fully_repaid THEN 0 ELSE principal_amount - v_principal_paid END,<br>    accrued_interest = CASE WHEN v_fully_repaid THEN 0 ELSE v_interest - v_interest_paid END,<br>    status = CASE WHEN v_fully_repaid THEN 'repaid' ELSE 'active' END,<br>    closed_at = CASE WHEN v_fully_repaid THEN now() ELSE NULL END<br>  WHERE id = p_loan_id;<br><br>  IF v_principal_paid > 0 THEN<br>    SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.asset_symbol FOR UPDATE;<br>    UPDATE treasury_wallets SET balance = balance + v_principal_paid, updated_at = now() WHERE asset_symbol = v_loan.asset_symbol;<br>    INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)<br>    VALUES (v_loan.asset_symbol, 'loan_repayment', v_principal_paid, v_treasury_before, v_treasury_before + v_principal_paid,<br>            v_user_id, 'Remboursement pret-score ' \|\| p_loan_id::text);<br>  END IF;<br><br>  IF v_interest_paid > 0 THEN<br>    PERFORM collect_fee_to_platform(v_loan.asset_symbol, v_interest_paid, 'score_loan_interest', v_user_id, NULL);<br>  END IF;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'score_loan_repaid', v_loan.asset_symbol, v_repay, v_repay, 'completed', now(),<br>          jsonb_build_object('loan_id', p_loan_id, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid));<br><br>  IF v_fully_repaid THEN<br>    SELECT * INTO v_config FROM score_credit_config WHERE id = 1;<br>    UPDATE user_score_credit_state<br>    SET conversion_rate_pct = LEAST(conversion_rate_pct + v_config.conversion_rate_step_pct, v_config.conversion_rate_max_pct),<br>        has_completed_first_loan = true,<br>        updated_at = now()<br>    WHERE user_id = v_user_id;<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'repaid', v_repay, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid,<br>    'fully_repaid', v_fully_repaid, 'remaining', GREATEST(v_owed - v_repay, 0)<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | fn_repay_score_loan_with_asset      | p_loan_id uuid, p_source_asset text, p_repay_amount_in_loan_asset numeric, p_preview boolean                                                                                      | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_repay_score_loan_with_asset(p_loan_id uuid, p_source_asset text, p_repay_amount_in_loan_asset numeric, p_preview boolean DEFAULT false)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id        uuid := auth.uid();<br>  v_loan           score_loans%ROWTYPE;<br>  v_config         score_credit_config%ROWTYPE;<br>  v_interest       numeric;<br>  v_owed           numeric;<br>  v_repay          numeric;<br>  v_interest_paid  numeric;<br>  v_principal_paid numeric;<br>  v_loan_price     numeric;<br>  v_source_price   numeric;<br>  v_repay_usd      numeric;<br>  v_source_needed_base numeric;<br>  v_conversion_fee_source numeric;<br>  v_source_total   numeric;<br>  v_source_balance numeric;<br>  v_fully_repaid   boolean;<br>  v_treasury_before numeric;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br>  IF p_repay_amount_in_loan_asset <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_loan FROM score_loans<br>  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');<br>  END IF;<br><br>  IF p_source_asset = v_loan.asset_symbol THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Utilise le remboursement standard pour ce meme actif');<br>  END IF;<br><br>  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;<br><br>  v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100<br>                * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);<br>  v_owed := v_loan.principal_amount + v_interest;<br>  v_repay := LEAST(p_repay_amount_in_loan_asset, v_owed);<br>  v_interest_paid := LEAST(v_repay, v_interest);<br>  v_principal_paid := v_repay - v_interest_paid;<br><br>  SELECT price_usd INTO v_loan_price FROM asset_prices WHERE asset_symbol = v_loan.asset_symbol;<br>  SELECT price_usd INTO v_source_price FROM asset_prices WHERE asset_symbol = p_source_asset;<br>  IF v_loan_price IS NULL OR v_loan_price <= 0 OR v_source_price IS NULL OR v_source_price <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible pour la conversion');<br>  END IF;<br><br>  v_repay_usd := v_repay * v_loan_price;<br>  v_source_needed_base := v_repay_usd / v_source_price;<br>  v_conversion_fee_source := ROUND(v_source_needed_base * v_config.cross_asset_repay_fee_pct / 100, 8);<br>  v_source_total := v_source_needed_base + v_conversion_fee_source;<br><br>  IF p_preview THEN<br>    SELECT available_balance INTO v_source_balance FROM user_balances<br>    WHERE user_id = v_user_id AND asset_symbol = p_source_asset;<br>    RETURN jsonb_build_object(<br>      'success', true, 'preview', true, 'repay_amount', v_repay, 'loan_asset', v_loan.asset_symbol,<br>      'source_asset', p_source_asset, 'source_amount_required', v_source_total,<br>      'conversion_fee_source', v_conversion_fee_source, 'source_balance_available', COALESCE(v_source_balance, 0),<br>      'sufficient_balance', COALESCE(v_source_balance, 0) >= v_source_total<br>    );<br>  END IF;<br><br>  SELECT available_balance INTO v_source_balance FROM user_balances<br>  WHERE user_id = v_user_id AND asset_symbol = p_source_asset FOR UPDATE;<br>  IF NOT FOUND OR v_source_balance < v_source_total THEN<br>    RETURN jsonb_build_object(<br>      'success', false, 'error', 'Solde insuffisant dans cet actif pour couvrir le remboursement et le frais de conversion',<br>      'source_amount_required', v_source_total, 'source_asset', p_source_asset<br>    );<br>  END IF;<br><br>  UPDATE user_balances SET available_balance = available_balance - v_source_total, updated_at = now()<br>  WHERE user_id = v_user_id AND asset_symbol = p_source_asset;<br><br>  IF v_conversion_fee_source > 0 THEN<br>    PERFORM collect_fee_to_platform(p_source_asset, v_conversion_fee_source, 'score_loan_cross_asset_fee', v_user_id, NULL);<br>  END IF;<br><br>  v_fully_repaid := (v_owed - v_repay) <= GREATEST(v_owed * 0.0001, 0.00000001);<br><br>  UPDATE score_loans SET<br>    principal_amount = CASE WHEN v_fully_repaid THEN 0 ELSE principal_amount - v_principal_paid END,<br>    accrued_interest = CASE WHEN v_fully_repaid THEN 0 ELSE v_interest - v_interest_paid END,<br>    status = CASE WHEN v_fully_repaid THEN 'repaid' ELSE 'active' END,<br>    closed_at = CASE WHEN v_fully_repaid THEN now() ELSE NULL END<br>  WHERE id = p_loan_id;<br><br>  IF v_principal_paid > 0 THEN<br>    SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.asset_symbol FOR UPDATE;<br>    UPDATE treasury_wallets SET balance = balance + v_principal_paid, updated_at = now() WHERE asset_symbol = v_loan.asset_symbol;<br>    INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)<br>    VALUES (v_loan.asset_symbol, 'loan_repayment', v_principal_paid, v_treasury_before, v_treasury_before + v_principal_paid,<br>            v_user_id, 'Remboursement pret-score (cross-asset) ' \|\| p_loan_id::text);<br>  END IF;<br><br>  IF v_interest_paid > 0 THEN<br>    PERFORM collect_fee_to_platform(v_loan.asset_symbol, v_interest_paid, 'score_loan_interest', v_user_id, NULL);<br>  END IF;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'score_loan_repaid_cross_asset', v_loan.asset_symbol, v_repay, v_repay, 'completed', now(),<br>          jsonb_build_object(<br>            'loan_id', p_loan_id, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid,<br>            'source_asset', p_source_asset, 'source_amount_debited', v_source_total, 'conversion_fee_source', v_conversion_fee_source<br>          ));<br><br>  IF v_fully_repaid THEN<br>    UPDATE user_score_credit_state<br>    SET conversion_rate_pct = LEAST(conversion_rate_pct + v_config.conversion_rate_step_pct, v_config.conversion_rate_max_pct),<br>        has_completed_first_loan = true,<br>        updated_at = now()<br>    WHERE user_id = v_user_id;<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'preview', false, 'repaid', v_repay, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid,<br>    'fully_repaid', v_fully_repaid, 'remaining', GREATEST(v_owed - v_repay, 0),<br>    'source_asset', p_source_asset, 'source_amount_debited', v_source_total, 'conversion_fee_source', v_conversion_fee_source<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       |
| public      | fn_resolve_bet                      | p_bet_id uuid, p_price_at_resolution numeric                                                                                                                                      | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_resolve_bet(p_bet_id uuid, p_price_at_resolution numeric)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id     uuid := auth.uid();<br>  v_bet         prediction_bets%ROWTYPE;<br>  v_won         boolean;<br>  v_payout      numeric;<br>  v_profit      numeric;<br>  v_new_status  text;<br>  v_streak_win  int;<br>  v_streak_loss int;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  SELECT * INTO v_bet<br>  FROM prediction_bets<br>  WHERE id = p_bet_id AND user_id = v_user_id AND status = 'pending'<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pari introuvable ou déjà résolu');<br>  END IF;<br><br>  IF now() < v_bet.resolves_at - interval '5 seconds' THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Le timer n''est pas encore écoulé');<br>  END IF;<br><br>  IF p_price_at_resolution = v_bet.price_at_bet THEN<br>    v_new_status := 'cancelled';<br>    v_payout     := v_bet.bet_amount;<br>    v_profit     := 0;<br>  ELSIF v_bet.direction = 'UP' THEN<br>    v_won := p_price_at_resolution > v_bet.price_at_bet;<br>  ELSE<br>    v_won := p_price_at_resolution < v_bet.price_at_bet;<br>  END IF;<br><br>  IF v_new_status IS NULL THEN<br>    IF v_won THEN<br>      v_new_status := 'won';<br>      v_payout     := ROUND(v_bet.bet_amount * v_bet.win_multiplier, 4);<br>      v_profit     := ROUND(v_payout - v_bet.bet_amount, 4);<br>    ELSE<br>      v_new_status := 'lost';<br>      v_payout     := 0;<br>      v_profit     := -v_bet.bet_amount;<br>    END IF;<br>  END IF;<br><br>  UPDATE prediction_bets SET<br>    status              = v_new_status,<br>    price_at_resolution = p_price_at_resolution,<br>    payout_amount       = v_payout,<br>    profit_amount       = v_profit,<br>    resolved_at         = now()<br>  WHERE id = p_bet_id;<br><br>  IF v_payout > 0 THEN<br>    UPDATE user_balances<br>    SET available_balance = available_balance + v_payout,<br>        updated_at        = now()<br>    WHERE user_id = v_user_id AND asset_symbol = v_bet.currency_symbol;<br><br>    IF v_new_status = 'won' THEN<br>      -- Seul le PROFIT (au-dela de la mise rendue) est finance par la tresorerie<br>      IF v_profit > 0 THEN<br>        PERFORM fn_treasury_debit_for_payout(<br>          v_bet.currency_symbol, v_profit, v_user_id, 'Gain pari prediction ' \|\| p_bet_id::text<br>        );<br>      END IF;<br><br>      INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>      VALUES (v_user_id, 'game_win', v_bet.currency_symbol, v_payout, v_payout, 'completed', now(),<br>              jsonb_build_object('game', 'prediction', 'bet_id', p_bet_id,<br>                                 'direction', v_bet.direction, 'profit', v_profit));<br>    END IF;<br>  END IF;<br><br>  IF v_new_status = 'lost' THEN<br>    PERFORM collect_fee_to_platform(<br>      v_bet.currency_symbol, v_bet.bet_amount, 'game_house_edge', v_user_id, NULL<br>    );<br>  END IF;<br><br>  SELECT win_streak, loss_streak INTO v_streak_win, v_streak_loss<br>  FROM prediction_user_stats WHERE user_id = v_user_id;<br><br>  UPDATE prediction_user_stats SET<br>    total_wins    = total_wins   + CASE WHEN v_won THEN 1 ELSE 0 END,<br>    total_losses  = total_losses + CASE WHEN v_won = false AND v_new_status = 'lost' THEN 1 ELSE 0 END,<br>    total_won     = total_won    + CASE WHEN v_won THEN v_payout ELSE 0 END,<br>    total_lost    = total_lost   + CASE WHEN v_won = false AND v_new_status = 'lost' THEN v_bet.bet_amount ELSE 0 END,<br>    net_profit    = net_profit   + v_profit,<br>    win_streak    = CASE WHEN v_won THEN win_streak + 1 ELSE 0 END,<br>    best_win_streak = GREATEST(best_win_streak, CASE WHEN v_won THEN win_streak + 1 ELSE win_streak END),<br>    loss_streak   = CASE WHEN v_won = false AND v_new_status = 'lost' THEN loss_streak + 1 ELSE 0 END,<br>    updated_at    = now()<br>  WHERE user_id = v_user_id;<br><br>  RETURN jsonb_build_object(<br>    'success',              true,<br>    'status',               v_new_status,<br>    'won',                  v_won,<br>    'direction',            v_bet.direction,<br>    'price_at_bet',         v_bet.price_at_bet,<br>    'price_at_resolution',  p_price_at_resolution,<br>    'bet_amount',           v_bet.bet_amount,<br>    'payout_amount',        v_payout,<br>    'profit_amount',        v_profit<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         |
| public      | fn_score_credit_capacity            | p_user_id uuid                                                                                                                                                                    | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_score_credit_capacity(p_user_id uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_config          score_credit_config%ROWTYPE;<br>  v_state           user_score_credit_state%ROWTYPE;<br>  v_account_age     int;<br>  v_organic_fees_usd numeric;<br>  v_outstanding_usd numeric;<br>  v_raw_cap_usd     numeric;<br>  v_available_usd   numeric;<br>  v_progress        jsonb;<br>BEGIN<br>  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;<br><br>  SELECT * INTO v_state FROM user_score_credit_state WHERE user_id = p_user_id;<br>  IF NOT FOUND THEN<br>    v_state.conversion_rate_pct := v_config.conversion_rate_base_pct;<br>    v_state.default_count := 0;<br>    v_state.has_completed_first_loan := false;<br>  END IF;<br><br>  SELECT COALESCE(EXTRACT(DAY FROM now() - created_at), 0)::int INTO v_account_age<br>  FROM public.users WHERE id = p_user_id;<br><br>  SELECT COALESCE(SUM(<br>    pf.amount * ap.price_usd *<br>    CASE WHEN pf.fee_type = 'game_net_loss'<br>         THEN v_config.game_house_edge_weight_pct / 100<br>         ELSE 1<br>    END<br>  ), 0) INTO v_organic_fees_usd<br>  FROM platform_fees pf<br>  JOIN asset_prices ap ON ap.asset_symbol = pf.asset_symbol<br>  WHERE pf.source_user_id = p_user_id<br>    AND pf.is_test = false<br>    AND pf.fee_type NOT IN ('score_loan_origination_fee', 'score_loan_interest', 'game_house_edge')<br>    AND pf.collected_at >= now() - (v_config.fee_window_days \|\| ' days')::interval;<br><br>  SELECT COALESCE(SUM((sl.principal_amount + sl.accrued_interest) * ap.price_usd), 0) INTO v_outstanding_usd<br>  FROM score_loans sl<br>  JOIN asset_prices ap ON ap.asset_symbol = sl.asset_symbol<br>  WHERE sl.user_id = p_user_id AND sl.status = 'active';<br><br>  v_raw_cap_usd := v_organic_fees_usd * v_state.conversion_rate_pct / 100;<br>  v_available_usd := GREATEST(v_raw_cap_usd - v_outstanding_usd, 0);<br>  v_available_usd := LEAST(v_available_usd, v_config.max_absolute_cap_usd);<br><br>  IF NOT v_state.has_completed_first_loan THEN<br>    v_available_usd := LEAST(v_available_usd, v_config.first_loan_cap_usd);<br>  END IF;<br><br>  v_progress := jsonb_build_object(<br>    'account_age_days', v_account_age,<br>    'min_account_age_days', v_config.min_account_age_days,<br>    'organic_fees_usd', v_organic_fees_usd,<br>    'min_fees_required_usd', v_config.min_fees_required_usd<br>  );<br><br>  IF NOT v_config.is_active THEN<br>    RETURN jsonb_build_object('eligible', false, 'reason', 'Systeme temporairement indisponible', 'available_usd', 0) \|\| v_progress;<br>  END IF;<br><br>  IF v_account_age < v_config.min_account_age_days THEN<br>    RETURN jsonb_build_object('eligible', false, 'reason', 'Compte trop recent', 'available_usd', 0) \|\| v_progress;<br>  END IF;<br><br>  IF v_organic_fees_usd < v_config.min_fees_required_usd THEN<br>    RETURN jsonb_build_object('eligible', false, 'reason', 'Activite insuffisante sur l''app', 'available_usd', 0) \|\| v_progress;<br>  END IF;<br><br>  IF v_available_usd <= 0 THEN<br>    RETURN jsonb_build_object('eligible', false, 'reason', 'Capacite d''emprunt epuisee', 'available_usd', 0) \|\| v_progress;<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'eligible', true,<br>    'available_usd', v_available_usd,<br>    'outstanding_usd', v_outstanding_usd,<br>    'conversion_rate_pct', v_state.conversion_rate_pct,<br>    'default_count', v_state.default_count<br>  ) \|\| v_progress;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        |
| public      | fn_score_loan_debt_recovery_trigger |                                                                                                                                                                                   | trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         | CREATE OR REPLACE FUNCTION public.fn_score_loan_debt_recovery_trigger()<br> RETURNS trigger<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_increase numeric;<br>  v_loan     RECORD;<br>  v_recovered numeric;<br>  v_treasury_before numeric;<br>  v_remaining numeric;<br>BEGIN<br>  IF pg_trigger_depth() > 1 THEN<br>    RETURN NEW;<br>  END IF;<br><br>  v_increase := NEW.available_balance - OLD.available_balance;<br>  IF v_increase <= 0 THEN<br>    RETURN NEW;<br>  END IF;<br><br>  SELECT * INTO v_loan FROM score_loans<br>  WHERE user_id = NEW.user_id AND asset_symbol = NEW.asset_symbol AND status = 'defaulted'<br>    AND (principal_amount + accrued_interest) > 0<br>  ORDER BY opened_at ASC<br>  LIMIT 1<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN NEW;<br>  END IF;<br><br>  v_recovered := LEAST(v_increase, v_loan.principal_amount + v_loan.accrued_interest);<br><br>  UPDATE user_balances<br>  SET available_balance = available_balance - v_recovered<br>  WHERE user_id = NEW.user_id AND asset_symbol = NEW.asset_symbol;<br><br>  v_remaining := v_loan.principal_amount + v_loan.accrued_interest - v_recovered;<br><br>  UPDATE score_loans<br>  SET principal_amount = GREATEST(principal_amount - v_recovered, 0),<br>      accrued_interest = GREATEST(accrued_interest - GREATEST(v_recovered - v_loan.principal_amount, 0), 0),<br>      status = CASE WHEN v_remaining <= 0.00000001 THEN 'repaid' ELSE 'defaulted' END,<br>      closed_at = CASE WHEN v_remaining <= 0.00000001 THEN now() ELSE closed_at END<br>  WHERE id = v_loan.id;<br><br>  SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = NEW.asset_symbol FOR UPDATE;<br>  IF FOUND THEN<br>    UPDATE treasury_wallets SET balance = balance + v_recovered, updated_at = now() WHERE asset_symbol = NEW.asset_symbol;<br>    INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)<br>    VALUES (NEW.asset_symbol, 'loan_repayment', v_recovered, v_treasury_before, v_treasury_before + v_recovered,<br>            NEW.user_id, 'Recouvrement auto pret-score defaillant ' \|\| v_loan.id::text);<br>  END IF;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (NEW.user_id, 'score_loan_debt_recovered', NEW.asset_symbol, v_recovered, v_recovered, 'completed', now(),<br>          jsonb_build_object('loan_id', v_loan.id));<br><br>  RETURN NEW;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| public      | fn_stake                            | p_amount numeric, p_pool_id uuid                                                                                                                                                  | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_stake(p_amount numeric, p_pool_id uuid DEFAULT 'f6c208e1-f277-4720-b303-45c1b607bf1f'::uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id   uuid := auth.uid();<br>  v_pool      staking_pools%ROWTYPE;<br>  v_balance   numeric;<br>  v_stake_id  uuid;<br>  v_unlock_at timestamptz;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  IF p_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_pool FROM staking_pools WHERE id = p_pool_id FOR UPDATE;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Plan de staking introuvable');<br>  END IF;<br>  IF NOT v_pool.is_active THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Ce plan de staking est temporairement désactivé');<br>  END IF;<br>  IF p_amount < v_pool.min_stake THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant inférieur au minimum requis (' \|\| v_pool.min_stake \|\| ')');<br>  END IF;<br>  IF v_pool.max_stake IS NOT NULL AND p_amount > v_pool.max_stake THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant supérieur au maximum autorisé (' \|\| v_pool.max_stake \|\| ')');<br>  END IF;<br>  IF v_pool.max_pool_capacity IS NOT NULL AND v_pool.total_staked + p_amount > v_pool.max_pool_capacity THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Capacité du plan atteinte');<br>  END IF;<br><br>  SELECT available_balance INTO v_balance<br>  FROM user_balances<br>  WHERE user_id = v_user_id AND asset_symbol = v_pool.asset_symbol<br>  FOR UPDATE;<br><br>  IF v_balance IS NULL OR v_balance < p_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant');<br>  END IF;<br><br>  UPDATE user_balances<br>  SET<br>    available_balance = available_balance - p_amount,<br>    staking_balance    = staking_balance + p_amount,<br>    updated_at         = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_pool.asset_symbol;<br><br>  IF v_pool.lock_period_days > 0 THEN<br>    v_unlock_at := now() + (v_pool.lock_period_days \|\| ' days')::interval;<br>  ELSE<br>    v_unlock_at := NULL;<br>  END IF;<br><br>  INSERT INTO user_stakes (user_id, pool_id, amount, status, initial_apy, staked_at, last_reward_calculation, unlock_at)<br>  VALUES (v_user_id, p_pool_id, p_amount, 'active', v_pool.base_apy, now(), now(), v_unlock_at)<br>  ON CONFLICT (user_id, pool_id, status)<br>  DO UPDATE SET<br>    amount      = user_stakes.amount + EXCLUDED.amount,<br>    initial_apy = v_pool.base_apy,<br>    -- Un nouvel ajout sur un pool bloqué repousse le déblocage sur le total<br>    unlock_at   = EXCLUDED.unlock_at,<br>    updated_at  = now()<br>  RETURNING id INTO v_stake_id;<br><br>  UPDATE staking_pools<br>  SET total_staked = total_staked + p_amount, updated_at = now()<br>  WHERE id = p_pool_id;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'stake', v_pool.asset_symbol, p_amount, p_amount, 'completed', now(),<br>          jsonb_build_object('pool_id', p_pool_id, 'stake_id', v_stake_id, 'apr', v_pool.base_apy));<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'staked', p_amount,<br>    'apr', v_pool.base_apy,<br>    'pool_id', p_pool_id,<br>    'unlock_at', v_unlock_at,<br>    'message', 'Staking activé avec succès'<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      |
| public      | fn_topup_score_loan                 | p_loan_id uuid, p_additional_amount numeric, p_preview boolean                                                                                                                    | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_topup_score_loan(p_loan_id uuid, p_additional_amount numeric, p_preview boolean DEFAULT false)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id      uuid := auth.uid();<br>  v_loan         score_loans%ROWTYPE;<br>  v_config       score_credit_config%ROWTYPE;<br>  v_asset_cfg    score_loan_asset_config%ROWTYPE;<br>  v_state        user_score_credit_state%ROWTYPE;<br>  v_capacity     jsonb;<br>  v_price        numeric;<br>  v_amount_usd   numeric;<br>  v_interest     numeric;<br>  v_capitalized_principal numeric;<br>  v_fee          numeric;<br>  v_net          numeric;<br>  v_treasury_before numeric;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br>  IF p_additional_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_loan FROM score_loans<br>  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');<br>  END IF;<br><br>  IF now() > v_loan.grace_until THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Delai de grace depasse, impossible d''ajouter a ce pret');<br>  END IF;<br><br>  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;<br><br>  SELECT * INTO v_asset_cfg FROM score_loan_asset_config WHERE asset_symbol = v_loan.asset_symbol AND is_active = true;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', v_loan.asset_symbol \|\| ' n''est plus disponible pour ce type de pret');<br>  END IF;<br><br>  v_capacity := fn_score_credit_capacity(v_user_id);<br>  IF NOT (v_capacity->>'eligible')::boolean THEN<br>    RETURN jsonb_build_object('success', false, 'error', v_capacity->>'reason');<br>  END IF;<br><br>  SELECT price_usd INTO v_price FROM asset_prices WHERE asset_symbol = v_loan.asset_symbol;<br>  IF v_price IS NULL OR v_price <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible pour cet actif');<br>  END IF;<br><br>  v_amount_usd := p_additional_amount * v_price;<br>  IF v_amount_usd > (v_capacity->>'available_usd')::numeric THEN<br>    RETURN jsonb_build_object(<br>      'success', false, 'error', 'Montant superieur a ta capacite actuelle',<br>      'available_usd', (v_capacity->>'available_usd')::numeric<br>    );<br>  END IF;<br><br>  v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100<br>                * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);<br>  v_capitalized_principal := v_loan.principal_amount + v_interest;<br><br>  SELECT * INTO v_state FROM user_score_credit_state WHERE user_id = v_user_id FOR UPDATE;<br>  v_fee := ROUND(v_asset_cfg.fixed_fee_amount * (1 + v_state.default_count * (v_config.default_fee_multiplier - 1)), 8);<br>  v_net := p_additional_amount - v_fee;<br>  IF v_net <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant trop faible pour couvrir le frais');<br>  END IF;<br><br>  IF p_preview THEN<br>    RETURN jsonb_build_object(<br>      'success', true, 'preview', true, 'fee_charged', v_fee, 'amount_received', v_net,<br>      'new_principal_owed', v_capitalized_principal + p_additional_amount,<br>      'asset_symbol', v_loan.asset_symbol<br>    );<br>  END IF;<br><br>  SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.asset_symbol FOR UPDATE;<br>  IF NOT FOUND OR v_treasury_before < p_additional_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Liquidite insuffisante en tresorerie pour cet actif');<br>  END IF;<br><br>  UPDATE treasury_wallets SET balance = balance - p_additional_amount, total_withdrawn = total_withdrawn + p_additional_amount, updated_at = now()<br>  WHERE asset_symbol = v_loan.asset_symbol;<br><br>  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)<br>  VALUES (v_loan.asset_symbol, 'loan_disbursement', p_additional_amount, v_treasury_before, v_treasury_before - p_additional_amount,<br>          v_user_id, 'Ajout au pret-score ' \|\| p_loan_id::text);<br><br>  UPDATE user_balances SET available_balance = available_balance + v_net, updated_at = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol;<br><br>  PERFORM collect_fee_to_platform(v_loan.asset_symbol, v_fee, 'score_loan_origination_fee', v_user_id, NULL);<br><br>  UPDATE score_loans SET<br>    principal_amount = v_capitalized_principal + p_additional_amount,<br>    accrued_interest = 0,<br>    opened_at = now()<br>  WHERE id = p_loan_id;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'score_loan_topup', v_loan.asset_symbol, v_net, v_net, 'completed', now(),<br>          jsonb_build_object('loan_id', p_loan_id, 'fee_charged', v_fee, 'new_principal', v_capitalized_principal + p_additional_amount));<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'preview', false, 'fee_charged', v_fee, 'amount_received', v_net,<br>    'new_principal_owed', v_capitalized_principal + p_additional_amount, 'asset_symbol', v_loan.asset_symbol<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| public      | fn_translate_payment_error          | p_failure_code text                                                                                                                                                               | text                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.fn_translate_payment_error(p_failure_code text)<br> RETURNS text<br> LANGUAGE sql<br> STABLE<br>AS $function$<br>  SELECT COALESCE(<br>    (SELECT message_fr FROM payment_error_messages WHERE failure_code = p_failure_code),<br>    (SELECT message_fr FROM payment_error_messages WHERE failure_code = 'DEFAULT')<br>  );<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    |
| public      | fn_treasury_debit_for_payout        | p_asset_symbol text, p_amount numeric, p_user_id uuid, p_reason text                                                                                                              | numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         | CREATE OR REPLACE FUNCTION public.fn_treasury_debit_for_payout(p_asset_symbol text, p_amount numeric, p_user_id uuid, p_reason text)<br> RETURNS numeric<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_balance_before numeric;<br>  v_debit          numeric;<br>  v_shortfall      numeric;<br>  v_balance_after  numeric;<br>BEGIN<br>  IF p_amount IS NULL OR p_amount <= 0 THEN<br>    RETURN 0;<br>  END IF;<br><br>  SELECT balance INTO v_balance_before<br>  FROM public.treasury_wallets<br>  WHERE asset_symbol = p_asset_symbol<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    v_balance_before := 0;<br>    INSERT INTO public.treasury_wallets (asset_symbol, balance, total_collected)<br>    VALUES (p_asset_symbol, 0, 0)<br>    ON CONFLICT (asset_symbol) DO NOTHING;<br>  END IF;<br><br>  v_debit     := LEAST(p_amount, v_balance_before);<br>  v_shortfall := p_amount - v_debit;<br><br>  IF v_debit > 0 THEN<br>    UPDATE public.treasury_wallets<br>    SET balance = balance - v_debit,<br>        total_withdrawn = total_withdrawn + v_debit,<br>        updated_at = now()<br>    WHERE asset_symbol = p_asset_symbol<br>    RETURNING balance INTO v_balance_after;<br><br>    INSERT INTO public.treasury_ledger (<br>      asset_symbol, entry_type, amount, balance_before, balance_after,<br>      performed_by, reason<br>    ) VALUES (<br>      p_asset_symbol, 'payout_debit', v_debit, v_balance_before, v_balance_after,<br>      p_user_id, p_reason<br>    );<br>  END IF;<br><br>  IF v_shortfall > 0 THEN<br>    -- Tracabilite : la tresorerie n'a pas suffi a couvrir tout le gain.<br>    -- Le joueur est quand meme paye (voir appelant), mais ceci doit alerter un admin.<br>    INSERT INTO public.treasury_ledger (<br>      asset_symbol, entry_type, amount, balance_before, balance_after,<br>      performed_by, reason<br>    ) VALUES (<br>      p_asset_symbol, 'adjustment', v_shortfall, 0, 0,<br>      p_user_id, 'SHORTFALL: gain non couvert par la tresorerie - ' \|\| COALESCE(p_reason, '')<br>    );<br>    RAISE WARNING 'Tresorerie insuffisante pour % %: manque de % (raison: %)', p_amount, p_asset_symbol, v_shortfall, p_reason;<br>  END IF;<br><br>  RETURN v_debit;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      |
| public      | fn_unstake                          | p_amount numeric, p_pool_id uuid                                                                                                                                                  | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_unstake(p_amount numeric, p_pool_id uuid DEFAULT 'f6c208e1-f277-4720-b303-45c1b607bf1f'::uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id     uuid := auth.uid();<br>  v_pool        staking_pools%ROWTYPE;<br>  v_stake       user_stakes%ROWTYPE;<br>  v_rewards     numeric;<br>  v_penalty     numeric := 0;<br>  v_net_amount  numeric;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  IF p_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_pool FROM staking_pools WHERE id = p_pool_id;<br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Plan de staking introuvable');<br>  END IF;<br><br>  SELECT * INTO v_stake<br>  FROM user_stakes<br>  WHERE user_id = v_user_id AND pool_id = p_pool_id AND status = 'active'<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Aucun staking actif sur ce plan');<br>  END IF;<br><br>  IF p_amount > v_stake.amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant supérieur au stake');<br>  END IF;<br><br>  -- Plan bloqué encore verrouillé : vérifier si le retrait anticipé est autorisé<br>  IF v_stake.unlock_at IS NOT NULL AND now() < v_stake.unlock_at THEN<br>    IF NOT v_pool.instant_unstake_enabled THEN<br>      RETURN jsonb_build_object(<br>        'success', false,<br>        'error', 'Ce staking est bloqué jusqu''au ' \|\| to_char(v_stake.unlock_at, 'DD/MM/YYYY'),<br>        'unlock_at', v_stake.unlock_at<br>      );<br>    END IF;<br>    v_penalty := ROUND(p_amount * COALESCE(v_pool.instant_unstake_fee_percent, 0) / 100.0, 8);<br>  END IF;<br><br>  v_rewards := v_stake.pending_rewards;<br>  v_net_amount := p_amount - v_penalty;<br><br>  IF p_amount = v_stake.amount THEN<br>    UPDATE user_stakes SET<br>      amount           = 0,<br>      status           = 'unstaked',<br>      pending_rewards  = 0,<br>      rewards_earned   = rewards_earned + v_rewards,<br>      unlock_at        = NULL,<br>      updated_at       = now()<br>    WHERE id = v_stake.id;<br>  ELSE<br>    UPDATE user_stakes SET<br>      amount           = amount - p_amount,<br>      pending_rewards  = 0,<br>      rewards_earned   = rewards_earned + v_rewards,<br>      last_reward_calculation = now(),<br>      updated_at       = now()<br>    WHERE id = v_stake.id;<br>  END IF;<br><br>  UPDATE user_balances SET<br>    available_balance    = available_balance + v_net_amount + v_rewards,<br>    staking_balance       = GREATEST(0, staking_balance - p_amount),<br>    total_earned_staking  = total_earned_staking + v_rewards,<br>    updated_at            = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_pool.asset_symbol;<br><br>  UPDATE staking_pools SET<br>    total_staked              = GREATEST(0, total_staked - p_amount),<br>    total_rewards_distributed = total_rewards_distributed + v_rewards,<br>    updated_at                = now()<br>  WHERE id = p_pool_id;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'unstake', v_pool.asset_symbol, p_amount, v_net_amount, 'completed', now(),<br>          jsonb_build_object('pool_id', p_pool_id, 'rewards_claimed', v_rewards, 'early_withdrawal_penalty', v_penalty));<br><br>  IF v_rewards > 0 THEN<br>    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>    VALUES (v_user_id, 'staking_reward', v_pool.asset_symbol, v_rewards, v_rewards, 'completed', now(),<br>            jsonb_build_object('pool_id', p_pool_id));<br><br>    PERFORM fn_treasury_debit_for_payout(v_pool.asset_symbol, v_rewards, v_user_id, 'Recompense staking - unstake');<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'success',  true,<br>    'unstaked', p_amount,<br>    'penalty', v_penalty,<br>    'rewards_claimed', v_rewards,<br>    'total_received', v_net_amount + v_rewards,<br>    'message', CASE WHEN v_penalty > 0<br>      THEN 'Retrait anticipé effectué avec ' \|\| v_penalty \|\| ' ' \|\| v_pool.asset_symbol \|\| ' de frais'<br>      ELSE 'Retrait effectué avec succès' END<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      |
| public      | fn_unstake                          | p_amount numeric                                                                                                                                                                  | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_unstake(p_amount numeric)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id     uuid := auth.uid();<br>  v_asset       text := 'WAKATI';<br>  v_pool_id     uuid := 'f6c208e1-f277-4720-b303-45c1b607bf1f';<br>  v_stake       user_stakes%ROWTYPE;<br>  v_rewards     numeric;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  IF p_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT * INTO v_stake<br>  FROM user_stakes<br>  WHERE user_id = v_user_id AND pool_id = v_pool_id AND status = 'active'<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Aucun staking actif');<br>  END IF;<br><br>  IF p_amount > v_stake.amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant supérieur au stake');<br>  END IF;<br><br>  v_rewards := v_stake.pending_rewards;<br><br>  IF p_amount = v_stake.amount THEN<br>    UPDATE user_stakes SET<br>      amount           = 0,<br>      status           = 'unstaked',<br>      pending_rewards  = 0,<br>      rewards_earned   = rewards_earned + v_rewards,<br>      updated_at       = now()<br>    WHERE id = v_stake.id;<br>  ELSE<br>    UPDATE user_stakes SET<br>      amount           = amount - p_amount,<br>      pending_rewards  = 0,<br>      rewards_earned   = rewards_earned + v_rewards,<br>      last_reward_calculation = now(),<br>      updated_at       = now()<br>    WHERE id = v_stake.id;<br>  END IF;<br><br>  UPDATE user_balances SET<br>    available_balance  = available_balance + p_amount + v_rewards,<br>    staking_balance    = GREATEST(0, staking_balance - p_amount),<br>    total_earned_staking = total_earned_staking + v_rewards,<br>    updated_at         = now()<br>  WHERE user_id = v_user_id AND asset_symbol = v_asset;<br><br>  UPDATE staking_pools SET<br>    total_staked             = GREATEST(0, total_staked - p_amount),<br>    total_rewards_distributed = total_rewards_distributed + v_rewards,<br>    updated_at               = now()<br>  WHERE id = v_pool_id;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>  VALUES (v_user_id, 'unstake', v_asset, p_amount, p_amount, 'completed', now(),<br>          jsonb_build_object('pool_id', v_pool_id, 'rewards_claimed', v_rewards));<br><br>  IF v_rewards > 0 THEN<br>    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)<br>    VALUES (v_user_id, 'staking_reward', v_asset, v_rewards, v_rewards, 'completed', now(),<br>            jsonb_build_object('pool_id', v_pool_id));<br><br>    -- La recompense est financee par la tresorerie, pas creee du neant<br>    PERFORM fn_treasury_debit_for_payout(v_asset, v_rewards, v_user_id, 'Recompense staking - unstake');<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'success',  true,<br>    'unstaked', p_amount,<br>    'rewards_claimed', v_rewards,<br>    'total_received', p_amount + v_rewards,<br>    'message', 'Retrait effectué avec succès'<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     |
| public      | fn_user_burn_tokens                 | p_asset_symbol text, p_amount numeric, p_reason text                                                                                                                              | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.fn_user_burn_tokens(p_asset_symbol text, p_amount numeric, p_reason text DEFAULT NULL::text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id         uuid := auth.uid();<br>  v_balance         numeric;<br>  v_new_balance     numeric;<br>  v_burn_id         uuid;<br>  v_total_burned    numeric;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');<br>  END IF;<br><br>  IF p_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');<br>  END IF;<br><br>  SELECT available_balance INTO v_balance<br>  FROM public.user_balances<br>  WHERE user_id = v_user_id AND asset_symbol = p_asset_symbol<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Aucun solde pour cet asset');<br>  END IF;<br><br>  IF v_balance < p_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant', 'solde_disponible', v_balance);<br>  END IF;<br><br>  UPDATE public.user_balances<br>  SET available_balance = available_balance - p_amount,<br>      updated_at = now()<br>  WHERE user_id = v_user_id AND asset_symbol = p_asset_symbol<br>  RETURNING available_balance INTO v_new_balance;<br><br>  INSERT INTO public.token_burns (<br>    asset_symbol, amount, reason, burned_by, status, source<br>  ) VALUES (<br>    p_asset_symbol, p_amount, p_reason, v_user_id, 'completed', 'user'<br>  ) RETURNING id INTO v_burn_id;<br><br>  UPDATE public.supported_assets_metrics<br>  SET total_burned = total_burned + p_amount, last_updated = now()<br>  WHERE asset_symbol = p_asset_symbol<br>  RETURNING total_burned INTO v_total_burned;<br><br>  INSERT INTO public.transactions (<br>    user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata<br>  ) VALUES (<br>    v_user_id, 'burn', p_asset_symbol, p_amount, p_amount, 'completed', now(),<br>    jsonb_build_object('reason', p_reason, 'burn_id', v_burn_id)<br>  );<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'burn_id', v_burn_id,<br>    'amount_burned', p_amount,<br>    'new_balance', v_new_balance,<br>    'asset_total_burned', v_total_burned<br>  );<br><br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              