                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | fn_user_can_get_free_spins          | p_user_id uuid                                                                                                                                                                    | boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         | CREATE OR REPLACE FUNCTION public.fn_user_can_get_free_spins(p_user_id uuid)<br> RETURNS boolean<br> LANGUAGE plpgsql<br> STABLE<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_created_at   timestamptz;<br>  v_fcfa_balance numeric;<br>BEGIN<br>  SELECT created_at INTO v_created_at FROM public.users WHERE id = p_user_id;<br><br>  IF v_created_at IS NULL THEN<br>    RETURN false;<br>  END IF;<br><br>  -- Nouvel utilisateur (moins de 15 jours) : toujours éligible.<br>  IF v_created_at >= NOW() - INTERVAL '15 days' THEN<br>    RETURN true;<br>  END IF;<br><br>  -- Ancien utilisateur : éligible seulement si solde FCFA actuel >= 500.<br>  SELECT available_balance INTO v_fcfa_balance<br>  FROM public.user_balances<br>  WHERE user_id = p_user_id AND asset_symbol = 'FCFA';<br><br>  RETURN COALESCE(v_fcfa_balance, 0) >= 500;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              |
| public      | generate_referral_code              |                                                                                                                                                                                   | text                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.generate_referral_code()<br> RETURNS text<br> LANGUAGE plpgsql<br>AS $function$<br>BEGIN<br>    RETURN 'WKT' \|\| UPPER(SUBSTRING(MD5(RANDOM()::text) FROM 1 FOR 6));<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    |
| public      | get_admin_dashboard                 |                                                                                                                                                                                   | TABLE(total_users bigint, new_users_24h bigint, new_users_7d bigint, verified_users bigint, total_active_stakes bigint, total_staked_usd numeric, total_pending_rewards_usd numeric, active_pools_count bigint, fees_24h_usd numeric, fees_7d_usd numeric, fees_30d_usd numeric, swap_volume_24h_usd numeric, p2p_volume_24h_usd numeric, transactions_24h bigint, pending_withdrawals bigint)                                                                                                                  | CREATE OR REPLACE FUNCTION public.get_admin_dashboard()<br> RETURNS TABLE(total_users bigint, new_users_24h bigint, new_users_7d bigint, verified_users bigint, total_active_stakes bigint, total_staked_usd numeric, total_pending_rewards_usd numeric, active_pools_count bigint, fees_24h_usd numeric, fees_7d_usd numeric, fees_30d_usd numeric, swap_volume_24h_usd numeric, p2p_volume_24h_usd numeric, transactions_24h bigint, pending_withdrawals bigint)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    SELECT<br>        -- Utilisateurs<br>        (SELECT COUNT(*) FROM public.users)::bigint,<br>        (SELECT COUNT(*) FROM public.users WHERE created_at > now() - interval '24 hours')::bigint,<br>        (SELECT COUNT(*) FROM public.users WHERE created_at > now() - interval '7 days')::bigint,<br>        (SELECT COUNT(*) FROM public.users WHERE is_verified = true)::bigint,<br><br>        -- Staking<br>        (SELECT COUNT(*) FROM public.user_stakes WHERE status = 'active')::bigint,<br>        (SELECT COALESCE(ROUND(SUM(us.amount * COALESCE(ap.price_usd, 0)), 2), 0)<br>         FROM public.user_stakes us<br>         JOIN public.staking_pools sp ON sp.id = us.pool_id<br>         LEFT JOIN public.asset_prices ap ON ap.asset_symbol = sp.asset_symbol<br>         WHERE us.status = 'active'),<br>        (SELECT COALESCE(ROUND(SUM(us.pending_rewards * COALESCE(ap.price_usd, 0)), 2), 0)<br>         FROM public.user_stakes us<br>         JOIN public.staking_pools sp ON sp.id = us.pool_id<br>         LEFT JOIN public.asset_prices ap<br>                ON ap.asset_symbol = COALESCE(sp.reward_asset_symbol, sp.asset_symbol)<br>         WHERE us.status = 'active'),<br>        (SELECT COUNT(*) FROM public.staking_pools WHERE is_active = true)::bigint,<br><br>        -- Frais<br>        (SELECT COALESCE(ROUND(SUM(pf.amount * COALESCE(ap.price_usd, 0)), 2), 0)<br>         FROM public.platform_fees pf<br>         LEFT JOIN public.asset_prices ap ON ap.asset_symbol = pf.asset_symbol<br>         WHERE pf.collected_at > now() - interval '24 hours'),<br>        (SELECT COALESCE(ROUND(SUM(pf.amount * COALESCE(ap.price_usd, 0)), 2), 0)<br>         FROM public.platform_fees pf<br>         LEFT JOIN public.asset_prices ap ON ap.asset_symbol = pf.asset_symbol<br>         WHERE pf.collected_at > now() - interval '7 days'),<br>        (SELECT COALESCE(ROUND(SUM(pf.amount * COALESCE(ap.price_usd, 0)), 2), 0)<br>         FROM public.platform_fees pf<br>         LEFT JOIN public.asset_prices ap ON ap.asset_symbol = pf.asset_symbol<br>         WHERE pf.collected_at > now() - interval '30 days'),<br><br>        -- Volumes 24h<br>        (SELECT COALESCE(ROUND(SUM(t.amount * COALESCE(ap.price_usd, 0)), 2), 0)<br>         FROM public.transactions t<br>         LEFT JOIN public.asset_prices ap ON ap.asset_symbol = t.asset_symbol<br>         WHERE t.type = 'swap_debit'<br>           AND t.created_at > now() - interval '24 hours'),<br>        (SELECT COALESCE(ROUND(SUM(t.amount * COALESCE(ap.price_usd, 0)), 2), 0)<br>         FROM public.transactions t<br>         LEFT JOIN public.asset_prices ap ON ap.asset_symbol = t.asset_symbol<br>         WHERE t.type = 'p2p_transfer'<br>           AND t.created_at > now() - interval '24 hours'),<br><br>        -- Transactions 24h<br>        (SELECT COUNT(*) FROM public.transactions<br>         WHERE created_at > now() - interval '24 hours')::bigint,<br>        (SELECT COUNT(*) FROM public.transactions<br>         WHERE type = 'withdrawal' AND status = 'pending')::bigint;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  |
| public      | get_admin_reconciliation            |                                                                                                                                                                                   | TABLE(asset_symbol text, available_total numeric, staking_balance_total numeric, pending_total numeric, liability_fn numeric, liability_diff numeric, active_stakes_total numeric, staking_orphan numeric, negative_rows bigint)                                                                                                                                                                                                                                                                                | CREATE OR REPLACE FUNCTION public.get_admin_reconciliation()<br> RETURNS TABLE(asset_symbol text, available_total numeric, staking_balance_total numeric, pending_total numeric, liability_fn numeric, liability_diff numeric, active_stakes_total numeric, staking_orphan numeric, negative_rows bigint)<br> LANGUAGE sql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>  with bal as (<br>    select ub.asset_symbol,<br>           sum(ub.available_balance) as available,<br>           sum(coalesce(ub.staking_balance, 0)) as staking,<br>           sum(coalesce(ub.pending_balance, 0)) as pending,<br>           count(*) filter (where ub.available_balance < 0 or coalesce(ub.staking_balance,0) < 0 or coalesce(ub.pending_balance,0) < 0) as neg<br>    from user_balances ub group by 1<br>  ), stk as (<br>    select p.asset_symbol, sum(s.amount) as staked<br>    from user_stakes s join staking_pools p on p.id = s.pool_id<br>    where s.status = 'active' group by 1<br>  ), fn as (select l.asset_symbol, l.total_liability from get_asset_liabilities() l)<br>  select b.asset_symbol,<br>         round(b.available, 8), round(b.staking, 8), round(b.pending, 8),<br>         round(coalesce(fn.total_liability, 0), 8),<br>         round(b.available + b.staking + b.pending - coalesce(fn.total_liability, 0), 8),<br>         round(coalesce(stk.staked, 0), 8),<br>         round(b.staking - coalesce(stk.staked, 0), 8),<br>         b.neg<br>  from bal b<br>  left join fn on fn.asset_symbol = b.asset_symbol<br>  left join stk on stk.asset_symbol = b.asset_symbol<br>  order by b.asset_symbol<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | get_asset_liabilities               |                                                                                                                                                                                   | TABLE(asset_symbol text, total_liability numeric, user_count bigint)                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.get_asset_liabilities()<br> RETURNS TABLE(asset_symbol text, total_liability numeric, user_count bigint)<br> LANGUAGE sql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>  SELECT ub.asset_symbol,<br>         COALESCE(SUM(ub.available_balance + COALESCE(ub.staking_balance,0) + COALESCE(ub.pending_balance,0)), 0) AS total_liability,<br>         COUNT(*) FILTER (WHERE ub.available_balance + COALESCE(ub.staking_balance,0) + COALESCE(ub.pending_balance,0) > 0) AS user_count<br>  FROM user_balances ub<br>  GROUP BY ub.asset_symbol;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     |
| public      | get_available_swap_assets           | p_user_id uuid                                                                                                                                                                    | TABLE(symbol text, name text, network text, available_balance numeric, current_price_usd numeric, change_24h numeric, can_be_swapped boolean)                                                                                                                                                                                                                                                                                                                                                                   | CREATE OR REPLACE FUNCTION public.get_available_swap_assets(p_user_id uuid)<br> RETURNS TABLE(symbol text, name text, network text, available_balance numeric, current_price_usd numeric, change_24h numeric, can_be_swapped boolean)<br> LANGUAGE plpgsql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    SELECT<br>        sa.symbol,<br>        sa.name,<br>        sa.network,<br>        COALESCE(ub.available_balance, 0) AS available_balance,<br>        COALESCE(ap.price_usd, 0) AS current_price_usd,<br>        COALESCE(ap.change_24h, 0) AS change_24h,  -- ✅ Utilise le nom exact de la colonne<br>        sa.can_be_swapped<br>    FROM public.supported_assets sa<br>    LEFT JOIN public.user_balances ub<br>        ON ub.asset_symbol = sa.symbol AND ub.user_id = p_user_id<br>    LEFT JOIN public.asset_prices ap<br>        ON ap.asset_symbol = sa.symbol<br>    WHERE sa.is_active = true<br>      AND sa.can_be_swapped = true<br>    ORDER BY COALESCE(ub.available_balance, 0) * COALESCE(ap.price_usd, 0) DESC;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | get_my_stakes                       |                                                                                                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.get_my_stakes()<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id uuid := auth.uid();<br>  v_result  jsonb;<br>BEGIN<br>  IF v_user_id IS NULL THEN<br>    RETURN '[]'::jsonb;<br>  END IF;<br><br>  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_result<br>  FROM (<br>    SELECT<br>      us.id               AS stake_id,<br>      us.pool_id,<br>      sp.name             AS pool_name,<br>      sp.asset_symbol,<br>      us.amount           AS staked,<br>      us.pending_rewards,<br>      us.rewards_earned,<br>      us.initial_apy       AS apr,<br>      us.staked_at,<br>      us.unlock_at,<br>      sp.lock_period_days,<br>      sp.instant_unstake_enabled,<br>      sp.instant_unstake_fee_percent,<br>      (us.unlock_at IS NOT NULL AND now() < us.unlock_at) AS is_locked<br>    FROM user_stakes us<br>    JOIN staking_pools sp ON sp.id = us.pool_id<br>    WHERE us.user_id = v_user_id AND us.status = 'active'<br>    ORDER BY us.staked_at DESC<br>  ) t;<br><br>  RETURN v_result;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         |
| public      | get_my_staking                      |                                                                                                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.get_my_staking()<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id uuid := auth.uid();<br>  v_result  jsonb;<br>BEGIN<br>  SELECT jsonb_build_object(<br>    'staked',             COALESCE(us.amount, 0),<br>    'pending_rewards',    COALESCE(us.pending_rewards, 0),<br>    'total_earned',       COALESCE(us.rewards_earned + us.pending_rewards, 0),<br>    'apr',                sc.apr,<br>    'daily_rate',         ROUND(sc.apr / 100.0 / 365.0 * 100, 4),<br>    'staking_active',     (us.status = 'active'),<br>    'staked_since',       us.staked_at,<br>    'available_balance',  COALESCE(ub.available_balance, 0)<br>  ) INTO v_result<br>  FROM staking_config sc<br>  LEFT JOIN user_stakes us ON us.user_id = v_user_id<br>    AND us.pool_id = 'f6c208e1-f277-4720-b303-45c1b607bf1f'<br>    AND us.status  = 'active'<br>  LEFT JOIN user_balances ub ON ub.user_id = v_user_id AND ub.asset_symbol = 'WAKATI'<br>  WHERE sc.id = 1;<br><br>  RETURN COALESCE(v_result, '{}'::jsonb);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | get_platform_fees_totals            |                                                                                                                                                                                   | TABLE(asset_symbol text, fee_count bigint, total_fees numeric)                                                                                                                                                                                                                                                                                                                                                                                                                                                  | CREATE OR REPLACE FUNCTION public.get_platform_fees_totals()<br> RETURNS TABLE(asset_symbol text, fee_count bigint, total_fees numeric)<br> LANGUAGE sql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>  select pf.asset_symbol, count(*)::bigint, coalesce(sum(pf.amount), 0)<br>  from platform_fees pf<br>  where pf.is_test = false<br>    and pf.fee_type <> 'game_net_loss'<br>  group by pf.asset_symbol<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         |
| public      | get_platform_revenue_report         | p_from timestamp with time zone, p_to timestamp with time zone                                                                                                                    | TABLE(fee_type text, asset_symbol text, total_collected numeric, total_collected_usd numeric, transaction_count bigint, avg_fee numeric, first_collected_at timestamp with time zone, last_collected_at timestamp with time zone)                                                                                                                                                                                                                                                                               | CREATE OR REPLACE FUNCTION public.get_platform_revenue_report(p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now())<br> RETURNS TABLE(fee_type text, asset_symbol text, total_collected numeric, total_collected_usd numeric, transaction_count bigint, avg_fee numeric, first_collected_at timestamp with time zone, last_collected_at timestamp with time zone)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    SELECT<br>        pf.fee_type,<br>        pf.asset_symbol,<br>        ROUND(SUM(pf.amount), 8)                                  AS total_collected,<br>        ROUND(SUM(pf.amount * COALESCE(ap.price_usd, 0)), 2)      AS total_collected_usd,<br>        COUNT(*)::bigint                                           AS transaction_count,<br>        ROUND(AVG(pf.amount), 8)                                   AS avg_fee,<br>        MIN(pf.collected_at)                                       AS first_collected_at,<br>        MAX(pf.collected_at)                                       AS last_collected_at<br>    FROM public.platform_fees pf<br>    LEFT JOIN public.asset_prices ap ON ap.asset_symbol = pf.asset_symbol<br>    WHERE pf.collected_at BETWEEN p_from AND p_to<br>    GROUP BY pf.fee_type, pf.asset_symbol<br>    ORDER BY total_collected_usd DESC;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   |
| public      | get_realtime_prices                 | p_symbols text[]                                                                                                                                                                  | TABLE(symbol text, current_price_usd numeric, price_change_24h numeric, last_update timestamp with time zone, is_success boolean, error_message text, source text)                                                                                                                                                                                                                                                                                                                                              | CREATE OR REPLACE FUNCTION public.get_realtime_prices(p_symbols text[])<br> RETURNS TABLE(symbol text, current_price_usd numeric, price_change_24h numeric, last_update timestamp with time zone, is_success boolean, error_message text, source text)<br> LANGUAGE plpgsql<br>AS $function$<br>DECLARE<br>    v_edge_function_url text := 'https://jbzbwyuawejdhhutkmkk.supabase.co/functions/v1';<br>    v_response json;<br>BEGIN<br>    BEGIN<br>        SELECT content::json INTO v_response<br>        FROM http((<br>            'GET',<br>            v_edge_function_url \|\| '/get-prices?symbols=' \|\| array_to_string(p_symbols, ','),<br>            ARRAY[http_header('Accept', 'application/json')],<br>            '',<br>            ''<br>        )::http_request);<br><br>        IF v_response->>'success' = 'true' THEN<br>            FOR symbol IN SELECT unnest(p_symbols)<br>            LOOP<br>                RETURN QUERY SELECT<br>                    symbol,<br>                    COALESCE((v_response->'prices'->symbol->>'current_price_usd')::numeric, 0),<br>                    COALESCE((v_response->'prices'->symbol->>'price_change_24h')::numeric, 0),<br>                    COALESCE((v_response->'prices'->symbol->>'last_update')::timestamptz, NOW()),<br>                    (v_response->'prices'->symbol->>'current_price_usd') IS NOT NULL,<br>                    CASE WHEN (v_response->'prices'->symbol->>'current_price_usd') IS NULL<br>                         THEN 'Prix non disponible' ELSE NULL END,<br>                    COALESCE(v_response->>'source', 'unknown');<br>            END LOOP;<br>            RETURN;<br>        END IF;<br>    EXCEPTION WHEN OTHERS THEN<br>        RAISE NOTICE 'Erreur appel Edge Function: %, utilisation cache', SQLERRM;<br>    END;<br><br>    -- FALLBACK : lire depuis asset_prices (nouvelle table dédiée aux prix)<br>    RETURN QUERY<br>    SELECT<br>        sa.symbol,<br>        COALESCE(ap.price_usd, 0),<br>        COALESCE(ap.change_24h, 0),<br>        ap.updated_at,<br>        (ap.price_usd > 0 AND ap.updated_at > NOW() - INTERVAL '5 minutes'),<br>        CASE<br>            WHEN ap.price_usd IS NULL OR ap.price_usd <= 0 THEN 'Prix nul en cache'<br>            WHEN ap.updated_at <= NOW() - INTERVAL '5 minutes' THEN 'Prix en cache obsolètes'<br>            ELSE NULL<br>        END,<br>        'cache'<br>    FROM supported_assets sa<br>    LEFT JOIN asset_prices ap ON ap.asset_symbol = sa.symbol<br>    WHERE sa.symbol = ANY(p_symbols)<br>    AND sa.is_active = true;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                |
| public      | get_staking_pools                   |                                                                                                                                                                                   | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.get_staking_pools()<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_user_id uuid := auth.uid();<br>  v_result  jsonb;<br>BEGIN<br>  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_result<br>  FROM (<br>    SELECT<br>      sp.id                          AS pool_id,<br>      sp.name                        AS pool_name,<br>      sp.asset_symbol,<br>      sp.asset_symbol                AS reward_asset_symbol,<br>      'fixed'                        AS apy_mode,<br>      sp.base_apy,<br>      sp.base_apy                    AS current_apy,<br>      sp.min_stake,<br>      sp.max_stake,<br>      sp.total_staked,<br>      sp.max_pool_capacity           AS total_capacity,<br>      sp.lock_period_days,<br>      sp.instant_unstake_enabled,<br>      sp.instant_unstake_fee_percent,<br>      sp.is_active,<br>      sp.description,<br>      us.amount                      AS user_staked_amount,<br>      us.pending_rewards             AS user_pending_rewards,<br>      us.unlock_at<br>    FROM staking_pools sp<br>    LEFT JOIN user_stakes us<br>      ON us.pool_id = sp.id AND us.user_id = v_user_id AND us.status = 'active'<br>    WHERE sp.is_active = true<br>    ORDER BY sp.sort_order, sp.created_at<br>  ) t;<br><br>  RETURN v_result;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  |
| public      | get_strategy_convergence            | p_symbol text                                                                                                                                                                     | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.get_strategy_convergence(p_symbol text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_total       integer := 0;<br>  v_bullish     integer := 0;<br>  v_bearish     integer := 0;<br>  v_neutral     integer := 0;<br>  v_trend       text    := 'neutral';<br>  v_total_strats integer := 0;<br>BEGIN<br>  -- Nombre total de stratégies actives (dynamique)<br>  SELECT COUNT(*) INTO v_total_strats<br>  FROM trading_strategy_config<br>  WHERE is_active = true;<br><br>  SELECT<br>    COUNT(*)                                                                      AS total,<br>    COUNT(*) FILTER (WHERE signal IN ('STRONG_BUY','BUY','LONG_STRONG','LONG'))  AS bullish,<br>    COUNT(*) FILTER (WHERE signal IN ('STRONG_SELL','SELL','SHORT_STRONG','SHORT')) AS bearish,<br>    COUNT(*) FILTER (WHERE signal = 'WAIT')                                       AS neutral<br>  INTO v_total, v_bullish, v_bearish, v_neutral<br>  FROM (<br>    -- La plus récente analyse par stratégie sur ce symbole (dernières 24h)<br>    SELECT DISTINCT ON (strategy_key) signal<br>    FROM public.trading_analyses<br>    WHERE symbol     = p_symbol<br>      AND created_at > NOW() - INTERVAL '24 hours'<br>    ORDER BY strategy_key, created_at DESC<br>  ) sub;<br><br>  IF v_bullish > v_bearish THEN<br>    v_trend := 'bullish';<br>  ELSIF v_bearish > v_bullish THEN<br>    v_trend := 'bearish';<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'symbol',                   p_symbol,<br>    'total',                    v_total,<br>    'total_strategies_available', v_total_strats,<br>    'coverage_pct',             CASE WHEN v_total_strats > 0<br>                                     THEN ROUND((v_total::numeric / v_total_strats) * 100)<br>                                     ELSE 0 END,<br>    'bullish',                  v_bullish,<br>    'bearish',                  v_bearish,<br>    'neutral',                  v_neutral,<br>    'trend',                    v_trend,<br>    'label',                    format('%s/%s stratégies haussières', v_bullish, v_total_strats)<br>  );<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          