                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | get_strategy_performance            |                                                                                                                                                                                   | TABLE(strategy_key text, wins bigint, losses bigint, total bigint, win_rate numeric)                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.get_strategy_performance()<br> RETURNS TABLE(strategy_key text, wins bigint, losses bigint, total bigint, win_rate numeric)<br> LANGUAGE sql<br> STABLE<br>AS $function$<br>  SELECT<br>    strategy_key,<br>    COUNT(*) FILTER (WHERE actual_outcome = 'win')  AS wins,<br>    COUNT(*) FILTER (WHERE actual_outcome = 'loss') AS losses,<br>    COUNT(*) FILTER (WHERE actual_outcome IN ('win','loss')) AS total,<br>    ROUND(<br>      COUNT(*) FILTER (WHERE actual_outcome = 'win')::numeric /<br>      NULLIF(COUNT(*) FILTER (WHERE actual_outcome IN ('win','loss')), 0) * 100,<br>      2<br>    ) AS win_rate<br>  FROM public.trading_prediction_history<br>  WHERE strategy_key IS NOT NULL<br>    AND actual_outcome IN ('win', 'loss')<br>  GROUP BY strategy_key<br>  ORDER BY win_rate DESC NULLS LAST;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      