                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | get_swap_rates                      | p_from_asset text, p_to_asset text                                                                                                                                                | TABLE(from_asset text, to_asset text, exchange_rate numeric, inverse_rate numeric, from_asset_price_usd numeric, to_asset_price_usd numeric, fee_percentage numeric, is_available boolean)                                                                                                                                                                                                                                                                                                                      | CREATE OR REPLACE FUNCTION public.get_swap_rates(p_from_asset text DEFAULT NULL::text, p_to_asset text DEFAULT NULL::text)<br> RETURNS TABLE(from_asset text, to_asset text, exchange_rate numeric, inverse_rate numeric, from_asset_price_usd numeric, to_asset_price_usd numeric, fee_percentage numeric, is_available boolean)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    WITH asset_pairs AS (<br>        SELECT<br>            sa1.symbol           AS from_symbol,<br>            sa2.symbol           AS to_symbol,<br>            COALESCE(ap1.price_usd, 0) AS from_price,<br>            COALESCE(ap2.price_usd, 0) AS to_price,<br>            COALESCE(sa2.transfer_fee_percentage, 0.5) AS fee_pct,<br>            (sa1.is_active AND sa2.is_active AND sa1.can_be_swapped AND sa2.can_be_swapped) AS available<br>        FROM supported_assets sa1<br>        CROSS JOIN supported_assets sa2<br>        LEFT JOIN asset_prices ap1 ON ap1.asset_symbol = sa1.symbol<br>        LEFT JOIN asset_prices ap2 ON ap2.asset_symbol = sa2.symbol<br>        WHERE sa1.symbol != sa2.symbol<br>        AND sa1.is_active = true<br>        AND sa2.is_active = true<br>        AND (p_from_asset IS NULL OR sa1.symbol = p_from_asset)<br>        AND (p_to_asset   IS NULL OR sa2.symbol = p_to_asset)<br>    )<br>    SELECT<br>        ap.from_symbol,<br>        ap.to_symbol,<br>        CASE WHEN ap.to_price > 0 THEN ap.from_price / ap.to_price ELSE 0 END,<br>        CASE WHEN ap.from_price > 0 THEN ap.to_price / ap.from_price ELSE 0 END,<br>        ap.from_price,<br>        ap.to_price,<br>        ap.fee_pct,<br>        ap.available AND (ap.from_price > 0) AND (ap.to_price > 0)<br>    FROM asset_pairs ap<br>    ORDER BY ap.from_symbol, ap.to_symbol;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        |
| public      | get_trading_analysis_detail         | p_analysis_id uuid, p_user_id uuid                                                                                                                                                | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.get_trading_analysis_detail(p_analysis_id uuid, p_user_id uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_result jsonb;<br>BEGIN<br>  SELECT to_jsonb(ta.*) \|\| jsonb_build_object(<br>    'strategy_name',        tsc.name,<br>    'strategy_description', tsc.description<br>  )<br>  INTO v_result<br>  FROM public.trading_analyses ta<br>  LEFT JOIN public.trading_strategy_config tsc<br>         ON tsc.strategy_key = ta.strategy_key<br>  WHERE ta.id      = p_analysis_id<br>    AND ta.user_id = p_user_id;<br><br>  IF v_result IS NULL THEN<br>    RETURN jsonb_build_object('error', 'Analysis not found');<br>  END IF;<br><br>  RETURN v_result;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| public      | get_transaction_impact              | p_type text                                                                                                                                                                       | text                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.get_transaction_impact(p_type text)<br> RETURNS text<br> LANGUAGE sql<br> IMMUTABLE<br>AS $function$<br>    SELECT CASE p_type<br>        -- CRÉDITS (argent reçu)<br>        WHEN 'deposit'            THEN 'credit'<br>        WHEN 'staking_reward'     THEN 'credit'<br>        WHEN 'unstake_completed'  THEN 'credit'  -- ← corrigé : l'user reçoit ses tokens<br>        WHEN 'game_win'           THEN 'credit'<br>        WHEN 'referral_bonus'     THEN 'credit'<br>        WHEN 'cashback'           THEN 'credit'<br>        WHEN 'refund'             THEN 'credit'<br>        WHEN 'commission'         THEN 'credit'<br>        WHEN 'dividend_payment'   THEN 'credit'<br>        WHEN 'lending_reward'     THEN 'credit'<br>        WHEN 'swap_credit'        THEN 'credit'<br>        WHEN 'asset_conversion'   THEN 'credit'<br><br>        -- DÉBITS (argent envoyé)<br>        WHEN 'withdrawal'         THEN 'debit'<br>        WHEN 'staking'            THEN 'debit'<br>        WHEN 'staking_lock'       THEN 'debit'<br>        WHEN 'unstaking'          THEN 'debit'<br>        WHEN 'game_bet'           THEN 'debit'<br>        WHEN 'wakati_purchase'    THEN 'debit'<br>        WHEN 'fee'                THEN 'debit'<br>        WHEN 'platform_fee'       THEN 'debit'<br>        WHEN 'swap_debit'         THEN 'debit'<br><br>        -- NEUTRES (transferts — montant net = 0 pour la plateforme)<br>        WHEN 'transfer'           THEN 'neutral'<br>        WHEN 'p2p_transfer'       THEN 'neutral'<br>        WHEN 'internal_transfer'  THEN 'neutral'<br>        WHEN 'balance_adjustment' THEN 'neutral'<br><br>        ELSE 'neutral'<br>    END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | get_user_all_addresses              | p_user_id uuid                                                                                                                                                                    | TABLE(asset_symbol text, ledger_symbol text, asset_name text, network text, address text, derivation_index integer, is_active boolean, cached_balance numeric, last_balance_check timestamp with time zone, qr_code_data text)                                                                                                                                                                                                                                                                                  | CREATE OR REPLACE FUNCTION public.get_user_all_addresses(p_user_id uuid)<br> RETURNS TABLE(asset_symbol text, ledger_symbol text, asset_name text, network text, address text, derivation_index integer, is_active boolean, cached_balance numeric, last_balance_check timestamp with time zone, qr_code_data text)<br> LANGUAGE plpgsql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    SELECT<br>        ua.asset_symbol,<br>        sa.ledger_symbol,<br>        sa.name,<br>        ua.network,<br>        ua.address,<br>        ua.derivation_index,<br>        ua.is_active,<br>        ua.cached_balance,<br>        ua.last_balance_check,<br>        format('%s:%s', LOWER(sa.symbol), ua.address) AS qr_data<br>    FROM user_addresses ua<br>    JOIN supported_assets sa<br>        ON ua.asset_symbol = sa.symbol AND ua.network = sa.network<br>    WHERE ua.user_id = p_user_id<br>    ORDER BY sa.is_native DESC, sa.name;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | get_user_assets_for_purchase        | p_user_id uuid                                                                                                                                                                    | TABLE(asset_symbol text, asset_name text, available_balance numeric, current_price_usd numeric, wakati_exchange_rate numeric, max_wakati_purchasable numeric, is_eligible boolean)                                                                                                                                                                                                                                                                                                                              | CREATE OR REPLACE FUNCTION public.get_user_assets_for_purchase(p_user_id uuid)<br> RETURNS TABLE(asset_symbol text, asset_name text, available_balance numeric, current_price_usd numeric, wakati_exchange_rate numeric, max_wakati_purchasable numeric, is_eligible boolean)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>DECLARE<br>  v_wakati_price numeric;<br>  v_fee_pct      numeric := 0.5;  -- frais par défaut 0.5%<br>BEGIN<br>  -- Prix WAKATI actuel<br>  SELECT ap_w.price_usd INTO v_wakati_price<br>  FROM public.asset_prices ap_w<br>  WHERE ap_w.asset_symbol = 'WAKATI'<br>  LIMIT 1;<br><br>  -- Si WAKATI n'a pas de prix, impossible de calculer<br>  IF v_wakati_price IS NULL OR v_wakati_price = 0 THEN<br>    RAISE EXCEPTION 'Prix WAKATI introuvable ou nul dans asset_prices';<br>  END IF;<br><br>  RETURN QUERY<br>  SELECT<br>    ub.asset_symbol,<br>    sa.name                                           AS asset_name,<br>    ub.available_balance,<br>    COALESCE(ap.price_usd, 0)                        AS current_price_usd,<br><br>    -- Taux : combien de WAKATI pour 1 unité de l'asset<br>    -- Ex: BNB = $300, WAKATI = $0.0018 → 300 / 0.0018 = 166 666 WAKATI/BNB<br>    CASE<br>      WHEN COALESCE(ap.price_usd, 0) > 0<br>      THEN ROUND(ap.price_usd / v_wakati_price, 2)<br>      ELSE 0<br>    END                                               AS wakati_exchange_rate,<br><br>    -- Max WAKATI achetable avec le solde disponible, frais déduits<br>    -- total_debit = from_amount * (1 + fee%) → from_amount = balance / (1 + fee%)<br>    -- wakati_max = from_amount * exchange_rate<br>    CASE<br>      WHEN COALESCE(ap.price_usd, 0) > 0<br>      THEN ROUND(<br>        (ub.available_balance / (1 + v_fee_pct / 100))<br>        * (ap.price_usd / v_wakati_price),<br>        2<br>      )<br>      ELSE 0<br>    END                                               AS max_wakati_purchasable,<br><br>    (ub.available_balance > 0 AND sa.is_active = true) AS is_eligible<br><br>  FROM public.user_balances ub<br>  JOIN public.supported_assets sa<br>    ON ub.asset_symbol = sa.symbol<br>  LEFT JOIN public.asset_prices ap<br>    ON ap.asset_symbol = ub.asset_symbol<br>  WHERE ub.user_id          = p_user_id<br>    AND ub.available_balance > 0<br>    AND ub.asset_symbol     != 'WAKATI'<br>    AND sa.is_active         = true<br>  ORDER BY (ub.available_balance * COALESCE(ap.price_usd, 0)) DESC;  -- tri par valeur USD décroissante<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | get_user_portfolio                  | p_user_id uuid                                                                                                                                                                    | TABLE(asset_symbol text, asset_name text, available_balance numeric, staking_balance numeric, total_balance numeric, price_usd numeric, value_usd numeric, staking_value_usd numeric, total_value_usd numeric, pct_of_portfolio numeric)                                                                                                                                                                                                                                                                        | CREATE OR REPLACE FUNCTION public.get_user_portfolio(p_user_id uuid)<br> RETURNS TABLE(asset_symbol text, asset_name text, available_balance numeric, staking_balance numeric, total_balance numeric, price_usd numeric, value_usd numeric, staking_value_usd numeric, total_value_usd numeric, pct_of_portfolio numeric)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>DECLARE<br>    v_total_usd numeric;<br>BEGIN<br>    SELECT COALESCE(SUM(<br>        (COALESCE(ub.available_balance, 0) + COALESCE(ub.staking_balance, 0))<br>        * COALESCE(ap.price_usd, 0)<br>    ), 0)<br>    INTO v_total_usd<br>    FROM (<br>        -- Prefere le nom d'un reseau "officiel" (non-BSC/Binance-Peg) pour<br>        -- l'affichage unifie, purement cosmetique.<br>        SELECT DISTINCT ON (sa.ledger_symbol) sa.ledger_symbol, sa.name<br>        FROM public.supported_assets sa<br>        WHERE sa.is_active = true<br>        ORDER BY sa.ledger_symbol, sa.is_native DESC, (sa.network = 'BSC') ASC, sa.symbol<br>    ) ua<br>    LEFT JOIN public.user_balances ub ON ub.asset_symbol = ua.ledger_symbol<br>                                     AND ub.user_id = p_user_id<br>    LEFT JOIN public.asset_prices ap  ON ap.asset_symbol = ua.ledger_symbol;<br><br>    RETURN QUERY<br>    SELECT<br>        ua.ledger_symbol,<br>        ua.name,<br>        ROUND(COALESCE(ub.available_balance, 0), 8)                          AS available_balance,<br>        ROUND(COALESCE(ub.staking_balance, 0), 8)                            AS staking_balance,<br>        ROUND(COALESCE(ub.available_balance, 0)<br>            + COALESCE(ub.staking_balance, 0), 8)                            AS total_balance,<br>        COALESCE(ap.price_usd, 0)                                            AS price_usd,<br>        ROUND(COALESCE(ub.available_balance, 0)<br>            * COALESCE(ap.price_usd, 0), 2)                                  AS value_usd,<br>        ROUND(COALESCE(ub.staking_balance, 0)<br>            * COALESCE(ap.price_usd, 0), 2)                                  AS staking_value_usd,<br>        ROUND((COALESCE(ub.available_balance, 0)<br>            + COALESCE(ub.staking_balance, 0))<br>            * COALESCE(ap.price_usd, 0), 2)                                  AS total_value_usd,<br>        CASE<br>            WHEN v_total_usd = 0 THEN 0<br>            ELSE ROUND(<br>                (COALESCE(ub.available_balance, 0) + COALESCE(ub.staking_balance, 0))<br>                * COALESCE(ap.price_usd, 0) / v_total_usd * 100, 2<br>            )<br>        END                                                                   AS pct_of_portfolio<br>    FROM (<br>        SELECT DISTINCT ON (sa.ledger_symbol) sa.ledger_symbol, sa.name<br>        FROM public.supported_assets sa<br>        WHERE sa.is_active = true<br>        ORDER BY sa.ledger_symbol, sa.is_native DESC, (sa.network = 'BSC') ASC, sa.symbol<br>    ) ua<br>    LEFT JOIN public.user_balances ub ON ub.asset_symbol = ua.ledger_symbol<br>                                     AND ub.user_id = p_user_id<br>    LEFT JOIN public.asset_prices ap  ON ap.asset_symbol = ua.ledger_symbol<br>    ORDER BY total_value_usd DESC, ua.ledger_symbol ASC;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              |
| public      | get_user_portfolio_stats            | p_user_id uuid                                                                                                                                                                    | TABLE(total_portfolio_value_usd numeric, total_onchain_deposited_usd numeric, total_earned_usd numeric, daily_change_usd numeric, daily_change_percent numeric, weekly_change_usd numeric, total_staking_value_usd numeric, asset_count integer)                                                                                                                                                                                                                                                                | CREATE OR REPLACE FUNCTION public.get_user_portfolio_stats(p_user_id uuid)<br> RETURNS TABLE(total_portfolio_value_usd numeric, total_onchain_deposited_usd numeric, total_earned_usd numeric, daily_change_usd numeric, daily_change_percent numeric, weekly_change_usd numeric, total_staking_value_usd numeric, asset_count integer)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    WITH<br>    deposits AS (<br>        SELECT asset_symbol, COALESCE(SUM(amount), 0) AS total<br>        FROM transactions<br>        WHERE user_id = p_user_id AND type = 'deposit' AND status = 'completed'<br>        GROUP BY asset_symbol<br>    ),<br>    withdrawals AS (<br>        SELECT asset_symbol, COALESCE(SUM(amount), 0) AS total<br>        FROM transactions<br>        WHERE user_id = p_user_id AND type IN ('withdraw', 'withdrawal') AND status = 'completed'<br>        GROUP BY asset_symbol<br>    ),<br>    portfolio_data AS (<br>        SELECT<br>            ub.asset_symbol,<br>            ub.available_balance,<br>            ub.staking_balance,<br>            COALESCE(d.total, 0)                         AS onchain_deposited,<br>            COALESCE(w.total, 0)                         AS admin_withdrawn,<br>            COALESCE(ap.price_usd, 0)                    AS current_price_usd,<br>            COALESCE(ap.change_24h, 0)                   AS price_change_24h<br>        FROM user_balances ub<br>        JOIN supported_assets sa ON ub.asset_symbol = sa.symbol<br>        LEFT JOIN asset_prices ap ON ap.asset_symbol = ub.asset_symbol<br>        LEFT JOIN deposits      d  ON d.asset_symbol = ub.asset_symbol<br>        LEFT JOIN withdrawals   w  ON w.asset_symbol = ub.asset_symbol<br>        WHERE ub.user_id = p_user_id<br>        AND ub.available_balance > 0<br>    )<br>    SELECT<br>        SUM(pd.available_balance * pd.current_price_usd),<br>        SUM(pd.onchain_deposited * pd.current_price_usd),<br>        SUM((pd.available_balance<br>             - (pd.onchain_deposited - pd.admin_withdrawn))<br>             * pd.current_price_usd),<br>        SUM(pd.available_balance * pd.current_price_usd * (pd.price_change_24h / 100)),<br>        CASE<br>            WHEN SUM(pd.available_balance * pd.current_price_usd) > 0<br>            THEN (SUM(pd.available_balance * pd.current_price_usd * (pd.price_change_24h / 100))<br>                  / SUM(pd.available_balance * pd.current_price_usd)) * 100<br>            ELSE 0<br>        END,<br>        0::numeric,<br>        SUM(pd.staking_balance * pd.current_price_usd),<br>        COUNT(*)::integer<br>    FROM portfolio_data pd;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | get_user_profile                    | p_user_id uuid                                                                                                                                                                    | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.get_user_profile(p_user_id uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_profile jsonb;<br>BEGIN<br>  SELECT to_jsonb(u.*) INTO v_profile<br>  FROM public.users u<br>  WHERE u.id = p_user_id;<br>  <br>  RETURN v_profile;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              