                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | get_user_swap_history               | p_user_id uuid, p_limit integer, p_offset integer                                                                                                                                 | TABLE(transaction_id uuid, from_asset text, to_asset text, from_amount numeric, to_amount numeric, exchange_rate numeric, fee_amount numeric, created_at timestamp with time zone)                                                                                                                                                                                                                                                                                                                              | CREATE OR REPLACE FUNCTION public.get_user_swap_history(p_user_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)<br> RETURNS TABLE(transaction_id uuid, from_asset text, to_asset text, from_amount numeric, to_amount numeric, exchange_rate numeric, fee_amount numeric, created_at timestamp with time zone)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    SELECT <br>        t_credit.id as transaction_id,<br>        t_debit.metadata->>'from_asset' as from_asset,<br>        t_credit.asset_symbol as to_asset,<br>        (t_debit.amount)::numeric as from_amount,<br>        t_credit.amount as to_amount,<br>        (t_credit.metadata->>'exchange_rate')::numeric as exchange_rate,<br>        COALESCE((t_fee.amount)::numeric, 0) as fee_amount,<br>        t_credit.created_at<br>    FROM transactions t_credit<br>    JOIN transactions t_debit ON t_credit.reference_id = t_debit.id<br>    LEFT JOIN transactions t_fee ON t_fee.reference_id = t_debit.id AND t_fee.type = 'swap_fee'<br>    WHERE t_credit.user_id = p_user_id<br>    AND t_credit.type = 'swap_credit'<br>    ORDER BY t_credit.created_at DESC<br>    LIMIT p_limit<br>    OFFSET p_offset;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                