                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | get_user_trading_analyses           | p_user_id uuid, p_limit integer, p_offset integer, p_symbol text                                                                                                                  | TABLE(id uuid, symbol text, base_asset text, market text, strategy_key text, strategy_name text, timeframe text, signal text, confidence integer, price_at_analysis numeric, price_at_check numeric, performance_pct numeric, stop_loss numeric, take_profit_1 numeric, take_profit_2 numeric, take_profit_3 numeric, risk_reward_1 numeric, risk_reward_2 numeric, risk_reward_3 numeric, valid_until timestamp with time zone, is_expired boolean, liquidity_score text, created_at timestamp with time zone) | CREATE OR REPLACE FUNCTION public.get_user_trading_analyses(p_user_id uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_symbol text DEFAULT NULL::text)<br> RETURNS TABLE(id uuid, symbol text, base_asset text, market text, strategy_key text, strategy_name text, timeframe text, signal text, confidence integer, price_at_analysis numeric, price_at_check numeric, performance_pct numeric, stop_loss numeric, take_profit_1 numeric, take_profit_2 numeric, take_profit_3 numeric, risk_reward_1 numeric, risk_reward_2 numeric, risk_reward_3 numeric, valid_until timestamp with time zone, is_expired boolean, liquidity_score text, created_at timestamp with time zone)<br> LANGUAGE sql<br> STABLE SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>  SELECT<br>    ta.id,<br>    ta.symbol,<br>    ta.base_asset,<br>    ta.market,<br>    ta.strategy_key,<br>    tsc.name        AS strategy_name,<br>    ta.timeframe,<br>    ta.signal,<br>    ta.confidence,<br>    ta.price_at_analysis,<br>    ta.price_at_check,<br>    ta.performance_pct,<br>    ta.stop_loss,<br>    ta.take_profit_1,<br>    ta.take_profit_2,<br>    ta.take_profit_3,<br>    ta.risk_reward_1,<br>    ta.risk_reward_2,<br>    ta.risk_reward_3,<br>    ta.valid_until,<br>    (ta.valid_until IS NOT NULL AND ta.valid_until < NOW()) AS is_expired,<br>    ta.liquidity_score,<br>    ta.created_at<br>  FROM public.trading_analyses ta<br>  LEFT JOIN public.trading_strategy_config tsc<br>         ON tsc.strategy_key = ta.strategy_key<br>  WHERE ta.user_id = p_user_id<br>    AND (p_symbol IS NULL OR ta.symbol = p_symbol)<br>  ORDER BY ta.created_at DESC<br>  LIMIT  p_limit<br>  OFFSET p_offset;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   