                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | get_user_transaction_history        | p_user_id uuid, p_asset_symbol text, p_transaction_type text, p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_limit integer, p_offset integer | TABLE(transaction_id uuid, type text, asset_symbol text, amount numeric, fee numeric, net_amount numeric, status text, counterparty_username text, tx_hash text, created_at timestamp with time zone, metadata jsonb)                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.get_user_transaction_history(p_user_id uuid, p_asset_symbol text DEFAULT NULL::text, p_transaction_type text DEFAULT NULL::text, p_start_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_end_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)<br> RETURNS TABLE(transaction_id uuid, type text, asset_symbol text, amount numeric, fee numeric, net_amount numeric, status text, counterparty_username text, tx_hash text, created_at timestamp with time zone, metadata jsonb)<br> LANGUAGE plpgsql<br> STABLE<br>AS $function$<br>BEGIN<br>    RETURN QUERY<br>    SELECT <br>        t.id,<br>        t.type,<br>        t.asset_symbol,<br>        t.amount,<br>        t.fee,<br>        t.net_amount,<br>        t.status,<br>        u.username as counterparty,<br>        t.tx_hash,<br>        t.created_at,<br>        t.metadata<br>    FROM transactions t<br>    LEFT JOIN users u ON t.counterparty_id = u.id<br>    WHERE t.user_id = p_user_id<br>    AND (p_asset_symbol IS NULL OR t.asset_symbol = p_asset_symbol)<br>    AND (p_transaction_type IS NULL OR t.type = p_transaction_type)<br>    AND (p_start_date IS NULL OR t.created_at >= p_start_date)<br>    AND (p_end_date IS NULL OR t.created_at <= p_end_date)<br>    ORDER BY t.created_at DESC<br>    LIMIT p_limit<br>    OFFSET p_offset;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            |
| public      | get_wakati_flows                    | p_days integer                                                                                                                                                                    | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.get_wakati_flows(p_days integer DEFAULT 30)<br> RETURNS jsonb<br> LANGUAGE sql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>  select jsonb_build_object(<br>    'days', p_days,<br>    'tx', coalesce((<br>      select jsonb_agg(jsonb_build_object('type', type, 'count', n, 'total', total) order by total desc)<br>      from (<br>        select t.type, count(*)::int as n, coalesce(sum(t.amount), 0) as total<br>        from transactions t<br>        where t.asset_symbol = 'WAKATI' and t.status = 'completed'<br>          and t.created_at > now() - make_interval(days => greatest(p_days, 1))<br>        group by t.type<br>      ) x<br>    ), '[]'::jsonb),<br>    'fees', coalesce((<br>      select jsonb_agg(jsonb_build_object('type', fee_type, 'count', n, 'total', total) order by total desc)<br>      from (<br>        select pf.fee_type, count(*)::int as n, coalesce(sum(pf.amount), 0) as total<br>        from platform_fees pf<br>        where pf.asset_symbol = 'WAKATI' and pf.is_test = false and pf.fee_type <> 'game_net_loss'<br>          and pf.collected_at > now() - make_interval(days => greatest(p_days, 1))<br>        group by pf.fee_type<br>      ) y<br>    ), '[]'::jsonb)<br>  )<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              |
| public      | get_wheel_state                     | p_user_id uuid                                                                                                                                                                    | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.get_wheel_state(p_user_id uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_config    RECORD;<br>  v_stats     RECORD;<br>  v_now       TIMESTAMPTZ := NOW();<br>  v_eligible  BOOLEAN;<br>  v_daily     INTEGER;<br>BEGIN<br>  SELECT * INTO v_config FROM public.wheel_config WHERE id = 1;<br><br>  IF NOT v_config.is_active THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Roue temporairement désactivée');<br>  END IF;<br><br>  v_eligible := public.fn_user_can_get_free_spins(p_user_id);<br>  v_daily    := CASE WHEN v_eligible THEN v_config.free_spins_daily ELSE 0 END;<br><br>  INSERT INTO public.user_wheel_stats (user_id, free_spins_remaining, free_spins_reset_at)<br>  VALUES (p_user_id, v_daily, date_trunc('day', v_now) + INTERVAL '1 day')<br>  ON CONFLICT (user_id) DO NOTHING;<br><br>  SELECT * INTO v_stats FROM public.user_wheel_stats WHERE user_id = p_user_id;<br><br>  IF v_stats.free_spins_reset_at <= v_now THEN<br>    UPDATE public.user_wheel_stats<br>    SET free_spins_remaining = v_daily,<br>        free_spins_reset_at  = date_trunc('day', v_now) + INTERVAL '1 day',<br>        updated_at           = v_now<br>    WHERE user_id = p_user_id;<br><br>    v_stats.free_spins_remaining := v_daily;<br>    v_stats.free_spins_reset_at  := date_trunc('day', v_now) + INTERVAL '1 day';<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'success',              true,<br>    'free_spins_daily',     v_daily,<br>    'free_spins_eligible',  v_eligible,<br>    'paid_spin_cost',       v_config.paid_spin_cost_amount,<br>    'paid_spin_cost_asset', v_config.paid_spin_cost_asset,<br>    'jackpot_amount',       v_config.jackpot_current_amount,<br>    'jackpot_asset',        v_config.jackpot_asset_symbol,<br>    'free_spins_remaining', v_stats.free_spins_remaining,<br>    'free_spins_reset_at',  v_stats.free_spins_reset_at,<br>    'current_streak',       v_stats.current_streak,<br>    'longest_streak',       v_stats.longest_streak,<br>    'total_spins',          v_stats.total_spins,<br>    -- ✅ Messages configurables en BDD, éditables sans mise à jour de l'app.<br>    'messages',             COALESCE(v_config.messages, '{}'::jsonb),<br>    'wakati_balance',       COALESCE((<br>      SELECT available_balance FROM public.user_balances<br>      WHERE user_id = p_user_id AND asset_symbol = v_config.paid_spin_cost_asset<br>    ), 0)<br>  );<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                |
| public      | handle_new_auth_user                |                                                                                                                                                                                   | trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         | CREATE OR REPLACE FUNCTION public.handle_new_auth_user()<br> RETURNS trigger<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_referral_code text;<br>  v_username      text;<br>BEGIN<br>  -- Générer un code referral unique format WKT<br>  LOOP<br>    v_referral_code := 'WKT' \|\| UPPER(SUBSTRING(MD5(RANDOM()::text \|\| CLOCK_TIMESTAMP()::text) FROM 1 FOR 6));<br>    EXIT WHEN NOT EXISTS (<br>      SELECT 1 FROM public.users WHERE referral_code = v_referral_code<br>    );<br>  END LOOP;<br><br>  -- Username temporaire basé sur le nom Google ou l'email, tronqué à 20 chars<br>  v_username := COALESCE(<br>    LOWER(REGEXP_REPLACE(NEW.raw_user_meta_data->>'full_name', '[^a-zA-Z0-9_]', '', 'g')),<br>    LOWER(SPLIT_PART(NEW.email, '@', 1))<br>  );<br>  v_username := REGEXP_REPLACE(v_username, '[^a-zA-Z0-9_]', '', 'g');<br><br>  -- Tronquer à 20 chars max<br>  IF LENGTH(v_username) > 20 THEN<br>    v_username := SUBSTRING(v_username FROM 1 FOR 20);<br>  END IF;<br><br>  IF LENGTH(v_username) = 0 THEN<br>    v_username := 'user' \|\| SUBSTRING(MD5(NEW.id::text) FROM 1 FOR 8);<br>  END IF;<br><br>  -- Dédoublonner si nécessaire<br>  IF EXISTS (SELECT 1 FROM public.users WHERE username = v_username) THEN<br>    v_username := SUBSTRING(v_username FROM 1 FOR 16) \|\| SUBSTRING(MD5(RANDOM()::text) FROM 1 FOR 4);<br>  END IF;<br><br>  -- Insérer le profil<br>  INSERT INTO public.users (<br>    id,<br>    email,<br>    username,<br>    referral_code,<br>    referred_by,<br>    email_confirmed,<br>    profile_completed,<br>    is_verified,<br>    avatar_url<br>  ) VALUES (<br>    NEW.id,<br>    NEW.email,<br>    v_username,<br>    v_referral_code,<br>    NULL,<br>    COALESCE(NEW.email_confirmed_at IS NOT NULL, true),<br>    false,<br>    false,<br>    NEW.raw_user_meta_data->>'avatar_url'<br>  )<br>  ON CONFLICT (id) DO NOTHING;<br><br>  -- Initialiser balances, multiplicateurs, limites de transaction<br>  PERFORM public.initialize_user_data(NEW.id);<br><br>  RETURN NEW;<br><br>EXCEPTION WHEN OTHERS THEN<br>  RAISE NOTICE 'handle_new_auth_user error for %: %', NEW.id, SQLERRM;<br>  RETURN NEW;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | handle_user_auth_flow               | p_user_id uuid                                                                                                                                                                    | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.handle_user_auth_flow(p_user_id uuid)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public', 'auth'<br>AS $function$<br>DECLARE<br>  v_user_profile jsonb;<br>  v_auth_user auth.users%ROWTYPE;<br>  v_is_new boolean := false;<br>  v_username text;<br>  v_referral_code text;<br>  v_retry_count integer := 0;<br>  v_max_retries constant integer := 3;<br>BEGIN<br>  -- 🔐 VÉRIFICATION DE SÉCURITÉ<br>  IF p_user_id IS NULL THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'User ID required',<br>      'code', 'INVALID_INPUT'<br>    );<br>  END IF;<br>  <br>  -- 1. RÉCUPÉRER L'UTILISATEUR AUTH<br>  SELECT * INTO v_auth_user<br>  FROM auth.users<br>  WHERE id = p_user_id AND deleted_at IS NULL;<br>  <br>  IF v_auth_user IS NULL THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'User not found or deleted',<br>      'code', 'USER_NOT_FOUND'<br>    );<br>  END IF;<br>  <br>  -- 2. VÉRIFIER SI LE PROFIL EXISTE DÉJÀ<br>  SELECT to_jsonb(u.*) INTO v_user_profile<br>  FROM users u<br>  WHERE u.id = p_user_id;<br>  <br>  -- 3. PROFIL EXISTANT - RETOUR DIRECT<br>  IF v_user_profile IS NOT NULL THEN<br>    -- Mettre à jour email_confirmed si nécessaire<br>    IF v_auth_user.email_confirmed_at IS NOT NULL AND <br>       (v_user_profile->>'email_confirmed')::boolean = false THEN<br>      UPDATE users <br>      SET email_confirmed = true, updated_at = NOW()<br>      WHERE id = p_user_id;<br>      <br>      SELECT to_jsonb(u.*) INTO v_user_profile<br>      FROM users u WHERE u.id = p_user_id;<br>    END IF;<br>    <br>    RETURN jsonb_build_object(<br>      'success', true,<br>      'data', v_user_profile,<br>      'is_new', false,<br>      'message', 'Existing profile retrieved',<br>      'code', 'PROFILE_EXISTS'<br>    );<br>  END IF;<br>  <br>  -- 4. CRÉER LE PROFIL (CAS RARE - normalement fait par le trigger)<br>  v_is_new := true;<br>  <br>  -- Tentative de création avec retry en cas de conflit<br>  WHILE v_retry_count < v_max_retries LOOP<br>    BEGIN<br>      -- Générer username unique<br>      v_username := LOWER(SPLIT_PART(v_auth_user.email, '@', 1));<br>      v_username := REGEXP_REPLACE(v_username, '[^a-zA-Z0-9]', '', 'g');<br>      <br>      IF LENGTH(v_username) = 0 THEN<br>        v_username := 'user' \|\| SUBSTRING(MD5(p_user_id::text) FROM 1 FOR 8);<br>      END IF;<br>      <br>      -- Ajouter suffixe si nécessaire<br>      IF v_retry_count > 0 THEN<br>        v_username := v_username \|\| v_retry_count;<br>      END IF;<br>      <br>      -- Vérifier unicité username<br>      IF EXISTS (SELECT 1 FROM users WHERE username = v_username) THEN<br>        v_retry_count := v_retry_count + 1;<br>        CONTINUE;<br>      END IF;<br>      <br>      -- Générer code de parrainage<br>      v_referral_code := 'WKT' \|\| UPPER(SUBSTRING(<br>        MD5(p_user_id::text \|\| v_auth_user.email \|\| EXTRACT(EPOCH FROM NOW())::text \|\| v_retry_count::text) <br>        FROM 1 FOR 7<br>      ));<br>      <br>      -- Vérifier unicité referral_code<br>      IF EXISTS (SELECT 1 FROM users WHERE referral_code = v_referral_code) THEN<br>        v_retry_count := v_retry_count + 1;<br>        CONTINUE;<br>      END IF;<br>      <br>      -- Insérer l'utilisateur<br>      INSERT INTO users (<br>        id,<br>        username,<br>        email,<br>        email_confirmed,<br>        referral_code,<br>        profile_completed,<br>        created_at,<br>        updated_at<br>      ) VALUES (<br>        p_user_id,<br>        v_username,<br>        v_auth_user.email,<br>        v_auth_user.email_confirmed_at IS NOT NULL,<br>        v_referral_code,<br>        false,<br>        v_auth_user.created_at,<br>        v_auth_user.created_at<br>      );<br>      <br>      -- Initialiser les données utilisateur (appel direct pour ce cas)<br>      PERFORM public.initialize_user_data(p_user_id);<br>      <br>      EXIT; -- Succès, sortir de la boucle<br>      <br>    EXCEPTION<br>      WHEN unique_violation THEN<br>        v_retry_count := v_retry_count + 1;<br>        IF v_retry_count >= v_max_retries THEN<br>          RAISE EXCEPTION 'Failed to create unique profile after % attempts', v_max_retries;<br>        END IF;<br>        -- Continuer la boucle<br>      WHEN OTHERS THEN<br>        -- Journaliser et propager<br>        INSERT INTO auth_logs (<br>          user_id,<br>          action,<br>          details,<br>          error_message,<br>          created_at<br>        ) VALUES (<br>          p_user_id,<br>          'profile_creation_manual_error',<br>          jsonb_build_object('email', v_auth_user.email, 'retry_count', v_retry_count),<br>          SQLERRM,<br>          NOW()<br>        );<br>        RAISE;<br>    END;<br>  END LOOP;<br>  <br>  -- 5. RÉCUPÉRER LE NOUVEAU PROFIL<br>  SELECT to_jsonb(u.*) INTO v_user_profile<br>  FROM users u<br>  WHERE u.id = p_user_id;<br>  <br>  -- 6. JOURNALISATION SUCCÈS<br>  INSERT INTO auth_logs (<br>    user_id,<br>    action,<br>    details,<br>    created_at<br>  ) VALUES (<br>    p_user_id,<br>    'profile_created_manual',<br>    jsonb_build_object(<br>      'is_new', true, <br>      'username', v_username,<br>      'retries', v_retry_count<br>    ),<br>    NOW()<br>  );<br>  <br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'data', v_user_profile,<br>    'is_new', true,<br>    'message', 'New profile created successfully',<br>    'code', 'PROFILE_CREATED'<br>  );<br>  <br>EXCEPTION<br>  WHEN OTHERS THEN<br>    -- Retourner un profil minimal en cas d'erreur critique<br>    INSERT INTO auth_logs (<br>      user_id,<br>      action,<br>      details,<br>      error_message,<br>      created_at<br>    ) VALUES (<br>      p_user_id,<br>      'profile_creation_fallback',<br>      jsonb_build_object('email', COALESCE(v_auth_user.email, 'unknown')),<br>      SQLERRM,<br>      NOW()<br>    );<br>    <br>    -- Profil minimal pour éviter de bloquer l'application<br>    RETURN jsonb_build_object(<br>      'success', true,<br>      'data', jsonb_build_object(<br>        'id', p_user_id,<br>        'email', COALESCE(v_auth_user.email, ''),<br>        'username', COALESCE(v_username, 'user' \|\| SUBSTRING(MD5(p_user_id::text) FROM 1 FOR 8)),<br>        'profile_completed', false,<br>        'created_at', NOW(),<br>        'is_fallback', true<br>      ),<br>      'is_new', true,<br>      'message', 'Profile created with fallback mode',<br>      'warning', 'Partial initialization: ' \|\| SQLERRM,<br>      'code', 'PROFILE_FALLBACK'<br>    );<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          |
| public      | handle_user_email_confirmed         |                                                                                                                                                                                   | trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         | CREATE OR REPLACE FUNCTION public.handle_user_email_confirmed()<br> RETURNS trigger<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>BEGIN<br>    IF NEW.email_confirmed_at IS NOT NULL AND OLD.email_confirmed_at IS NULL THEN<br>        UPDATE public.users<br>        SET email_confirmed = true,<br>            updated_at      = now()<br>        WHERE id = NEW.id;<br>    END IF;<br>    RETURN NEW;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  |
| public      | increment_balance                   | p_user_id uuid, p_asset_symbol text, p_amount numeric                                                                                                                             | numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         | CREATE OR REPLACE FUNCTION public.increment_balance(p_user_id uuid, p_asset_symbol text, p_amount numeric)<br> RETURNS numeric<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  new_balance numeric;<br>BEGIN<br>  -- Réservé aux rôles internes uniquement<br>  IF current_role NOT IN ('service_role', 'postgres', 'supabase_admin') THEN<br>    RAISE EXCEPTION 'increment_balance: accès non autorisé (rôle: %)', current_role<br>    USING ERRCODE = 'insufficient_privilege';<br>  END IF;<br><br>  -- Validation du montant<br>  IF p_amount <= 0 THEN<br>    RAISE EXCEPTION 'increment_balance: le montant doit être positif (reçu: %)', p_amount<br>    USING ERRCODE = 'check_violation';<br>  END IF;<br><br>  -- ✅ CORRECTION : UPSERT au lieu de simple UPDATE<br>  -- Si la ligne n'existe pas, on la crée avec un solde initial = p_amount<br>  -- Si elle existe, on incrémente simplement<br>  INSERT INTO user_balances (user_id, asset_symbol, available_balance, staking_balance, updated_at)<br>  VALUES (p_user_id, p_asset_symbol, p_amount, 0, now())<br>  ON CONFLICT (user_id, asset_symbol) <br>  DO UPDATE SET <br>    available_balance = user_balances.available_balance + p_amount,<br>    updated_at = now()<br>  RETURNING available_balance INTO new_balance;<br><br>  RETURN new_balance;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    |
| public      | initialize_asset_metrics            | p_asset_symbol text                                                                                                                                                               | void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.initialize_asset_metrics(p_asset_symbol text)<br> RETURNS void<br> LANGUAGE plpgsql<br>AS $function$<br>BEGIN<br>    INSERT INTO supported_assets_metrics (<br>        asset_symbol,<br>        total_deposited,<br>        total_withdrawn,<br>        total_user_balance,<br>        net_position,<br>        should_be_in_custody<br>    )<br>    VALUES (<br>        p_asset_symbol,<br>        0, 0, 0, 0, 0<br>    )<br>    ON CONFLICT (asset_symbol) DO NOTHING;<br>    <br>    RAISE NOTICE 'Metrics initialized for asset: %', p_asset_symbol;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 |
| public      | initialize_user_data                | p_user_id uuid                                                                                                                                                                    | void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.initialize_user_data(p_user_id uuid)<br> RETURNS void<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>BEGIN<br>  -- 1. Initialiser les balances pour les assets actifs<br>  INSERT INTO user_balances (user_id, asset_symbol, available_balance)<br>  SELECT <br>    p_user_id,<br>    sa.symbol,<br>    0<br>  FROM supported_assets sa<br>  WHERE sa.is_active = true<br>  ON CONFLICT (user_id, asset_symbol) <br>  DO UPDATE SET updated_at = NOW(); -- Juste mettre à jour le timestamp<br>  <br>  -- 2. Initialiser les multiplicateurs<br>  INSERT INTO user_active_multipliers (user_id, multiplier_value, spins_remaining)<br>  VALUES (p_user_id, 1, 0)<br>  ON CONFLICT (user_id) <br>  DO UPDATE SET updated_at = NOW();<br>  <br>  -- 3. Initialiser les limites de transaction<br>  INSERT INTO user_transaction_limits (user_id)<br>  VALUES (p_user_id)<br>  ON CONFLICT (user_id) <br>  DO NOTHING;<br>  <br>  -- 4. Journaliser<br>  INSERT INTO auth_logs (<br>    user_id,<br>    action,<br>    details,<br>    created_at<br>  ) VALUES (<br>    p_user_id,<br>    'data_initialized',<br>    jsonb_build_object('assets_initialized', (<br>      SELECT COUNT(*) FROM supported_assets WHERE is_active = true<br>    )),<br>    NOW()<br>  );<br>  <br>EXCEPTION<br>  WHEN OTHERS THEN<br>    -- Journaliser l'erreur mais ne pas bloquer<br>    INSERT INTO auth_logs (<br>      user_id,<br>      action,<br>      details,<br>      error_message,<br>      created_at<br>    ) VALUES (<br>      p_user_id,<br>      'data_initialization_error',<br>      '{}'::jsonb,<br>      SQLERRM,<br>      NOW()<br>    );<br>    <br>    RAISE NOTICE 'Erreur initialisation données pour user_id %: %', p_user_id, SQLERRM;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| public      | initiate_airtime_purchase           | p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text                                                                                                         | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.initiate_airtime_purchase(p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_balance_check boolean;<br>  v_limit_check record;<br>  v_tx_id uuid;<br>BEGIN<br>  -- 1. Vérifier le solde<br>  SELECT check_balance(p_user_id, 'FCFA', p_amount) INTO v_balance_check;<br>  IF NOT v_balance_check THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde FCFA insuffisant');<br>  END IF;<br><br>  -- 2. Vérifier les limites<br>  SELECT * INTO v_limit_check FROM check_transaction_limit(p_user_id, p_amount, 'withdraw');<br>  IF NOT v_limit_check.allowed THEN<br>    RETURN jsonb_build_object('success', false, 'error', v_limit_check.message);<br>  END IF;<br><br>  -- 3. Débiter le solde<br>  PERFORM decrement_balance(p_user_id, 'FCFA', p_amount);<br><br>  -- 4. Créer la transaction pending<br>  INSERT INTO transactions (<br>    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata<br>  ) VALUES (<br>    p_user_id, 'airtime_purchase', 'FCFA', p_amount, 0, p_amount, 'pending',<br>    jsonb_build_object(<br>      'external_reference', p_external_reference,<br>      'phone', p_phone,<br>      'provider', 'campay',<br>      'operation_type', 'airtime'<br>    )<br>  ) RETURNING id INTO v_tx_id;<br><br>  -- 5. Mettre à jour les limites<br>  UPDATE user_transaction_limits <br>  SET daily_withdraw_used = daily_withdraw_used + p_amount,<br>      monthly_withdraw_used = monthly_withdraw_used + p_amount,<br>      updated_at = now()<br>  WHERE user_id = p_user_id;<br><br>  RETURN jsonb_build_object(<br>    'success', true, <br>    'transaction_id', v_tx_id, <br>    'external_reference', p_external_reference<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    |
| public      | initiate_campay_deposit             | p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text, p_environment text                                                                                     | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.initiate_campay_deposit(p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text, p_environment text DEFAULT 'sandbox'::text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_tx_id uuid;<br>  v_min_deposit numeric;<br>  v_max_deposit numeric;<br>  v_cfg campay_config%ROWTYPE;<br>BEGIN<br>  SELECT * INTO v_cfg FROM campay_config WHERE id = 1;<br><br>  IF p_environment = 'production' THEN<br>    v_min_deposit := v_cfg.production_min_deposit;<br>    v_max_deposit := v_cfg.production_max_deposit;<br>  ELSE<br>    v_min_deposit := v_cfg.sandbox_min_deposit;<br>    v_max_deposit := v_cfg.sandbox_max_deposit;<br>  END IF;<br><br>  IF v_min_deposit IS NOT NULL AND p_amount < v_min_deposit THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'Montant minimum de dépôt : ' \|\| v_min_deposit \|\| ' FCFA',<br>      'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit<br>    );<br>  END IF;<br><br>  IF v_max_deposit IS NOT NULL AND p_amount > v_max_deposit THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'Montant maximum de dépôt : ' \|\| v_max_deposit \|\| ' FCFA',<br>      'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit<br>    );<br>  END IF;<br><br>  INSERT INTO transactions (<br>    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata<br>  ) VALUES (<br>    p_user_id, 'deposit', 'FCFA', p_amount, 0, p_amount, 'pending',<br>    jsonb_build_object(<br>      'external_reference', p_external_reference,<br>      'phone', p_phone,<br>      'provider', 'campay'<br>    )<br>  ) RETURNING id INTO v_tx_id;<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'transaction_id', v_tx_id,<br>    'external_reference', p_external_reference,<br>    'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                |
| public      | initiate_campay_deposit             | p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text                                                                                                         | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.initiate_campay_deposit(p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_tx_id uuid;<br>  v_min_deposit numeric;<br>  v_max_deposit numeric;<br>BEGIN<br>  SELECT active_min_deposit, active_max_deposit INTO v_min_deposit, v_max_deposit<br>  FROM v_active_campay_limits;<br><br>  IF v_min_deposit IS NOT NULL AND p_amount < v_min_deposit THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'Montant minimum de dépôt : ' \|\| v_min_deposit \|\| ' FCFA',<br>      'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit<br>    );<br>  END IF;<br><br>  IF v_max_deposit IS NOT NULL AND p_amount > v_max_deposit THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'Montant maximum de dépôt : ' \|\| v_max_deposit \|\| ' FCFA',<br>      'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit<br>    );<br>  END IF;<br><br>  INSERT INTO transactions (<br>    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata<br>  ) VALUES (<br>    p_user_id, 'deposit', 'FCFA', p_amount, 0, p_amount, 'pending',<br>    jsonb_build_object(<br>      'external_reference', p_external_reference,<br>      'phone', p_phone,<br>      'provider', 'campay'<br>    )<br>  ) RETURNING id INTO v_tx_id;<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'transaction_id', v_tx_id,<br>    'external_reference', p_external_reference,<br>    'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        |
| public      | initiate_campay_withdrawal          | p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text                                                                                                         | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.initiate_campay_withdrawal(p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_balance_check boolean;<br>  v_limit_check record;<br>  v_tx_id uuid;<br>  v_fee numeric;<br>  v_net_amount numeric;<br>  v_min_withdraw numeric;<br>BEGIN<br>  SELECT min_withdraw INTO v_min_withdraw FROM supported_assets WHERE symbol = 'FCFA';<br>  IF p_amount < v_min_withdraw THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant minimum de retrait : ' \|\| v_min_withdraw \|\| ' FCFA');<br>  END IF;<br><br>  SELECT check_balance(p_user_id, 'FCFA', p_amount) INTO v_balance_check;<br>  IF NOT v_balance_check THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde FCFA insuffisant');<br>  END IF;<br><br>  SELECT * INTO v_limit_check FROM check_transaction_limit(p_user_id, p_amount, 'withdraw');<br>  IF NOT v_limit_check.allowed THEN<br>    RETURN jsonb_build_object('success', false, 'error', v_limit_check.message);<br>  END IF;<br><br>  SELECT fee_amount, net_amount INTO v_fee, v_net_amount<br>  FROM calculate_fee('FCFA', p_amount, 'withdraw');<br><br>  IF v_net_amount <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant insuffisant pour couvrir le frais de retrait');<br>  END IF;<br><br>  PERFORM decrement_balance(p_user_id, 'FCFA', p_amount);<br><br>  INSERT INTO transactions (<br>    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata<br>  ) VALUES (<br>    p_user_id, 'withdrawal', 'FCFA', p_amount, v_fee, v_net_amount, 'pending',<br>    jsonb_build_object(<br>      'external_reference', p_external_reference,<br>      'phone', p_phone,<br>      'provider', 'campay'<br>    )<br>  ) RETURNING id INTO v_tx_id;<br><br>  UPDATE user_transaction_limits<br>  SET daily_withdraw_used = daily_withdraw_used + p_amount,<br>      monthly_withdraw_used = monthly_withdraw_used + p_amount,<br>      updated_at = now()<br>  WHERE user_id = p_user_id;<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'transaction_id', v_tx_id,<br>    'external_reference', p_external_reference,<br>    'fee', v_fee,<br>    'net_amount', v_net_amount<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | initiate_mobile_money_deposit       | p_user_id uuid, p_amount numeric, p_phone text, p_iso_code text, p_external_reference text                                                                                        | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.initiate_mobile_money_deposit(p_user_id uuid, p_amount numeric, p_phone text, p_iso_code text, p_external_reference text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_tx_id uuid;<br>  v_country payment_countries%ROWTYPE;<br>  v_msg text;<br>BEGIN<br>  SELECT pc.* INTO v_country<br>  FROM payment_countries pc<br>  JOIN payment_providers pp ON pp.code = pc.provider_code<br>  WHERE pc.iso_code = p_iso_code AND pc.is_active = true AND pp.is_active = true;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pays non disponible pour le depot');<br>  END IF;<br><br>  IF NOT v_country.deposit_enabled THEN<br>    SELECT message_fr INTO v_msg FROM payment_error_messages WHERE failure_code = 'DEPOSIT_DISABLED';<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', COALESCE(v_msg, 'Les dépôts sont momentanément suspendus pour ce pays.'),<br>      'failure_code', 'DEPOSIT_DISABLED'<br>    );<br>  END IF;<br><br>  IF v_country.wallet_asset_symbol IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Configuration incomplete pour ce pays (actif de portefeuille manquant)');<br>  END IF;<br><br>  IF v_country.min_deposit IS NOT NULL AND p_amount < v_country.min_deposit THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'Montant minimum de dépôt : ' \|\| v_country.min_deposit \|\| ' ' \|\| v_country.currency_code,<br>      'min_deposit', v_country.min_deposit, 'max_deposit', v_country.max_deposit<br>    );<br>  END IF;<br><br>  IF v_country.max_deposit IS NOT NULL AND p_amount > v_country.max_deposit THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'Montant maximum de dépôt : ' \|\| v_country.max_deposit \|\| ' ' \|\| v_country.currency_code,<br>      'min_deposit', v_country.min_deposit, 'max_deposit', v_country.max_deposit<br>    );<br>  END IF;<br><br>  INSERT INTO transactions (<br>    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata<br>  ) VALUES (<br>    p_user_id, 'deposit', v_country.wallet_asset_symbol, p_amount, 0, p_amount, 'pending',<br>    jsonb_build_object(<br>      'external_reference', p_external_reference,<br>      'phone', p_phone,<br>      'provider', v_country.provider_code,<br>      'country_iso', p_iso_code,<br>      'display_currency', v_country.currency_code<br>    )<br>  ) RETURNING id INTO v_tx_id;<br><br>  RETURN jsonb_build_object(<br>    'success', true,<br>    'transaction_id', v_tx_id,<br>    'external_reference', p_external_reference,<br>    'provider', v_country.provider_code,<br>    'currency', v_country.currency_code,<br>    'wallet_asset', v_country.wallet_asset_symbol,<br>    'min_deposit', v_country.min_deposit, 'max_deposit', v_country.max_deposit<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| public      | initiate_mobile_money_withdrawal    | p_user_id uuid, p_amount numeric, p_phone text, p_iso_code text, p_external_reference text                                                                                        | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.initiate_mobile_money_withdrawal(p_user_id uuid, p_amount numeric, p_phone text, p_iso_code text, p_external_reference text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_country payment_countries%ROWTYPE;<br>  v_fee numeric;<br>  v_net numeric;<br>  v_balance numeric;<br>  v_tx_id uuid;<br>  v_msg text;<br>BEGIN<br>  SELECT pc.* INTO v_country<br>  FROM payment_countries pc<br>  JOIN payment_providers pp ON pp.code = pc.provider_code<br>  WHERE pc.iso_code = p_iso_code AND pc.is_active = true AND pp.is_active = true;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Pays non disponible pour le retrait');<br>  END IF;<br><br>  IF NOT v_country.withdraw_enabled THEN<br>    SELECT message_fr INTO v_msg FROM payment_error_messages WHERE failure_code = 'WITHDRAW_DISABLED';<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', COALESCE(v_msg, 'Les retraits sont momentanément suspendus pour ce pays.'),<br>      'failure_code', 'WITHDRAW_DISABLED'<br>    );<br>  END IF;<br><br>  IF v_country.wallet_asset_symbol IS NULL THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Configuration incomplete pour ce pays');<br>  END IF;<br><br>  IF v_country.min_withdraw IS NOT NULL AND p_amount < v_country.min_withdraw THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'Montant minimum de retrait : ' \|\| v_country.min_withdraw \|\| ' ' \|\| v_country.currency_code,<br>      'min_withdraw', v_country.min_withdraw, 'max_withdraw', v_country.max_withdraw<br>    );<br>  END IF;<br><br>  IF v_country.max_withdraw IS NOT NULL AND p_amount > v_country.max_withdraw THEN<br>    RETURN jsonb_build_object(<br>      'success', false,<br>      'error', 'Montant maximum de retrait : ' \|\| v_country.max_withdraw \|\| ' ' \|\| v_country.currency_code,<br>      'min_withdraw', v_country.min_withdraw, 'max_withdraw', v_country.max_withdraw<br>    );<br>  END IF;<br><br>  -- [FIX 2026-09-19] Frais en pourcentage si configure (withdraw_fee_percentage),<br>  -- sinon on garde l'ancien comportement (montant fixe withdraw_fee) pour ne rien<br>  -- casser sur les pays/actifs pas encore bascules en %.<br>  IF v_country.withdraw_fee_percentage IS NOT NULL THEN<br>    v_fee := ROUND(p_amount * v_country.withdraw_fee_percentage / 100, 0);<br>  ELSE<br>    v_fee := COALESCE(v_country.withdraw_fee, 0);<br>  END IF;<br><br>  v_net := p_amount - v_fee;<br><br>  IF v_net <= 0 THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Montant insuffisant pour couvrir les frais de retrait');<br>  END IF;<br><br>  SELECT available_balance INTO v_balance<br>  FROM user_balances<br>  WHERE user_id = p_user_id AND asset_symbol = v_country.wallet_asset_symbol<br>  FOR UPDATE;<br><br>  IF v_balance IS NULL OR v_balance < p_amount THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant', 'available_balance', COALESCE(v_balance, 0));<br>  END IF;<br><br>  UPDATE user_balances<br>  SET available_balance = available_balance - p_amount, updated_at = now()<br>  WHERE user_id = p_user_id AND asset_symbol = v_country.wallet_asset_symbol;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, amount, fee, net_amount, status, metadata)<br>  VALUES (<br>    p_user_id, 'withdrawal', v_country.wallet_asset_symbol, p_amount, v_fee, v_net, 'pending',<br>    jsonb_build_object(<br>      'external_reference', p_external_reference, 'phone', p_phone, 'provider', v_country.provider_code,<br>      'country_iso', p_iso_code, 'display_currency', v_country.currency_code,<br>      'wallet_asset', v_country.wallet_asset_symbol, 'amount', p_amount<br>    )<br>  ) RETURNING id INTO v_tx_id;<br><br>  IF v_fee > 0 THEN<br>    PERFORM collect_fee_to_platform(v_country.wallet_asset_symbol, v_fee, 'withdraw_fee', p_user_id, v_tx_id);<br>  END IF;<br><br>  RETURN jsonb_build_object(<br>    'success', true, 'transaction_id', v_tx_id, 'provider', v_country.provider_code,<br>    'currency', v_country.currency_code, 'wallet_asset', v_country.wallet_asset_symbol,<br>    'fee', v_fee, 'net_amount', v_net<br>  );<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        |
| public      | log_transaction_error               | p_function_name text, p_error_message text, p_context jsonb                                                                                                                       | void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.log_transaction_error(p_function_name text, p_error_message text, p_context jsonb DEFAULT '{}'::jsonb)<br> RETURNS void<br> LANGUAGE plpgsql<br>AS $function$<br>BEGIN<br>    -- staking_system_logs a été supprimée.<br>    -- Les erreurs sont désormais visibles dans les Supabase Logs (RAISE LOG)<br>    -- et peuvent être capturées par un outil externe si besoin.<br>    RAISE LOG '[ERROR] function=% message=% context=%',<br>        p_function_name,<br>        p_error_message,<br>        p_context::text;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                |
| public      | process_user_deposit                | p_user_id uuid, p_asset_symbol text, p_network text, p_amount numeric, p_tx_hash text, p_onchain_address text                                                                     | TABLE(success boolean, message text, transaction_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                       | CREATE OR REPLACE FUNCTION public.process_user_deposit(p_user_id uuid, p_asset_symbol text, p_network text, p_amount numeric, p_tx_hash text, p_onchain_address text)<br> RETURNS TABLE(success boolean, message text, transaction_id uuid)<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_transaction_id uuid;<br>  v_asset_exists   boolean;<br>BEGIN<br>  IF current_role NOT IN ('service_role', 'postgres', 'supabase_admin') THEN<br>    RETURN QUERY SELECT false, 'Accès non autorisé : les dépôts sont traités uniquement par le système', NULL::uuid;<br>    RETURN;<br>  END IF;<br><br>  IF p_amount <= 0 THEN<br>    RETURN QUERY SELECT false, 'Montant invalide', NULL::uuid;<br>    RETURN;<br>  END IF;<br><br>  IF p_tx_hash IS NULL OR trim(p_tx_hash) = '' THEN<br>    RETURN QUERY SELECT false, 'tx_hash manquant', NULL::uuid;<br>    RETURN;<br>  END IF;<br><br>  IF EXISTS (<br>    SELECT 1 FROM transactions<br>    WHERE tx_hash = p_tx_hash AND type = 'deposit' AND status = 'completed'<br>  ) THEN<br>    RETURN QUERY SELECT false, 'Ce dépôt a déjà été traité (tx_hash en double)', NULL::uuid;<br>    RETURN;<br>  END IF;<br><br>  SELECT EXISTS (<br>    SELECT 1 FROM supported_assets WHERE symbol = p_asset_symbol AND network = p_network AND is_active = true<br>  ) INTO v_asset_exists;<br><br>  IF NOT v_asset_exists THEN<br>    RETURN QUERY SELECT false, 'Asset non supporté sur ce réseau', NULL::uuid;<br>    RETURN;<br>  END IF;<br><br>  IF EXISTS (<br>    SELECT 1 FROM supported_assets WHERE symbol = p_asset_symbol AND network = p_network AND can_be_deposited = false<br>  ) THEN<br>    RETURN QUERY SELECT false, 'Dépôts suspendus pour cet actif', NULL::uuid;<br>    RETURN;<br>  END IF;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, network, amount, status, tx_hash, metadata)<br>  VALUES (p_user_id, 'deposit', p_asset_symbol, p_network, p_amount, 'completed', p_tx_hash, jsonb_build_object('onchain_address', p_onchain_address))<br>  RETURNING id INTO v_transaction_id;<br><br>  INSERT INTO user_balances (user_id, asset_symbol, available_balance)<br>  VALUES (p_user_id, p_asset_symbol, p_amount)<br>  ON CONFLICT (user_id, asset_symbol) DO UPDATE SET<br>    available_balance = user_balances.available_balance + p_amount,<br>    total_deposited = COALESCE(user_balances.total_deposited, 0) + p_amount,<br>    updated_at = NOW();<br><br>  INSERT INTO notifications (user_id, type, title, message, data)<br>  VALUES (p_user_id, 'deposit_confirmed', 'Dépôt confirmé',<br>    format('Votre dépôt de %s %s a été confirmé', p_amount, p_asset_symbol),<br>    jsonb_build_object('transaction_id', v_transaction_id, 'amount', p_amount, 'asset', p_asset_symbol, 'tx_hash', p_tx_hash));<br><br>  PERFORM fn_award_engagement_points(p_user_id, 'deposit');<br><br>  RETURN QUERY SELECT true, 'Deposit processed successfully', v_transaction_id;<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN QUERY SELECT false, 'Erreur: ' \|\| SQLERRM, NULL::uuid;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | process_user_deposit_atomic         | p_address_id uuid, p_user_id uuid, p_asset_symbol text, p_network text, p_current_balance numeric, p_onchain_address text                                                         | TABLE(success boolean, message text, transaction_id uuid, deposit_amount numeric)                                                                                                                                                                                                                                                                                                                                                                                                                               | CREATE OR REPLACE FUNCTION public.process_user_deposit_atomic(p_address_id uuid, p_user_id uuid, p_asset_symbol text, p_network text, p_current_balance numeric, p_onchain_address text)<br> RETURNS TABLE(success boolean, message text, transaction_id uuid, deposit_amount numeric)<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_previous_balance numeric;<br>  v_deposit_amount numeric;<br>  v_transaction_id uuid;<br>  v_ledger_symbol text;<br>  v_tx_hash text;<br>BEGIN<br>  IF current_role NOT IN ('service_role', 'postgres', 'supabase_admin') THEN<br>    RETURN QUERY SELECT false, 'Accès non autorisé', NULL::uuid, 0::numeric;<br>    RETURN;<br>  END IF;<br><br>  SELECT cached_balance INTO v_previous_balance<br>  FROM user_addresses<br>  WHERE id = p_address_id<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN QUERY SELECT false, 'Adresse introuvable', NULL::uuid, 0::numeric;<br>    RETURN;<br>  END IF;<br><br>  v_deposit_amount := p_current_balance - COALESCE(v_previous_balance, 0);<br><br>  -- Dépôts suspendus pour cet actif : on ne crédite pas et on NE met PAS à jour cached_balance,<br>  -- pour que le dépôt soit détecté et crédité normalement à la réactivation.<br>  IF v_deposit_amount > 0.000001 AND EXISTS (<br>    SELECT 1 FROM supported_assets<br>    WHERE symbol = p_asset_symbol AND network = p_network AND can_be_deposited = false<br>  ) THEN<br>    RETURN QUERY SELECT false, 'Dépôts suspendus pour cet actif', NULL::uuid, 0::numeric;<br>    RETURN;<br>  END IF;<br><br>  UPDATE user_addresses<br>  SET cached_balance = p_current_balance, last_balance_check = NOW()<br>  WHERE id = p_address_id;<br><br>  IF v_deposit_amount <= 0.000001 THEN<br>    RETURN QUERY SELECT true, 'Rien à créditer', NULL::uuid, 0::numeric;<br>    RETURN;<br>  END IF;<br><br>  SELECT ledger_symbol INTO v_ledger_symbol<br>  FROM supported_assets<br>  WHERE symbol = p_asset_symbol AND network = p_network AND is_active = true;<br><br>  IF v_ledger_symbol IS NULL THEN<br>    RETURN QUERY SELECT false, 'Asset non supporté', NULL::uuid, 0::numeric;<br>    RETURN;<br>  END IF;<br><br>  v_tx_hash := 'scan_' \|\| p_address_id \|\| '_' \|\| COALESCE(v_previous_balance,0) \|\| '_' \|\| p_current_balance;<br><br>  IF EXISTS (SELECT 1 FROM transactions WHERE tx_hash = v_tx_hash AND type = 'deposit') THEN<br>    RETURN QUERY SELECT false, 'Doublon détecté et bloqué', NULL::uuid, 0::numeric;<br>    RETURN;<br>  END IF;<br><br>  INSERT INTO transactions (user_id, type, asset_symbol, network, amount, status, tx_hash, metadata)<br>  VALUES (p_user_id, 'deposit', v_ledger_symbol, p_network, v_deposit_amount, 'completed', v_tx_hash,<br>          jsonb_build_object('onchain_address', p_onchain_address, 'detection_method', 'balance_delta_atomic', 'source_symbol', p_asset_symbol))<br>  RETURNING id INTO v_transaction_id;<br><br>  INSERT INTO user_balances (user_id, asset_symbol, available_balance)<br>  VALUES (p_user_id, v_ledger_symbol, v_deposit_amount)<br>  ON CONFLICT (user_id, asset_symbol) DO UPDATE SET<br>    available_balance = user_balances.available_balance + v_deposit_amount,<br>    total_deposited = COALESCE(user_balances.total_deposited, 0) + v_deposit_amount,<br>    updated_at = NOW();<br><br>  INSERT INTO notifications (user_id, type, title, message, data)<br>  VALUES (p_user_id, 'deposit_confirmed', 'Dépôt confirmé',<br>    format('Votre dépôt de %s %s a été confirmé', v_deposit_amount, v_ledger_symbol),<br>    jsonb_build_object('transaction_id', v_transaction_id, 'amount', v_deposit_amount, 'asset', v_ledger_symbol));<br><br>  PERFORM fn_award_engagement_points(p_user_id, 'deposit');<br><br>  RETURN QUERY SELECT true, 'Deposit processed successfully', v_transaction_id, v_deposit_amount;<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN QUERY SELECT false, 'Erreur: ' \|\| SQLERRM, NULL::uuid, 0::numeric;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             |
| public      | recalculate_all_metrics             |                                                                                                                                                                                   | TABLE(asset text, calc_status text, message text)                                                                                                                                                                                                                                                                                                                                                                                                                                                               | CREATE OR REPLACE FUNCTION public.recalculate_all_metrics()<br> RETURNS TABLE(asset text, calc_status text, message text)<br> LANGUAGE plpgsql<br>AS $function$<br>DECLARE<br>    v_asset          RECORD;<br>    v_total_credits  numeric;<br>    v_total_debits   numeric;<br>    v_user_balances  numeric;<br>    v_net_position   numeric;<br>BEGIN<br>    FOR v_asset IN SELECT symbol FROM supported_assets WHERE is_active = true<br>    LOOP<br>        BEGIN<br>            SELECT COALESCE(SUM(<br>                CASE WHEN get_transaction_impact(t.type) = 'credit' THEN t.amount ELSE 0 END<br>            ), 0) INTO v_total_credits<br>            FROM transactions t<br>            WHERE t.asset_symbol = v_asset.symbol AND t.status = 'completed';<br><br>            SELECT COALESCE(SUM(<br>                CASE WHEN get_transaction_impact(t.type) = 'debit' THEN t.amount ELSE 0 END<br>            ), 0) INTO v_total_debits<br>            FROM transactions t<br>            WHERE t.asset_symbol = v_asset.symbol AND t.status = 'completed';<br><br>            -- lending_balance et collateral_balance supprimées<br>            SELECT COALESCE(SUM(available_balance + staking_balance), 0)<br>            INTO v_user_balances<br>            FROM user_balances<br>            WHERE asset_symbol = v_asset.symbol;<br><br>            v_net_position := GREATEST(v_total_credits - v_total_debits, 0);<br><br>            INSERT INTO supported_assets_metrics (<br>                asset_symbol, total_deposited, total_withdrawn,<br>                total_user_balance, net_position, should_be_in_custody, last_updated<br>            ) VALUES (<br>                v_asset.symbol, v_total_credits, v_total_debits,<br>                v_user_balances, v_net_position, v_user_balances, NOW()<br>            )<br>            ON CONFLICT (asset_symbol) DO UPDATE SET<br>                total_deposited    = EXCLUDED.total_deposited,<br>                total_withdrawn    = EXCLUDED.total_withdrawn,<br>                total_user_balance = EXCLUDED.total_user_balance,<br>                net_position       = EXCLUDED.net_position,<br>                should_be_in_custody = EXCLUDED.should_be_in_custody,<br>                last_updated       = NOW();<br><br>            RETURN QUERY SELECT v_asset.symbol, 'RECALCULATED',<br>                format('Credits: %s, Debits: %s, User Balances: %s',<br>                       v_total_credits, v_total_debits, v_user_balances);<br><br>        EXCEPTION WHEN OTHERS THEN<br>            RETURN QUERY SELECT v_asset.symbol, 'ERROR', format('Erreur: %s', SQLERRM);<br>        END;<br>    END LOOP;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      |
| public      | reconcile_user_balance              | p_user_id uuid, p_asset_symbol text                                                                                                                                               | TABLE(total_app_balance numeric, net_onchain_balance numeric, other_sources_balance numeric, is_balanced boolean)                                                                                                                                                                                                                                                                                                                                                                                               | CREATE OR REPLACE FUNCTION public.reconcile_user_balance(p_user_id uuid, p_asset_symbol text)<br> RETURNS TABLE(total_app_balance numeric, net_onchain_balance numeric, other_sources_balance numeric, is_balanced boolean)<br> LANGUAGE plpgsql<br>AS $function$<br>DECLARE<br>    v_total_app    numeric;<br>    v_deposited    numeric;<br>    v_withdrawn    numeric;<br>    v_net_onchain  numeric;<br>BEGIN<br>    SELECT COALESCE(available_balance, 0) + COALESCE(staking_balance, 0)<br>    INTO v_total_app<br>    FROM user_balances<br>    WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol;<br><br>    SELECT COALESCE(SUM(amount), 0) INTO v_deposited<br>    FROM transactions<br>    WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol<br>    AND type = 'deposit' AND status = 'completed';<br><br>    SELECT COALESCE(SUM(amount), 0) INTO v_withdrawn<br>    FROM transactions<br>    WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol<br>    AND type IN ('withdraw', 'withdrawal') AND status = 'completed';<br><br>    v_net_onchain := v_deposited - v_withdrawn;<br><br>    RETURN QUERY SELECT<br>        v_total_app,<br>        v_net_onchain,<br>        v_total_app - v_net_onchain,<br>        (v_total_app >= v_net_onchain);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               |
| public      | refresh_admin_asset_dashboard       |                                                                                                                                                                                   | void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.refresh_admin_asset_dashboard()<br> RETURNS void<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>BEGIN<br>  REFRESH MATERIALIZED VIEW CONCURRENTLY public.admin_asset_dashboard;<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           |
| public      | request_user_address                | p_user_id uuid, p_asset_symbol text                                                                                                                                               | TABLE(status text, id uuid, asset_symbol text, network text, address text, derivation_index integer, is_active boolean, cached_balance numeric, created_at timestamp with time zone)                                                                                                                                                                                                                                                                                                                            | CREATE OR REPLACE FUNCTION public.request_user_address(p_user_id uuid, p_asset_symbol text)<br> RETURNS TABLE(status text, id uuid, asset_symbol text, network text, address text, derivation_index integer, is_active boolean, cached_balance numeric, created_at timestamp with time zone)<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>#variable_conflict use_column<br>declare<br>  v_service_key text;<br>  v_request_id bigint;<br>  v_symbol text := upper(trim(p_asset_symbol));<br>begin<br>  if auth.uid() is distinct from p_user_id<br>     and coalesce(auth.role(), '') <> 'service_role' then<br>    raise exception 'Non autorisé';<br>  end if;<br><br>  return query<br>    select 'ready'::text, ua.id, ua.asset_symbol, ua.network, ua.address,<br>           ua.derivation_index, ua.is_active, ua.cached_balance, ua.created_at<br>    from public.user_addresses ua<br>    where ua.user_id = p_user_id and ua.asset_symbol = v_symbol<br>    limit 1;<br>  if found then return; end if;<br><br>  if exists (<br>    select 1 from public.pending_address_requests par<br>    where par.user_id = p_user_id and par.asset_symbol = v_symbol<br>      and par.created_at > now() - interval '2 minutes'<br>  ) then<br>    return query select 'pending'::text, null::uuid, v_symbol, null::text, null::text,<br>                        null::integer, null::boolean, null::numeric, null::timestamptz;<br>    return;<br>  end if;<br><br>  select decrypted_secret into v_service_key<br>  from vault.decrypted_secrets where name = 'service_role_key';<br>  if v_service_key is null then<br>    raise exception 'Configuration serveur invalide (clé service manquante)';<br>  end if;<br><br>  select net.http_post(<br>    url := 'https://jbzbwyuawejdhhutkmkk.supabase.co/functions/v1/generate-crypto-address',<br>    headers := jsonb_build_object(<br>      'Content-Type', 'application/json',<br>      'Authorization', 'Bearer ' \|\| v_service_key<br>    ),<br>    body := jsonb_build_object('asset_symbol', v_symbol, 'user_id', p_user_id)<br>  ) into v_request_id;<br><br>  insert into public.pending_address_requests (user_id, asset_symbol, request_id)<br>  values (p_user_id, v_symbol, v_request_id)<br>  on conflict (user_id, asset_symbol) do update<br>    set request_id = excluded.request_id, created_at = now();<br><br>  return query select 'pending'::text, null::uuid, v_symbol, null::text, null::text,<br>                      null::integer, null::boolean, null::numeric, null::timestamptz;<br>end;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       |
| public      | rollback_airtime_purchase           | p_external_reference text, p_amount numeric, p_reason text                                                                                                                        | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.rollback_airtime_purchase(p_external_reference text, p_amount numeric, p_reason text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_tx_id uuid;<br>  v_user_id uuid;<br>BEGIN<br>  SELECT id, user_id INTO v_tx_id, v_user_id<br>  FROM transactions<br>  WHERE metadata->>'external_reference' = p_external_reference<br>    AND type = 'airtime_purchase'<br>    AND status = 'pending'<br>  LIMIT 1;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Transaction non trouvée');<br>  END IF;<br><br>  -- Rembourser l'utilisateur<br>  PERFORM increment_balance(v_user_id, 'FCFA', p_amount);<br><br>  -- Restaurer les limites consommées à tort par la tentative échouée<br>  UPDATE user_transaction_limits<br>  SET daily_withdraw_used = GREATEST(0, daily_withdraw_used - p_amount),<br>      monthly_withdraw_used = GREATEST(0, monthly_withdraw_used - p_amount),<br>      updated_at = now()<br>  WHERE user_id = v_user_id;<br><br>  -- Marquer comme échoué<br>  UPDATE transactions <br>  SET status = 'failed',<br>      metadata = metadata \|\| jsonb_build_object('failure_reason', p_reason, 'rolled_back_at', now()),<br>      completed_at = now()<br>  WHERE id = v_tx_id;<br><br>  -- Notification<br>  INSERT INTO notifications (user_id, type, title, message, data)<br>  VALUES (<br>    v_user_id, 'airtime_failed', 'Achat de crédit annulé ❌', <br>    format('Votre achat de crédit a échoué. %s FCFA ont été remboursés.', p_amount),<br>    jsonb_build_object('amount', p_amount, 'reason', p_reason)<br>  );<br><br>  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id);<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            |
| public      | rollback_airtime_purchase           | p_reference_no text, p_amount numeric, p_currency text, p_reason text                                                                                                             | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.rollback_airtime_purchase(p_reference_no text, p_amount numeric, p_currency text, p_reason text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_tx_id uuid;<br>  v_user_id uuid;<br>BEGIN<br>  SELECT id, user_id INTO v_tx_id, v_user_id<br>  FROM transactions<br>  WHERE metadata->>'referenceNo' = p_reference_no<br>    AND type = 'airtime_purchase'<br>    AND status = 'pending'<br>  LIMIT 1;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Transaction non trouvée');<br>  END IF;<br><br>  -- Rembourser l'utilisateur<br>  PERFORM increment_balance(v_user_id, p_currency, p_amount);<br><br>  -- Marquer la transaction comme échouée<br>  UPDATE transactions <br>  SET status = 'failed',<br>      metadata = metadata \|\| jsonb_build_object('failure_reason', p_reason, 'rolled_back_at', now()),<br>      completed_at = now()<br>  WHERE id = v_tx_id;<br><br>  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    |
| public      | rollback_campay_withdrawal          | p_external_reference text, p_amount numeric, p_reason text                                                                                                                        | jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           | CREATE OR REPLACE FUNCTION public.rollback_campay_withdrawal(p_external_reference text, p_amount numeric, p_reason text)<br> RETURNS jsonb<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br>AS $function$<br>DECLARE<br>  v_tx_id uuid;<br>  v_user_id uuid;<br>BEGIN<br>  -- FOR UPDATE : sans ce verrou, deux callbacks FAILED simultanes peuvent tous<br>  -- deux lire 'pending' et rembourser l'utilisateur DEUX FOIS.<br>  SELECT id, user_id INTO v_tx_id, v_user_id<br>  FROM transactions<br>  WHERE metadata->>'external_reference' = p_external_reference<br>    AND type = 'withdrawal'<br>    AND status = 'pending'<br>  LIMIT 1<br>  FOR UPDATE;<br><br>  IF NOT FOUND THEN<br>    RETURN jsonb_build_object('success', false, 'error', 'Transaction de retrait non trouvée');<br>  END IF;<br><br>  -- Marquer comme echoue AVANT de rembourser : un appel concurrent en attente<br>  -- sur le verrou relira 'failed' et sortira proprement en NOT FOUND.<br>  UPDATE transactions<br>  SET status = 'failed',<br>      metadata = metadata \|\| jsonb_build_object('failure_reason', p_reason, 'rolled_back_at', now()),<br>      completed_at = now()<br>  WHERE id = v_tx_id;<br><br>  -- Rembourser l'utilisateur<br>  PERFORM increment_balance(v_user_id, 'FCFA', p_amount);<br><br>  -- Notification<br>  INSERT INTO notifications (user_id, type, title, message, data)<br>  VALUES (<br>    v_user_id, 'withdrawal_failed', 'Retrait annulé ❌',<br>    format('Votre retrait a échoué. %s FCFA ont été remboursés sur votre compte.', p_amount),<br>    jsonb_build_object('amount', p_amount, 'reason', p_reason)<br>  );<br><br>  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id);<br>EXCEPTION WHEN OTHERS THEN<br>  RETURN jsonb_build_object('success', false, 'error', SQLERRM);<br>END;<br>$function$<br>                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        |
